$makeFirstPage = static function (int $pageSize = 512, int $databaseSizePages = 1): string {
    $page = str_repeat("\0", $pageSize);
    $page = substr_replace($page, "SQLite format 3\0", 0, 16);
    $page = substr_replace($page, pack('n', $pageSize === 65536 ? 1 : $pageSize), 16, 2);
    $page[18] = "\x01";
    $page[19] = "\x01";
    $page[20] = "\x00";
    $page[21] = "\x40";
    $page[22] = "\x20";
    $page[23] = "\x20";
    $page = substr_replace($page, pack('N', $databaseSizePages), 28, 4);
    $page = substr_replace($page, pack('N', 1), 56, 4);

    return $page;
};

$varint = static function (int $value): string {
    return SQLiteVarint::encode($value);
};

$recordPayload = static function (array $values) use ($varint): string {
    $serialTypes = [];
    $body = '';
    foreach ($values as $value) {
        if ($value === null) {
            $serialTypes[] = 0;
        } elseif (is_int($value)) {
            if ($value === 0) {
                $serialTypes[] = 8;
            } elseif ($value === 1) {
                $serialTypes[] = 9;
            } elseif ($value >= -128 && $value <= 127) {
                $serialTypes[] = 1;
                $body .= pack('C', $value & 0xff);
            } elseif ($value >= -32768 && $value <= 32767) {
                $serialTypes[] = 2;
                $body .= pack('n', $value & 0xffff);
            } else {
                $serialTypes[] = 4;
                $body .= pack('N', $value & 0xffffffff);
            }
        } elseif (is_float($value)) {
            $serialTypes[] = 7;
            $body .= pack('E', $value);
        } elseif (is_array($value) && isset($value['__sqlite_blob']) && is_string($value['__sqlite_blob'])) {
            $serialTypes[] = 12 + (strlen($value['__sqlite_blob']) * 2);
            $body .= $value['__sqlite_blob'];
        } elseif (is_string($value)) {
            $serialTypes[] = 13 + (strlen($value) * 2);
            $body .= $value;
        } else {
            throw new RuntimeException('Unsupported fixture record value');
        }
    }

    $serialHeader = implode('', array_map($varint, $serialTypes));
    $headerSize = strlen($serialHeader) + 1;

    return $varint($headerSize) . $serialHeader . $body;
};

$blobValue = static fn (string $bytes): array => ['__sqlite_blob' => $bytes];

$schemaCell = static function (array $values, int $rowId) use ($varint, $recordPayload): string {
    $payload = $recordPayload($values);

    return $varint(strlen($payload)) . $varint($rowId) . $payload;
};

$tableLeafPage = static function (array $cells, int $pageSize = 512, int $headerOffset = 0, ?string $basePage = null): string {
    $page = $basePage ?? str_repeat("\0", $pageSize);
    $cellCount = count($cells);
    $offset = $pageSize;
    $pointers = [];

    foreach ($cells as $cell) {
        $offset -= strlen($cell);
        if ($offset < $headerOffset + 8 + ($cellCount * 2)) {
            throw new RuntimeException('Fixture table leaf page has overlapping cells');
        }
        $page = substr_replace($page, $cell, $offset, strlen($cell));
        $pointers[] = $offset;
    }

    $page[$headerOffset] = "\x0d";
    $page = substr_replace($page, pack('n', 0), $headerOffset + 1, 2);
    $page = substr_replace($page, pack('n', $cellCount), $headerOffset + 3, 2);
    $contentStart = $cellCount === 0 ? $pageSize : min($pointers);
    $page = substr_replace($page, pack('n', $contentStart === 65536 ? 0 : $contentStart), $headerOffset + 5, 2);
    $page[$headerOffset + 7] = "\x00";

    foreach ($pointers as $index => $pointer) {
        $page = substr_replace($page, pack('n', $pointer), $headerOffset + 8 + ($index * 2), 2);
    }

    return $page;
};

$tableInteriorPage = static function (array $cells, int $rightMostPage, int $pageSize = 512, int $headerOffset = 0, ?string $basePage = null) use ($varint): string {
    $page = $basePage ?? str_repeat("\0", $pageSize);
    $cellCount = count($cells);
    $offset = $pageSize;
    $pointers = [];

    foreach ($cells as [$leftChildPage, $key]) {
        $cell = pack('N', $leftChildPage) . $varint($key);
        $offset -= strlen($cell);
        if ($offset < $headerOffset + 12 + ($cellCount * 2)) {
            throw new RuntimeException('Fixture table interior page has overlapping cells');
        }
        $page = substr_replace($page, $cell, $offset, strlen($cell));
        $pointers[] = $offset;
    }

    $page[$headerOffset] = "\x05";
    $page = substr_replace($page, pack('n', 0), $headerOffset + 1, 2);
    $page = substr_replace($page, pack('n', $cellCount), $headerOffset + 3, 2);
    $contentStart = $cellCount === 0 ? $pageSize : min($pointers);
    $page = substr_replace($page, pack('n', $contentStart === 65536 ? 0 : $contentStart), $headerOffset + 5, 2);
    $page[$headerOffset + 7] = "\x00";
    $page = substr_replace($page, pack('N', $rightMostPage), $headerOffset + 8, 4);

    foreach ($pointers as $index => $pointer) {
        $page = substr_replace($page, pack('n', $pointer), $headerOffset + 12 + ($index * 2), 2);
    }

    return $page;
};

$indexCell = static function (array $values) use ($varint, $recordPayload): string {
    $payload = $recordPayload($values);

    return $varint(strlen($payload)) . $payload;
};

$indexLeafPage = static function (array $cells, int $pageSize = 512, int $headerOffset = 0, ?string $basePage = null): string {
    $page = $basePage ?? str_repeat("\0", $pageSize);
    $cellCount = count($cells);
    $offset = $pageSize;
    $pointers = [];

    foreach ($cells as $cell) {
        $offset -= strlen($cell);
        if ($offset < $headerOffset + 8 + ($cellCount * 2)) {
            throw new RuntimeException('Fixture index leaf page has overlapping cells');
        }
        $page = substr_replace($page, $cell, $offset, strlen($cell));
        $pointers[] = $offset;
    }

    $page[$headerOffset] = "\x0a";
    $page = substr_replace($page, pack('n', 0), $headerOffset + 1, 2);
    $page = substr_replace($page, pack('n', $cellCount), $headerOffset + 3, 2);
    $contentStart = $cellCount === 0 ? $pageSize : min($pointers);
    $page = substr_replace($page, pack('n', $contentStart === 65536 ? 0 : $contentStart), $headerOffset + 5, 2);
    $page[$headerOffset + 7] = "\x00";

    foreach ($pointers as $index => $pointer) {
        $page = substr_replace($page, pack('n', $pointer), $headerOffset + 8 + ($index * 2), 2);
    }

    return $page;
};

$indexInteriorPage = static function (array $cells, int $rightMostPage, int $pageSize = 512, int $headerOffset = 0, ?string $basePage = null) use ($indexCell): string {
    $page = $basePage ?? str_repeat("\0", $pageSize);
    $cellCount = count($cells);
    $offset = $pageSize;
    $pointers = [];

    foreach ($cells as [$leftChildPage, $values]) {
        $cell = pack('N', $leftChildPage) . $indexCell($values);
        $offset -= strlen($cell);
        if ($offset < $headerOffset + 12 + ($cellCount * 2)) {
            throw new RuntimeException('Fixture index interior page has overlapping cells');
        }
        $page = substr_replace($page, $cell, $offset, strlen($cell));
        $pointers[] = $offset;
    }

    $page[$headerOffset] = "\x02";
    $page = substr_replace($page, pack('n', 0), $headerOffset + 1, 2);
    $page = substr_replace($page, pack('n', $cellCount), $headerOffset + 3, 2);
    $contentStart = $cellCount === 0 ? $pageSize : min($pointers);
    $page = substr_replace($page, pack('n', $contentStart === 65536 ? 0 : $contentStart), $headerOffset + 5, 2);
    $page[$headerOffset + 7] = "\x00";
    $page = substr_replace($page, pack('N', $rightMostPage), $headerOffset + 8, 4);

    foreach ($pointers as $index => $pointer) {
        $page = substr_replace($page, pack('n', $pointer), $headerOffset + 12 + ($index * 2), 2);
    }

    return $page;
};

$overflowLeafCell = static function (string $payload, int $rowId, int $firstOverflowPage, int $usableSize = 512) use ($varint): array {
    $localLength = SQLiteTableLeafCell::localPayloadLength(strlen($payload), $usableSize);

    return [
        $varint(strlen($payload)) . $varint($rowId) . substr($payload, 0, $localLength) . pack('N', $firstOverflowPage),
        substr($payload, $localLength),
        $localLength,
    ];
};

$overflowPage = static function (string $payload, int $nextPage = 0, int $pageSize = 512): string {
    if (strlen($payload) > $pageSize - 4) {
        throw new RuntimeException('Fixture overflow payload does not fit on one page');
    }

    $page = str_repeat("\0", $pageSize);
    $page = substr_replace($page, pack('N', $nextPage), 0, 4);

    return substr_replace($page, $payload, 4, strlen($payload));
};

return [
    'parses core sqlite database header fields' => static function (TestRunner $t): void {
        $header = str_repeat("\0", 100);
        $header = substr_replace($header, "SQLite format 3\0", 0, 16);
        $header = substr_replace($header, pack('n', 4096), 16, 2);
        $header[18] = "\x01";
        $header[19] = "\x01";
        $header[20] = "\x00";
        $header = substr_replace($header, pack('N', 123), 24, 4);
        $header = substr_replace($header, pack('N', 2), 28, 4);
        $header = substr_replace($header, pack('N', 17), 40, 4);
        $header = substr_replace($header, pack('N', 1), 56, 4);
        $header = substr_replace($header, pack('N', 9), 60, 4);
        $header = substr_replace($header, pack('N', 0x57503100), 68, 4);
        $parsed = SQLiteHeader::parse($header);
        $t->same(4096, $parsed->pageSize);
        $t->same(1, $parsed->writeVersion);
        $t->same(2, $parsed->databaseSizePages);
        $t->same(0, $parsed->firstFreelistTrunkPage);
        $t->same(0, $parsed->freelistPageCount);
        $t->same(17, $parsed->schemaCookie);
        $t->same(0, $parsed->largestRootBtreePage);
        $t->same(1, $parsed->textEncoding);
        $t->same(9, $parsed->userVersion);
        $t->same(0, $parsed->incrementalVacuum);
        $t->same(0x57503100, $parsed->applicationId);
        $t->same(123, $parsed->fileChangeCounter);
    },
    'reports application copy preflight pragma metadata from sqlite headers' => static function (TestRunner $t) use ($makeFirstPage): void {
        $firstPage = $makeFirstPage(1024, 4);
        $firstPage[18] = "\x02";
        $firstPage[19] = "\x02";
        $firstPage = substr_replace($firstPage, pack('N', 77), 24, 4);
        $firstPage = substr_replace($firstPage, pack('N', 3), 32, 4);
        $firstPage = substr_replace($firstPage, pack('N', 5), 36, 4);
        $firstPage = substr_replace($firstPage, pack('N', 19), 40, 4);
        $firstPage = substr_replace($firstPage, pack('N', 8), 52, 4);
        $firstPage = substr_replace($firstPage, pack('N', 2), 56, 4);
        $firstPage = substr_replace($firstPage, pack('N', 14), 60, 4);
        $firstPage = substr_replace($firstPage, pack('N', 1), 64, 4);
        $firstPage = substr_replace($firstPage, pack('N', 0x57505351), 68, 4);

        $snapshot = SQLitePragmaSnapshot::fromDatabase(SQLiteDatabase::fromBytes($firstPage . str_repeat("\0", 1024 * 3)));

        $t->same(1024, $snapshot->value('page_size'));
        $t->same(4, $snapshot->value('page-count'));
        $t->same(5, $snapshot->value('freelist_count'));
        $t->same('UTF-16le', $snapshot->value('encoding'));
        $t->same('wal', $snapshot->value('journal_mode'));
        $t->same('normal', $snapshot->value('locking_mode'));
        $t->same('incremental', $snapshot->value('auto_vacuum'));
        $t->same(1, $snapshot->value('incremental_vacuum'));
        $t->same(0x57505351, $snapshot->value('application_id'));
        $t->same(14, $snapshot->value('user_version'));
        $t->same(19, $snapshot->value('schema_version'));
        $t->same(77, $snapshot->value('data_version'));
        $t->same(null, $snapshot->value('missing'));
        $t->same([
            'page_size' => 1024,
            'journal_mode' => 'wal',
            'locking_mode' => 'normal',
            'auto_vacuum' => 'incremental',
        ], $snapshot->toArray(['page-size', 'journal_mode', 'locking-mode', 'auto_vacuum', 'missing']));

        $plain = SQLitePragmaSnapshot::fromDatabase(SQLiteDatabase::fromBytes($makeFirstPage(512, 1)));
        $t->same('delete', $plain->value('journal_mode'));
        $t->same('normal', $plain->value('locking_mode'));
        $t->same('none', $plain->value('auto_vacuum'));
        $t->same('UTF-8', $plain->value('encoding'));
        $t->same(0, $plain->value('incremental_vacuum'));
    },
    'executes current PRAGMA locking_mode state for application copy connections' => static function (TestRunner $t): void {
        $pragma = new SQLitePragmaLockingMode();

        $initial = $pragma->execute('PRAGMA locking_mode');
        $t->same('ok', $initial['status']);
        $t->same('locking_mode', $initial['pragma']);
        $t->same('main', $initial['schema']);
        $t->same(null, $initial['requested_mode']);
        $t->same('normal', $initial['locking_mode']);
        $t->same(false, $initial['changed']);
        $t->same([['locking_mode' => 'normal']], $initial['rows']);
        $t->same('normal', $pragma->current());

        $hyphenQuery = $pragma->execute(" PRAGMA locking_mode; \n");
        $t->same('normal', $hyphenQuery['locking_mode']);
        $t->same([['locking_mode' => 'normal']], $hyphenQuery['rows']);

        $exclusive = $pragma->execute('PRAGMA locking_mode = EXCLUSIVE');
        $t->same('main', $exclusive['schema']);
        $t->same('exclusive', $exclusive['requested_mode']);
        $t->same('exclusive', $exclusive['locking_mode']);
        $t->true($exclusive['changed']);
        $t->same([['locking_mode' => 'exclusive']], $exclusive['rows']);
        $t->same('exclusive', $pragma->current());
        $t->same('exclusive', $pragma->current('main'));
        $t->same('exclusive', $pragma->execute('PRAGMA main.locking_mode')['locking_mode']);

        $sameExclusive = $pragma->execute('PRAGMA main.locking_mode(exclusive)');
        $t->same('exclusive', $sameExclusive['locking_mode']);
        $t->same(false, $sameExclusive['changed']);
        $t->same('exclusive', $sameExclusive['rows'][0]['locking_mode']);

        $normal = $pragma->execute('PRAGMA MAIN.locking_mode=NORMAL');
        $t->same('main', $normal['schema']);
        $t->same('normal', $normal['requested_mode']);
        $t->same('normal', $normal['locking_mode']);
        $t->true($normal['changed']);
        $t->same('normal', $pragma->current());

        $invalidMode = $pragma->execute('PRAGMA locking_mode = invalid_mode');
        $t->same('invalid_mode', $invalidMode['requested_mode']);
        $t->same('normal', $invalidMode['locking_mode']);
        $t->same(false, $invalidMode['changed']);
        $t->same('normal', $pragma->current());

        $temp = $pragma->execute('PRAGMA temp.locking_mode');
        $t->same('temp', $temp['schema']);
        $t->same('exclusive', $temp['locking_mode']);
        $t->same(false, $temp['changed']);
        $t->same([['locking_mode' => 'exclusive']], $temp['rows']);
        $t->same('exclusive', $pragma->current('temp'));

        $tempNormal = $pragma->execute('PRAGMA temp.locking_mode = normal');
        $t->same('normal', $tempNormal['requested_mode']);
        $t->same('exclusive', $tempNormal['locking_mode']);
        $t->same(false, $tempNormal['changed']);
        $t->same('normal', $pragma->current('main'));

        $attached = $pragma->execute('PRAGMA wp.locking_mode = exclusive');
        $t->same('wp', $attached['schema']);
        $t->same('exclusive', $attached['locking_mode']);
        $t->true($attached['changed']);
        $t->same('normal', $pragma->current('main'));
        $t->same('exclusive', $pragma->execute('PRAGMA wp.locking_mode')['locking_mode']);
        $t->same('normal', $pragma->execute('PRAGMA locking_mode')['locking_mode']);

        $attachedNormal = $pragma->execute('PRAGMA wp.locking_mode(normal)');
        $t->same('wp', $attachedNormal['schema']);
        $t->same('normal', $attachedNormal['locking_mode']);
        $t->true($attachedNormal['changed']);
        $t->same('normal', $pragma->current());
        $t->same('normal', $pragma->current('wp'));

        $t->throws(InvalidArgumentException::class, static fn () => $pragma->execute('PRAGMA journal_mode'));
        $t->throws(InvalidArgumentException::class, static fn () => $pragma->execute('SELECT PRAGMA locking_mode'));
    },
    'parses sqlite database freelist header fields' => static function (TestRunner $t): void {
        $header = str_repeat("\0", 100);
        $header = substr_replace($header, "SQLite format 3\0", 0, 16);
        $header = substr_replace($header, pack('n', 1024), 16, 2);
        $header[18] = "\x01";
        $header[19] = "\x01";
        $header = substr_replace($header, pack('N', 8), 28, 4);
        $header = substr_replace($header, pack('N', 5), 32, 4);
        $header = substr_replace($header, pack('N', 4), 36, 4);
        $header = substr_replace($header, pack('N', 1), 56, 4);

        $parsed = SQLiteHeader::parse($header);

        $t->same(5, $parsed->firstFreelistTrunkPage);
        $t->same(4, $parsed->freelistPageCount);
    },
    'parses sqlite auto-vacuum pointer map entries for application pages' => static function (TestRunner $t) use ($makeFirstPage, $schemaCell, $tableLeafPage, $overflowPage): void {
        $pageSize = 512;
        $schemaPage = SQLiteTableLeafPage::assemble([
            $schemaCell([
                'table',
                'app_settings',
                'app_settings',
                3,
                'CREATE TABLE app_settings(setting_id integer primary key, key_name text, key_value text, load_policy text)',
            ], 1),
        ], $pageSize, 100, $makeFirstPage($pageSize, 7));
        $schemaPage = substr_replace($schemaPage, pack('N', 3), 52, 4);
        $schemaPage = substr_replace($schemaPage, pack('N', 1), 64, 4);

        $pointerMapPage = str_repeat("\0", $pageSize);
        foreach ([
