            . $emptyPage
            . $emptyPage
            . $emptyPage
            . $emptyPage,
        );

        $plan = $database->planPageFreeList([4, 5], true);
        $postPages = [];
        for ($pageNumber = 1; $pageNumber <= 8; $pageNumber++) {
            $postPages[$pageNumber] = $database->page($pageNumber);
        }
