            $pages[$pageNumber] = $database->page($pageNumber);
        }
        foreach ($application->pageImages as $pageNumber => $page) {
            $pages[$pageNumber] = $page;
        }
        $postDatabase = SQLiteDatabase::fromBytes(implode('', $pages));
