        $t->same([12, 13], $plan->rightKeys);
        $t->same(2, count($plan->leftCells));
        $t->same(2, count($plan->rightCells));
        $t->same([3 => $plan->leftPage, 4 => $plan->rightPage], $plan->pageImages());
