        $t->throws(InvalidArgumentException::class, static fn () => $database->keyValueRowsByIndexedNameRangeWithPrefixAndCollation(['load_policy' => 'no'], 'cache-a', 'cache-c', 'WPSLUG', static fn (): string => '0'));
