            ['column' => 'key', 'operator' => 'IN', 'value' => ['priority', 'missing']],
            ['column' => 'atom', 'operator' => 'BETWEEN', 'value' => [3, 7]],
            ['column' => 'fullkey', 'operator' => 'LIKE', 'value' => '$.plugin.rules[%].priority'],
        ];

