        $t->throws(InvalidArgumentException::class, static fn () => SQLiteJsonTablePlan::hostJoinRows($hostRows, 'key_value', 'json_tree', [
            ['column' => 'root', 'operator' => '=', 'value' => '$.plugin[#-]'],
