    'plans sqlite incremental-vacuum tail truncation from freelist trunks and leaves' => static function (TestRunner $t) use ($makeFirstPage): void {
        $emptyPage = str_repeat("\0", 512);
        $firstPage = $makeFirstPage(512, 10);
