    'parses sqlite wal headers and committed frame page images' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x01020304;
        $salt2 = 0x05060708;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 7, $salt1, $salt2, 0x11111111, 0x22222222);
        $pageOne = $makeFirstPage($pageSize, 2);
        $pageTwo = str_repeat('W', $pageSize);
        $pageThree = str_repeat('U', $pageSize);
        $walBytes = $walHeader
            . pack('N*', 1, 0, $salt1, $salt2, 0xaaaa0001, 0xbbbb0001) . $pageOne
            . pack('N*', 2, 2, $salt1, $salt2, 0xaaaa0002, 0xbbbb0002) . $pageTwo
            . pack('N*', 3, 0, $salt1, $salt2, 0xaaaa0003, 0xbbbb0003) . $pageThree;

        $wal = SQLiteWal::parse($walBytes);

        $t->same(SQLiteWal::class, get_class($wal));
        $t->same(SQLiteWalHeader::class, get_class($wal->header));
        $t->same(3, $wal->frameCount());
        $t->same('big-endian', $wal->header->byteOrder());
        $t->same([
            'magic' => SQLiteWalHeader::MAGIC_BIG_ENDIAN,
            'format_version' => 3007000,
            'page_size' => 512,
            'checkpoint_sequence' => 7,
            'salt1' => $salt1,
            'salt2' => $salt2,
            'checksum1' => 0x11111111,
            'checksum2' => 0x22222222,
            'byte_order' => 'big-endian',
        ], $wal->header->toArray());
        $lastCommitFrame = $wal->lastCommitFrame();
        $t->same(SQLiteWalFrame::class, get_class($lastCommitFrame));
        $t->same(2, $lastCommitFrame->index);
        $t->same(2, $lastCommitFrame->pageNumber);
        $t->same(true, $lastCommitFrame->isCommitFrame());
        $t->same([1, 2], array_keys($wal->pageImagesThroughLastCommit()));
        $t->same($pageOne, $wal->pageImagesThroughLastCommit()[1]);
        $t->same($pageTwo, $wal->pageImagesThroughLastCommit()[2]);
        $t->same([
            [
                'first_frame' => 1,
                'last_frame' => 2,
                'database_page_count' => 2,
                'page_numbers' => [1, 2],
            ],
        ], $wal->committedTransactions());
        $t->same(1, $wal->uncommittedFrameCount());
        $baseDatabase = $makeFirstPage($pageSize, 3) . str_repeat('B', $pageSize) . str_repeat('C', $pageSize);
        $checkpointDatabase = $wal->checkpointDatabaseImage($baseDatabase);
        $t->same($pageSize * 2, strlen($checkpointDatabase));
        $t->same($pageOne, substr($checkpointDatabase, 0, $pageSize));
        $t->same($pageTwo, substr($checkpointDatabase, $pageSize, $pageSize));
        $t->same(false, str_contains($checkpointDatabase, 'U'));
        $t->same([
            'header' => $wal->header->toArray(),
            'frame_count' => 3,
            'checksums_validated' => false,
            'committed_transactions' => [
                [
                    'first_frame' => 1,
                    'last_frame' => 2,
                    'database_page_count' => 2,
                    'page_numbers' => [1, 2],
                ],
            ],
            'uncommitted_frame_count' => 1,
            'committed_page_numbers' => [1, 2],
            'last_commit_frame' => $lastCommitFrame->toArray(),
        ], $wal->toArray());
    },
    'summarizes sqlite wal committed transaction boundaries' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x11111111;
        $salt2 = 0x22222222;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 3, $salt1, $salt2, 0x33333333, 0x44444444);
        $pageOne = $makeFirstPage($pageSize, 3);
        $pageTwoA = str_repeat('A', $pageSize);
        $pageTwoB = str_repeat('B', $pageSize);
        $pageThree = str_repeat('C', $pageSize);
        $tailPage = str_repeat('T', $pageSize);
        $walBytes = $walHeader
            . pack('N*', 1, 0, $salt1, $salt2, 0, 0) . $pageOne
            . pack('N*', 2, 2, $salt1, $salt2, 0, 0) . $pageTwoA
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $pageTwoB
            . pack('N*', 3, 3, $salt1, $salt2, 0, 0) . $pageThree
            . pack('N*', 1, 0, $salt1, $salt2, 0, 0) . $tailPage;

        $wal = SQLiteWal::parse($walBytes);

        $t->same([
            [
                'first_frame' => 1,
                'last_frame' => 2,
                'database_page_count' => 2,
                'page_numbers' => [1, 2],
            ],
            [
                'first_frame' => 3,
                'last_frame' => 4,
                'database_page_count' => 3,
                'page_numbers' => [2, 3],
            ],
        ], $wal->committedTransactions());
        $t->same(1, $wal->uncommittedFrameCount());
        $t->same([1, 2, 3], array_keys($wal->pageImagesThroughLastCommit()));
        $t->same($pageOne, $wal->pageImagesThroughLastCommit()[1]);
        $t->same($pageTwoB, $wal->pageImagesThroughLastCommit()[2]);
        $t->same($pageThree, $wal->pageImagesThroughLastCommit()[3]);

        $emptyWal = SQLiteWal::parse($walHeader);
        $t->same([], $emptyWal->committedTransactions());
        $t->same(0, $emptyWal->uncommittedFrameCount());

        $uncommittedWal = SQLiteWal::parse(
            $walHeader . pack('N*', 1, 0, $salt1, $salt2, 0, 0) . $pageOne
        );
        $t->same([], $uncommittedWal->committedTransactions());
        $t->same(1, $uncommittedWal->uncommittedFrameCount());
    },
    'plans sqlite wal checkpoint frame application diagnostics' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x21212121;
        $salt2 = 0x34343434;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 5, $salt1, $salt2, 0, 0);
        $baseDatabase = $makeFirstPage($pageSize, 4)
            . str_repeat('B', $pageSize)
            . str_repeat('C', $pageSize)
            . str_repeat('D', $pageSize);
        $pageTwoOld = str_repeat('o', $pageSize);
        $pageTwoNew = str_repeat('n', $pageSize);
        $pageThree = str_repeat('3', $pageSize);
        $pageFive = str_repeat('5', $pageSize);
        $tailPage = str_repeat('t', $pageSize);
        $walBytes = $walHeader
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $pageTwoOld
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $pageTwoNew
            . pack('N*', 3, 4, $salt1, $salt2, 0, 0) . $pageThree
            . pack('N*', 5, 4, $salt1, $salt2, 0, 0) . $pageFive
            . pack('N*', 4, 0, $salt1, $salt2, 0, 0) . $tailPage;

        $wal = SQLiteWal::parse($walBytes);

        $t->same([
            'database_page_count' => 4,
            'final_database_bytes' => 2048,
            'last_commit_frame' => 4,
            'frames' => [
                [
                    'frame_index' => 1,
                    'page_number' => 2,
                    'database_offset' => 512,
                    'applied' => false,
                    'reason' => 'superseded_by_later_committed_frame',
                ],
                [
                    'frame_index' => 2,
                    'page_number' => 2,
                    'database_offset' => 512,
                    'applied' => true,
                    'reason' => 'checkpointed_to_database',
                ],
                [
                    'frame_index' => 3,
                    'page_number' => 3,
                    'database_offset' => 1024,
                    'applied' => true,
                    'reason' => 'checkpointed_to_database',
                ],
                [
                    'frame_index' => 4,
                    'page_number' => 5,
                    'database_offset' => 2048,
                    'applied' => false,
                    'reason' => 'beyond_committed_database_size',
                ],
                [
                    'frame_index' => 5,
                    'page_number' => 4,
                    'database_offset' => 1536,
                    'applied' => false,
                    'reason' => 'after_last_commit',
                ],
            ],
        ], $wal->checkpointPlan($baseDatabase));

        $checkpointed = $wal->checkpointDatabaseImage($baseDatabase);
        $t->same($pageTwoNew, substr($checkpointed, 512, $pageSize));
        $t->same($pageThree, substr($checkpointed, 1024, $pageSize));
        $t->same(str_repeat('D', $pageSize), substr($checkpointed, 1536, $pageSize));
        $t->same(2048, strlen($checkpointed));
        $t->same('', substr($checkpointed, 2048, $pageSize));

        $emptyWal = SQLiteWal::parse($walHeader);
        $t->same([
            'database_page_count' => 4,
            'final_database_bytes' => 2048,
            'last_commit_frame' => null,
            'frames' => [],
        ], $emptyWal->checkpointPlan($baseDatabase));

        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointPlan(substr($baseDatabase, 1)));
    },
    'plans sqlite wal reset and truncation eligibility after checkpoint' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0xffffffff;
        $salt2 = 0x12121212;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 8, $salt1, $salt2, 0, 0);
        $baseDatabase = $makeFirstPage($pageSize, 2) . str_repeat('B', $pageSize);
        $pageTwo = str_repeat('2', $pageSize);
        $tailPage = str_repeat('T', $pageSize);

        $committedWal = SQLiteWal::parse(
            $walHeader
            . pack('N*', 2, 2, $salt1, $salt2, 0, 0) . $pageTwo
        );
        $t->same([
            'can_reset' => true,
            'action' => 'truncate_or_restart_wal',
            'reason' => 'all_committed_frames_checkpointed',
            'checkpointed_frame_count' => 1,
            'uncommitted_frame_count' => 0,
            'last_commit_frame' => 1,
            'next_wal_header_salt' => [0, $salt2],
        ], $committedWal->resetPlan($baseDatabase));

        $tailWal = SQLiteWal::parse(
            $walHeader
            . pack('N*', 2, 2, $salt1, $salt2, 0, 0) . $pageTwo
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $tailPage
        );
        $t->same([
            'can_reset' => false,
            'action' => 'preserve_wal_tail',
            'reason' => 'uncommitted_frames_after_last_commit',
            'checkpointed_frame_count' => 1,
            'uncommitted_frame_count' => 1,
            'last_commit_frame' => 1,
            'next_wal_header_salt' => [0, $salt2],
        ], $tailWal->resetPlan($baseDatabase));

        $uncommittedWal = SQLiteWal::parse(
            $walHeader
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $tailPage
        );
        $t->same([
            'can_reset' => false,
            'action' => 'preserve_uncommitted_wal',
            'reason' => 'no_committed_transaction',
            'checkpointed_frame_count' => 0,
            'uncommitted_frame_count' => 1,
            'last_commit_frame' => null,
            'next_wal_header_salt' => [0, $salt2],
        ], $uncommittedWal->resetPlan($baseDatabase));

        $emptyWal = SQLiteWal::parse($walHeader);
        $t->same([
            'can_reset' => true,
            'action' => 'leave_empty_wal',
            'reason' => 'wal_has_no_frames',
            'checkpointed_frame_count' => 0,
            'uncommitted_frame_count' => 0,
            'last_commit_frame' => null,
            'next_wal_header_salt' => [0, $salt2],
        ], $emptyWal->resetPlan($baseDatabase));

        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->resetPlan(substr($baseDatabase, 1)));
    },
    'plans sqlite wal checkpoint modes with active reader limits' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
