        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->checkpointModePlan(substr($baseDatabase, 1), 'passive'));
    },
    'applies sqlite wal checkpoint mode results to bounded database images' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x01020304;
        $salt2 = 0xa0b0c0d0;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 13, $salt1, $salt2, 0, 0);
        $baseDatabase = $makeFirstPage($pageSize, 4)
            . str_repeat('B', $pageSize)
            . str_repeat('C', $pageSize)
            . str_repeat('D', $pageSize);
        $pageTwoOld = str_repeat('o', $pageSize);
        $pageTwoNew = str_repeat('n', $pageSize);
        $pageThree = str_repeat('3', $pageSize);
        $pageFourTail = str_repeat('t', $pageSize);
        $wal = SQLiteWal::parse(
            $walHeader
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $pageTwoOld
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $pageTwoNew
            . pack('N*', 3, 4, $salt1, $salt2, 0, 0) . $pageThree
            . pack('N*', 4, 0, $salt1, $salt2, 0, 0) . $pageFourTail
        );

        $passive = $wal->checkpointModeResult($baseDatabase, 'passive', 2);
        $t->same('passive', $passive['mode']);
        $t->same(false, $passive['busy']);
        $t->same('reader_limited_passive_checkpoint', $passive['reason']);
        $t->same(2, $passive['reader_end_frame']);
        $t->same(1, $passive['checkpointed_frame_count']);
        $t->same(2, $passive['total_committable_frame_count']);
        $t->same(1, $passive['remaining_committed_frame_count']);
        $t->same(1, $passive['uncommitted_frame_count']);
        $t->same(false, $passive['can_reset']);
        $t->same(false, $passive['can_truncate']);
        $t->same('preserve_wal', $passive['wal_action']);
        $t->same([$salt1 + 1, $salt2], $passive['next_wal_header_salt']);
        $t->same(4, $passive['database_page_count']);
        $t->same(2048, $passive['final_database_bytes']);
        $t->same($pageTwoNew, substr($passive['database_bytes'], 512, $pageSize));
        $t->same(str_repeat('C', $pageSize), substr($passive['database_bytes'], 1024, $pageSize));
        $t->same(str_repeat('D', $pageSize), substr($passive['database_bytes'], 1536, $pageSize));

        $full = $wal->checkpointModeResult($baseDatabase, 'full', 2);
        $t->same(true, $full['busy']);
        $t->same('reader_blocks_checkpoint_completion', $full['reason']);
        $t->same($passive['database_bytes'], $full['database_bytes']);
        $t->same('preserve_wal', $full['wal_action']);

        $latest = $wal->checkpointModeResult($baseDatabase, 'passive');
        $t->same('uncommitted_frames_after_last_commit', $latest['reason']);
        $t->same(2, $latest['checkpointed_frame_count']);
        $t->same($pageThree, substr($latest['database_bytes'], 1024, $pageSize));
        $t->same(str_repeat('D', $pageSize), substr($latest['database_bytes'], 1536, $pageSize));
        $t->same('preserve_wal', $latest['wal_action']);

        $committedWal = SQLiteWal::parse(
            $walHeader
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $pageTwoOld
            . pack('N*', 2, 4, $salt1, $salt2, 0, 0) . $pageTwoNew
            . pack('N*', 3, 4, $salt1, $salt2, 0, 0) . $pageThree
        );
        $restart = $committedWal->checkpointModeResult($baseDatabase, 'restart');
        $t->same(false, $restart['busy']);
        $t->same('restart_checkpoint_can_reset_wal', $restart['reason']);
        $t->same(true, $restart['can_reset']);
        $t->same(false, $restart['can_truncate']);
        $t->same('restart_wal', $restart['wal_action']);
        $t->same($pageTwoNew, substr($restart['database_bytes'], 512, $pageSize));
        $t->same($pageThree, substr($restart['database_bytes'], 1024, $pageSize));

        $truncate = $committedWal->checkpointModeResult($baseDatabase, 'truncate');
        $t->same('truncate_checkpoint_can_reset_and_truncate_wal', $truncate['reason']);
        $t->same(true, $truncate['can_reset']);
        $t->same(true, $truncate['can_truncate']);
        $t->same('truncate_wal', $truncate['wal_action']);
        $t->same($restart['database_bytes'], $truncate['database_bytes']);

        $blockedRestart = $committedWal->checkpointModeResult($baseDatabase, 'restart', 3);
        $t->same(true, $blockedRestart['busy']);
        $t->same('reader_blocks_wal_reset', $blockedRestart['reason']);
        $t->same('preserve_wal', $blockedRestart['wal_action']);
        $t->same(2, $blockedRestart['checkpointed_frame_count']);
        $t->same($restart['database_bytes'], $blockedRestart['database_bytes']);

        $emptyWal = SQLiteWal::parse($walHeader);
        $empty = $emptyWal->checkpointModeResult($baseDatabase, 'truncate');
        $t->same('wal_has_no_frames', $empty['reason']);
        $t->same('truncate_wal', $empty['wal_action']);
        $t->same($baseDatabase, $empty['database_bytes']);
        $t->same(4, $empty['database_page_count']);

        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->checkpointModeResult($baseDatabase, 'bogus'));
        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->checkpointModeResult($baseDatabase, 'passive', -1));
        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->checkpointModeResult(substr($baseDatabase, 1), 'passive'));
    },
    'materializes sqlite wal durable checkpoint sidecar writes' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x11111111;
        $salt2 = 0x22222222;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 21, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walHeader = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $baseDatabase = $makeFirstPage($pageSize, 4)
            . str_repeat('B', $pageSize)
            . str_repeat('C', $pageSize)
            . str_repeat('D', $pageSize);
        $pageTwoOld = str_repeat('o', $pageSize);
        $pageTwoNew = str_repeat('n', $pageSize);
        $pageThree = str_repeat('3', $pageSize);
        $pageFourTail = str_repeat('t', $pageSize);
        $appendFrame = static function (string $walBytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $walBytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };
        $walBytes = $appendFrame($walHeader, $checksumSeed, 2, 0, $pageTwoOld);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 0, $pageTwoNew);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 3, 4, $pageThree);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 4, 0, $pageFourTail);
        $wal = SQLiteWal::parse($walBytes, null, true);

        $preserve = $wal->durableCheckpointResult($baseDatabase, 'passive', 2);
        $t->same('passive', $preserve['mode']);
        $t->same(false, $preserve['busy']);
        $t->same('reader_limited_passive_checkpoint', $preserve['reason']);
        $t->same('preserve_wal', $preserve['wal_action']);
        $t->same(1, $preserve['checkpointed_frame_count']);
        $t->same(1, $preserve['remaining_committed_frame_count']);
        $t->same(1, $preserve['uncommitted_frame_count']);
        $t->same($walBytes, $preserve['wal_bytes']);
        $t->same(strlen($walBytes), $preserve['wal_bytes_length']);
        $t->same(21, $preserve['wal_header']['checkpoint_sequence']);
        $t->same($salt1, $preserve['wal_header']['salt1']);
        $t->same($salt2, $preserve['wal_header']['salt2']);
        $t->same(['sqlite-wal-checkpoint', 'durable-sidecar-write'], $preserve['dependencies']);
        $t->same($pageTwoNew, substr($preserve['database_bytes'], 512, $pageSize));
        $t->same(str_repeat('C', $pageSize), substr($preserve['database_bytes'], 1024, $pageSize));
        $t->same(str_repeat('D', $pageSize), substr($preserve['database_bytes'], 1536, $pageSize));

        $latestPreserve = $wal->durableCheckpointResult($baseDatabase, 'truncate');
        $t->same('uncommitted_frames_after_last_commit', $latestPreserve['reason']);
        $t->same('preserve_wal', $latestPreserve['wal_action']);
        $t->same(2, $latestPreserve['checkpointed_frame_count']);
        $t->same(1, $latestPreserve['uncommitted_frame_count']);
        $t->same($walBytes, $latestPreserve['wal_bytes']);
        $t->same($pageThree, substr($latestPreserve['database_bytes'], 1024, $pageSize));
        $t->same(str_repeat('D', $pageSize), substr($latestPreserve['database_bytes'], 1536, $pageSize));

        $committedSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $committedBytes = $appendFrame($walHeader, $committedSeed, 2, 0, $pageTwoOld);
        $committedBytes = $appendFrame($committedBytes, $committedSeed, 2, 4, $pageTwoNew);
        $committedBytes = $appendFrame($committedBytes, $committedSeed, 3, 4, $pageThree);
        $committedWal = SQLiteWal::parse($committedBytes, null, true);
        $restart = $committedWal->durableCheckpointResult($baseDatabase, 'restart');
        $t->same('restart_checkpoint_can_reset_wal', $restart['reason']);
        $t->same('restart_wal', $restart['wal_action']);
        $t->same(true, $restart['can_reset']);
        $t->same(false, $restart['can_truncate']);
        $t->same(32, $restart['wal_bytes_length']);
        $t->same(22, $restart['wal_header']['checkpoint_sequence']);
        $t->same(($salt1 + 1) & 0xffffffff, $restart['wal_header']['salt1']);
        $t->same($salt2, $restart['wal_header']['salt2']);
        $t->same($restart['wal_header']['checksum1'], SQLiteWalHeader::parse($restart['wal_bytes'])->checksum1);
        $t->same($pageTwoNew, substr($restart['database_bytes'], 512, $pageSize));
        $t->same($pageThree, substr($restart['database_bytes'], 1024, $pageSize));
        $t->same(str_repeat('D', $pageSize), substr($restart['database_bytes'], 1536, $pageSize));

        $blockedRestart = $committedWal->durableCheckpointResult($baseDatabase, 'restart', 3);
        $t->same(true, $blockedRestart['busy']);
        $t->same('reader_blocks_wal_reset', $blockedRestart['reason']);
        $t->same('preserve_wal', $blockedRestart['wal_action']);
        $t->same(strlen($committedBytes), $blockedRestart['wal_bytes_length']);
        $t->same($committedBytes, $blockedRestart['wal_bytes']);
        $t->same(21, $blockedRestart['wal_header']['checkpoint_sequence']);

        $truncate = $committedWal->durableCheckpointResult($baseDatabase, 'truncate');
        $t->same('truncate_checkpoint_can_reset_and_truncate_wal', $truncate['reason']);
        $t->same('truncate_wal', $truncate['wal_action']);
        $t->same(true, $truncate['can_reset']);
        $t->same(true, $truncate['can_truncate']);
        $t->same('', $truncate['wal_bytes']);
        $t->same(0, $truncate['wal_bytes_length']);
        $t->same(null, $truncate['wal_header']);
        $t->same($restart['database_bytes'], $truncate['database_bytes']);

        $emptyWal = SQLiteWal::parse($walHeader);
        $empty = $emptyWal->durableCheckpointResult($baseDatabase, 'truncate');
        $t->same('wal_has_no_frames', $empty['reason']);
        $t->same('truncate_wal', $empty['wal_action']);
        $t->same('', $empty['wal_bytes']);
        $t->same(0, $empty['wal_bytes_length']);
        $t->same($baseDatabase, $empty['database_bytes']);

        $t->same($walBytes, $wal->toBytes());
        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->durableCheckpointResult($baseDatabase, 'bogus'));
        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->durableCheckpointResult($baseDatabase, 'passive', -1));
        $t->throws(InvalidArgumentException::class, static fn () => $committedWal->durableCheckpointResult(substr($baseDatabase, 1), 'passive'));
    },
    'keeps current wal readers visible across checkpoint results' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x51515151;
        $salt2 = 0x62626262;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 24, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walHeader = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $appendFrame = static function (string $walBytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $walBytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };

        $basePageTwo = str_pad('base app_settings row page before checkpoint', $pageSize, "\0");
        $basePageThree = str_pad('base load_policy index page before checkpoint', $pageSize, "\0");
        $baseDatabase = $makeFirstPage($pageSize, 3) . $basePageTwo . $basePageThree;
        $readerPageTwo = str_pad('reader current siteurl row from first wal commit', $pageSize, "\0");
        $latestPageTwo = str_pad('latest siteurl row after reader started', $pageSize, "\0");
        $latestPageThree = str_pad('latest load_policy index after reader started', $pageSize, "\0");

        $walBytes = $appendFrame($walHeader, $checksumSeed, 2, 3, $readerPageTwo);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 0, $latestPageTwo);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 3, 3, $latestPageThree);
        $wal = SQLiteWal::parse($walBytes, null, true);

        $pinned = $wal->checkpointReaderVisibility($baseDatabase, [2, 3], 'passive', 1);
        $t->same('passive', $pinned['mode']);
        $t->same(1, $pinned['reader_end_frame']);
        $t->same('preserve_wal', $pinned['wal_action']);
        $t->same('reader_limited_passive_checkpoint', $pinned['checkpoint_reason']);
        $t->same(false, $pinned['checkpoint_busy']);
        $t->same(true, $pinned['stable']);
        $t->same(['sqlite-wal-checkpoint', 'wal-reader-current-visibility', 'durable-sidecar-write'], $pinned['dependencies']);
        $t->same(2, count($pinned['before']));
        $t->same(2, count($pinned['after']));
        $t->same('wal', $pinned['before'][0]['source']);
        $t->same(1, $pinned['before'][0]['frame_index']);
        $t->same($readerPageTwo, $pinned['before'][0]['image']);
        $t->same(1, $pinned['before'][0]['snapshot_end_frame']);
        $t->same(1, $pinned['before'][0]['snapshot_commit_frame']);
        $t->same('database', $pinned['before'][1]['source']);
        $t->same(null, $pinned['before'][1]['frame_index']);
        $t->same($basePageThree, $pinned['before'][1]['image']);
        $t->same($pinned['before'][0]['image'], $pinned['after'][0]['image']);
        $t->same($pinned['before'][1]['image'], $pinned['after'][1]['image']);
        $t->same('wal', $pinned['after'][0]['source']);
        $t->same('database', $pinned['after'][1]['source']);
        $t->same(3, $pinned['after'][1]['database_page_count']);

        $fullBlocked = $wal->checkpointReaderVisibility($baseDatabase, [2, 3], 'full', 1);
        $t->same(true, $fullBlocked['checkpoint_busy']);
        $t->same('reader_blocks_checkpoint_completion', $fullBlocked['checkpoint_reason']);
        $t->same(true, $fullBlocked['stable']);
        $t->same($readerPageTwo, $fullBlocked['after'][0]['image']);
        $t->same($basePageThree, $fullBlocked['after'][1]['image']);

        $latest = $wal->checkpointReaderVisibility($baseDatabase, [2, 3], 'truncate');
        $t->same('truncate', $latest['mode']);
        $t->same(null, $latest['reader_end_frame']);
        $t->same('truncate_wal', $latest['wal_action']);
        $t->same('truncate_checkpoint_can_reset_and_truncate_wal', $latest['checkpoint_reason']);
        $t->same(false, $latest['checkpoint_busy']);
        $t->same(true, $latest['stable']);
        $t->same('wal', $latest['before'][0]['source']);
        $t->same(2, $latest['before'][0]['frame_index']);
        $t->same('wal', $latest['before'][1]['source']);
        $t->same(3, $latest['before'][1]['frame_index']);
        $t->same($latestPageTwo, $latest['before'][0]['image']);
        $t->same($latestPageThree, $latest['before'][1]['image']);
        $t->same('database', $latest['after'][0]['source']);
        $t->same(null, $latest['after'][0]['frame_index']);
        $t->same($latestPageTwo, $latest['after'][0]['image']);
        $t->same($latestPageThree, $latest['after'][1]['image']);
        $t->same(0, $latest['after'][0]['snapshot_end_frame']);

        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointReaderVisibility($baseDatabase, []));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointReaderVisibility($baseDatabase, [2, '3']));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointReaderVisibility($baseDatabase, [0]));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointReaderVisibility(substr($baseDatabase, 1), [2]));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointReaderVisibility($baseDatabase, [2], 'bogus'));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->checkpointReaderVisibility($baseDatabase, [2], 'passive', -1));
    },
    'plans sqlite wal durable checkpoint vfs file writes' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x51515151;
