    'plans sqlite pager checkpoint transactions with locks and wal writes' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x73737373;
        $salt2 = 0x84848484;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 61, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walHeader = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $appendFrame = static function (string $walBytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $walBytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };

        $baseDatabase = $makeFirstPage($pageSize, 3) . str_repeat('b', $pageSize) . str_repeat('c', $pageSize);
        $walBytes = $appendFrame($walHeader, $checksumSeed, 2, 0, str_repeat('2', $pageSize));
        $walBytes = $appendFrame($walBytes, $checksumSeed, 3, 3, str_repeat('3', $pageSize));
        $wal = SQLiteWal::parse($walBytes, null, true);
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';

        $passive = SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'passive');
        $t->same('ready', $passive['status']);
        $t->same(true, $passive['can_checkpoint']);
        $t->same('wp-import', $passive['connection']);
        $t->same('passive', $passive['mode']);
        $t->same($databasePath, $passive['database_path']);
        $t->same('passive_checkpoint_complete', $passive['reason']);
        $t->same(['sqlite-pager-checkpoint-transaction', 'sqlite-lock-coordinator', 'sqlite-wal-checkpoint', 'durable-sidecar-write', 'vfs-file-write-coordination'], $passive['dependencies']);
        $t->same(1, count($passive['lock_sequence']));
        $t->same('shared', $passive['lock_sequence'][0]['requested']);
        $t->same(true, $passive['lock_sequence'][0]['can_acquire']);
        $t->same([], $passive['lock_sequence'][0]['blocking']);
        $t->same(null, $passive['busy']);
        $t->same('passive', $passive['write_plan']['mode']);
        $t->same('preserve_wal', $passive['write_plan']['wal_action']);
        $t->same(5, count($passive['write_plan']['operations']));
        $t->same('checkpoint_database_pages', $passive['write_plan']['operations'][0]['reason']);
        $t->same('preserve_wal_sidecar', $passive['write_plan']['operations'][2]['reason']);

        $restart = SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'restart');
        $t->same('ready', $restart['status']);
        $t->same(true, $restart['can_checkpoint']);
        $t->same('restart', $restart['mode']);
        $t->same('restart_checkpoint_can_reset_wal', $restart['reason']);
        $t->same(4, count($restart['lock_sequence']));
        $t->same(['shared', 'reserved', 'pending', 'exclusive'], array_column($restart['lock_sequence'], 'requested'));
        $t->same([true, true, true, true], array_column($restart['lock_sequence'], 'can_acquire'));
        $t->same('restart_wal', $restart['write_plan']['wal_action']);
        $t->same(32, $restart['write_plan']['wal_bytes']);
        $t->same('write_restarted_wal_header', $restart['write_plan']['operations'][2]['reason']);
        $t->same('sync_wal_sidecar', $restart['write_plan']['operations'][3]['reason']);
        $t->same('persist_database_and_wal_directory_entries', $restart['write_plan']['operations'][4]['reason']);

        $truncate = SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'truncate');
        $t->same('ready', $truncate['status']);
        $t->same(true, $truncate['can_checkpoint']);
        $t->same('truncate', $truncate['mode']);
        $t->same('truncate_checkpoint_can_reset_and_truncate_wal', $truncate['reason']);
        $t->same('truncate_wal', $truncate['write_plan']['wal_action']);
        $t->same(0, $truncate['write_plan']['wal_bytes']);
        $t->same('truncate', $truncate['write_plan']['operations'][2]['op']);
        $t->same('truncate_reset_wal', $truncate['write_plan']['operations'][2]['reason']);

        $readerBlocked = SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'restart', 1);
        $t->same('busy', $readerBlocked['status']);
        $t->same(false, $readerBlocked['can_checkpoint']);
        $t->same('reader_blocks_checkpoint_completion', $readerBlocked['reason']);
        $t->same(4, count($readerBlocked['lock_sequence']));
        $t->same('preserve_wal', $readerBlocked['write_plan']['wal_action']);
        $t->same(true, $readerBlocked['write_plan']['busy']);
        $t->same(null, $readerBlocked['busy']);

        $pendingWriter = new SQLiteLockCoordinator(['writer' => 'pending']);
        $blockedShared = SQLitePagerCheckpointTransactionPlan::plan($pendingWriter, 'wp-import', $wal, $baseDatabase, $databasePath, 'passive', null, SQLiteBusyHandler::timeout(25, 5));
        $t->same('busy-timeout', $blockedShared['status']);
        $t->same(false, $blockedShared['can_checkpoint']);
        $t->same('new reader is blocked by pending or exclusive writer lock', $blockedShared['reason']);
        $t->same(1, count($blockedShared['lock_sequence']));
        $t->same('shared', $blockedShared['lock_sequence'][0]['requested']);
        $t->same(false, $blockedShared['lock_sequence'][0]['can_acquire']);
        $t->same('writer', $blockedShared['lock_sequence'][0]['blocking'][0]['connection']);
        $t->same('pending lock blocks new shared readers', $blockedShared['lock_sequence'][0]['blocking'][0]['reason']);
        $t->same('busy-timeout', $blockedShared['busy']['status']);
        $t->same(25, $blockedShared['busy']['timeout_ms']);
        $t->same(['sqlite-pager-checkpoint-transaction', 'sqlite-lock-coordinator', 'busy-handler'], $blockedShared['dependencies']);
        $t->same(null, $blockedShared['write_plan']);

        $readerHeld = new SQLiteLockCoordinator(['reader-one' => 'shared']);
        $blockedExclusive = SQLitePagerCheckpointTransactionPlan::plan($readerHeld, 'wp-import', $wal, $baseDatabase, $databasePath, 'full');
        $t->same('busy-cancelled', $blockedExclusive['status']);
        $t->same(false, $blockedExclusive['can_checkpoint']);
        $t->same('exclusive writer is blocked until readers and writers drain', $blockedExclusive['reason']);
        $t->same(4, count($blockedExclusive['lock_sequence']));
        $t->same(['shared', 'reserved', 'pending', 'exclusive'], array_column($blockedExclusive['lock_sequence'], 'requested'));
        $t->same([true, true, true, false], array_column($blockedExclusive['lock_sequence'], 'can_acquire'));
        $t->same('reader-one', $blockedExclusive['lock_sequence'][3]['blocking'][0]['connection']);
        $t->same('shared reader must drain before exclusive lock', $blockedExclusive['lock_sequence'][3]['blocking'][0]['reason']);
        $t->same(null, $blockedExclusive['write_plan']);

        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'invalid'));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), '', $wal, $baseDatabase, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, ''));
        $t->throws(LogicException::class, static fn () => SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'passive', null, null, true));
        $t->throws(LogicException::class, static fn () => SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, $baseDatabase, $databasePath, 'passive', null, null, false, true));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerCheckpointTransactionPlan::plan(new SQLiteLockCoordinator(), 'wp-import', $wal, substr($baseDatabase, 1), $databasePath));
    },
    'applies sqlite vfs file handle primitives for pager reads and writes' => static function (TestRunner $t) use ($makeFirstPage): void {
        $root = sys_get_temp_dir() . '/port-libsqlite-vfs-handle-' . bin2hex(random_bytes(4));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';
        $walPath = $databasePath . '-wal';
        $localDatabasePath = $root . $databasePath;
        $pageSize = 512;
        $pageOne = $makeFirstPage($pageSize, 2);
        $pageTwo = str_repeat('W', $pageSize);
        $databaseBytes = $pageOne . $pageTwo;

        if (!mkdir(dirname($localDatabasePath), 0777, true) && !is_dir(dirname($localDatabasePath))) {
            throw new RuntimeException('Could not create VFS handle test directory');
        }
        file_put_contents($localDatabasePath, $databaseBytes);

        $handle = new SQLiteVfsFileHandle($root, $databasePath);
        $stat = $handle->stat();
        $t->same('ready', $stat['status']);
        $t->same($databasePath, $stat['path']);
        $t->same($localDatabasePath, $stat['local_path']);
        $t->same(true, $stat['exists']);
        $t->same(1024, $stat['size']);
        $t->same(false, $stat['read_only']);
        $t->same(false, $stat['immutable']);
        $t->same(['vfs-file-handle-primitive', 'vfs-xfilesize'], $stat['dependencies']);

        $header = $handle->readAt(0, 16);
        $t->same('ok', $header['status']);
        $t->same($databasePath, $header['path']);
        $t->same($localDatabasePath, $header['local_path']);
        $t->same(0, $header['offset']);
        $t->same(16, $header['requested']);
        $t->same(16, $header['bytes_read']);
        $t->same(0, $header['short_read']);
        $t->same('SQLite format 3' . "\0", $header['data']);
        $t->same($header['data'], $header['zero_filled_data']);
        $t->same(['vfs-file-handle-primitive', 'vfs-xread'], $header['dependencies']);

        $pageTwoPrefix = $handle->readAt($pageSize, 8);
        $t->same('ok', $pageTwoPrefix['status']);
        $t->same(str_repeat('W', 8), $pageTwoPrefix['data']);
        $t->same(8, $pageTwoPrefix['bytes_read']);

        $tail = $handle->readAt(1020, 16);
        $t->same('short_read', $tail['status']);
        $t->same(4, $tail['bytes_read']);
        $t->same(12, $tail['short_read']);
        $t->same(str_repeat('W', 4), $tail['data']);
        $t->same(str_repeat('W', 4) . str_repeat("\0", 12), $tail['zero_filled_data']);

        $zero = $handle->readAt(12, 0);
        $t->same('ok', $zero['status']);
        $t->same(0, $zero['requested']);
        $t->same(0, $zero['bytes_read']);
        $t->same('', $zero['data']);

        $write = $handle->writeAt(100, 'siteurl');
        $t->same('ok', $write['status']);
        $t->same($databasePath, $write['path']);
        $t->same($localDatabasePath, $write['local_path']);
        $t->same(100, $write['offset']);
        $t->same(7, $write['bytes_written']);
        $t->same(1024, $write['size']);
        $t->same(['vfs-file-handle-primitive', 'vfs-xwrite'], $write['dependencies']);
        $t->same('siteurl', substr(file_get_contents($localDatabasePath), 100, 7));

        $sparse = $handle->writeAt(1030, 'tail');
        $t->same('ok', $sparse['status']);
        $t->same(4, $sparse['bytes_written']);
        $t->same(1034, $sparse['size']);
        $t->same(str_repeat("\0", 6) . 'tail', substr(file_get_contents($localDatabasePath), 1024, 10));

        $truncate = $handle->truncateTo(700);
        $t->same('ok', $truncate['status']);
        $t->same(700, $truncate['size']);
        $t->same(['vfs-file-handle-primitive', 'vfs-xtruncate'], $truncate['dependencies']);
        $t->same(700, filesize($localDatabasePath));
        $truncatedRead = $handle->readAt(696, 8);
        $t->same('short_read', $truncatedRead['status']);
        $t->same(4, $truncatedRead['bytes_read']);
        $t->same(4, $truncatedRead['short_read']);
        $t->same(str_repeat("\0", 4), substr($truncatedRead['zero_filled_data'], 4));

        $grow = $handle->truncateTo(900);
        $t->same('ok', $grow['status']);
        $t->same(900, $grow['size']);
        $t->same(900, filesize($localDatabasePath));

        $wal = new SQLiteVfsFileHandle($root, $walPath);
        $missingWal = $wal->stat();
        $t->same(false, $missingWal['exists']);
        $t->same(0, $missingWal['size']);
        $walWrite = $wal->writeAt(0, 'wal-frame-bytes');
        $t->same('ok', $walWrite['status']);
        $t->same(15, $walWrite['bytes_written']);
        $t->same(15, $walWrite['size']);
        $t->same('wal-frame-bytes', file_get_contents($root . $walPath));
        $walDelete = $wal->delete();
        $t->same('ok', $walDelete['status']);
        $t->same(true, $walDelete['deleted']);
        $t->same(['vfs-file-handle-primitive', 'vfs-xdelete'], $walDelete['dependencies']);
        $t->same(false, is_file($root . $walPath));
        $missingDelete = $wal->delete();
        $t->same(false, $missingDelete['deleted']);

        $readOnly = new SQLiteVfsFileHandle($root, $databasePath, true);
        $immutable = new SQLiteVfsFileHandle($root, $databasePath, false, true);
        $readOnlyStat = $readOnly->stat();
        $t->same(true, $readOnlyStat['read_only']);
        $t->same(false, $readOnlyStat['immutable']);
        $t->same('SQLite format 3' . "\0", $readOnly->readAt(0, 16)['data']);
        $t->throws(LogicException::class, static fn () => $readOnly->writeAt(0, 'x'));
        $t->throws(LogicException::class, static fn () => $readOnly->truncateTo(1));
        $t->throws(LogicException::class, static fn () => $readOnly->delete());
        $t->throws(LogicException::class, static fn () => $immutable->writeAt(0, 'x'));
        $t->throws(InvalidArgumentException::class, static fn () => new SQLiteVfsFileHandle('', $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => new SQLiteVfsFileHandle($root, ''));
        $t->throws(InvalidArgumentException::class, static fn () => (new SQLiteVfsFileHandle($root, '../escape.sqlite'))->stat());
        $t->throws(InvalidArgumentException::class, static fn () => (new SQLiteVfsFileHandle($root, "/tmp/bad\0name.sqlite"))->stat());
        $t->throws(InvalidArgumentException::class, static fn () => $handle->readAt(-1, 1));
        $t->throws(InvalidArgumentException::class, static fn () => $handle->readAt(0, -1));
        $t->throws(InvalidArgumentException::class, static fn () => $handle->writeAt(-1, 'x'));
        $t->throws(InvalidArgumentException::class, static fn () => $handle->truncateTo(-1));
        $t->throws(RuntimeException::class, static fn () => (new SQLiteVfsFileHandle($root, '/srv/www/wp-content/database/missing.sqlite'))->readAt(0, 1));
    },
    'applies sqlite vfs wal checkpoint file writes to local handles' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x61616161;
        $salt2 = 0x72727272;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 44, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walHeader = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $appendFrame = static function (string $walBytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $walBytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };

        $root = sys_get_temp_dir() . '/port-libsqlite-vfs-writer-' . bin2hex(random_bytes(4));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';
        $localDatabasePath = $root . '/srv/www/wp-content/database/.ht.sqlite';
        $localWalPath = $localDatabasePath . '-wal';
        $baseDatabase = $makeFirstPage($pageSize, 3) . str_repeat('b', $pageSize) . str_repeat('c', $pageSize);
        $pageTwo = str_repeat('2', $pageSize);
        $pageThree = str_repeat('3', $pageSize);
        $committedSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $committedBytes = $appendFrame($walHeader, $committedSeed, 2, 0, $pageTwo);
        $committedBytes = $appendFrame($committedBytes, $committedSeed, 3, 3, $pageThree);
        $committedWal = SQLiteWal::parse($committedBytes, null, true);
        $writer = new SQLiteVfsFileWriter($root);

        $restart = $writer->applyWalCheckpoint($committedWal, $baseDatabase, $databasePath, 'restart');
        $t->same('applied', $restart['status']);
        $t->same($root, $restart['root']);
        $t->same(5, $restart['applied']);
        $t->same(1568, $restart['bytes_written']);
        $t->same(0, $restart['bytes_truncated']);
        $t->same(2, $restart['durable_syncs']);
        $t->same(1, $restart['directory_syncs']);
        $t->same(['sqlite-wal-checkpoint', 'durable-sidecar-write', 'vfs-file-write-coordination', 'vfs-file-handle-write-application'], $restart['dependencies']);
        $t->same('write', $restart['operations'][0]['op']);
        $t->same($databasePath, $restart['operations'][0]['path']);
        $t->same($localDatabasePath, $restart['operations'][0]['local_path']);
        $t->same(1536, $restart['operations'][0]['bytes']);
        $t->same(false, $restart['operations'][0]['durable']);
        $t->same('checkpoint_database_pages', $restart['operations'][0]['reason']);
        $t->same('sync', $restart['operations'][1]['op']);
        $t->same(true, $restart['operations'][1]['durable']);
        $t->same('write', $restart['operations'][2]['op']);
        $t->same($databasePath . '-wal', $restart['operations'][2]['path']);
        $t->same($localWalPath, $restart['operations'][2]['local_path']);
        $t->same(32, $restart['operations'][2]['bytes']);
        $t->same('write_restarted_wal_header', $restart['operations'][2]['reason']);
        $t->same('sync', $restart['operations'][3]['op']);
        $t->same('sync_directory', $restart['operations'][4]['op']);
        $t->same($root . '/srv/www/wp-content/database', $restart['operations'][4]['local_path']);
        $t->same(1536, filesize($localDatabasePath));
        $t->same(32, filesize($localWalPath));
        $t->contains(str_repeat('2', 32), file_get_contents($localDatabasePath));
        $t->contains(str_repeat('3', 32), file_get_contents($localDatabasePath));
        $t->same(substr($committedWal->durableCheckpointResult($baseDatabase, 'restart')['wal_bytes'], 0, 32), file_get_contents($localWalPath));

        file_put_contents($localWalPath, 'stale-wal-bytes');
        $truncate = $writer->applyWalCheckpoint($committedWal, $baseDatabase, $databasePath, 'truncate');
        $t->same('applied', $truncate['status']);
        $t->same(4, $truncate['applied']);
        $t->same(1536, $truncate['bytes_written']);
        $t->same(0, $truncate['bytes_truncated']);
        $t->same(1, $truncate['durable_syncs']);
        $t->same(1, $truncate['directory_syncs']);
        $t->same('truncate', $truncate['operations'][2]['op']);
        $t->same($databasePath . '-wal', $truncate['operations'][2]['path']);
        $t->same(0, $truncate['operations'][2]['bytes']);
        $t->same('truncate_reset_wal', $truncate['operations'][2]['reason']);
        $t->same(0, filesize($localWalPath));
        $t->same(1536, filesize($localDatabasePath));
        $t->contains(str_repeat('2', 32), file_get_contents($localDatabasePath));

        $manual = $writer->applyOperations([
            ['op' => 'write', 'path' => '/tmp/manual.sqlite', 'offset' => 4, 'bytes' => 3, 'reason' => 'sparse_write'],
            ['op' => 'sync', 'path' => '/tmp/manual.sqlite', 'durable' => true, 'reason' => 'manual_sync'],
            ['op' => 'truncate', 'path' => '/tmp/manual.sqlite', 'bytes' => 5, 'reason' => 'manual_truncate'],
        ], ['/tmp/manual.sqlite' => 'abc'], ['manual-plan']);
        $t->same('applied', $manual['status']);
        $t->same(3, $manual['applied']);
        $t->same(3, $manual['bytes_written']);
        $t->same(5, $manual['bytes_truncated']);
        $t->same(1, $manual['durable_syncs']);
        $t->same(0, $manual['directory_syncs']);
        $t->same(['manual-plan', 'vfs-file-handle-write-application'], $manual['dependencies']);
        $t->same(5, filesize($root . '/tmp/manual.sqlite'));
        $t->same("\0\0\0\0a", file_get_contents($root . '/tmp/manual.sqlite'));

        $readOnly = new SQLiteVfsFileWriter($root, true);
        $immutable = new SQLiteVfsFileWriter($root, false, true);
        $t->throws(LogicException::class, static fn () => $readOnly->applyOperations([]));
        $t->throws(LogicException::class, static fn () => $immutable->applyWalCheckpoint($committedWal, $baseDatabase, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => new SQLiteVfsFileWriter(''));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyOperations([['op' => 'write', 'path' => '/tmp/missing.sqlite', 'offset' => 0, 'bytes' => 1]]));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyOperations([['op' => 'write', 'path' => '/tmp/mismatch.sqlite', 'offset' => 0, 'bytes' => 2]], ['/tmp/mismatch.sqlite' => 'x']));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyOperations([['op' => 'bogus', 'path' => '/tmp/bogus.sqlite']]));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyOperations([['op' => 'write', 'path' => '../escape.sqlite', 'offset' => 0, 'bytes' => 1]], ['../escape.sqlite' => 'x']));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyOperations([['op' => 'write', 'path' => "/tmp/bad\0name.sqlite", 'offset' => 0, 'bytes' => 1]], ["/tmp/bad\0name.sqlite" => 'x']));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyOperations([['op' => 'write', 'path' => '/tmp/negative.sqlite', 'offset' => -1, 'bytes' => 1]], ['/tmp/negative.sqlite' => 'x']));
        $t->throws(RuntimeException::class, static fn () => $writer->applyOperations([['op' => 'sync', 'path' => '/tmp/does-not-exist.sqlite']]));
        $t->throws(RuntimeException::class, static fn () => $writer->applyOperations([['op' => 'sync_directory', 'path' => '/tmp/does-not-exist-directory']]));
    },
    'plans and applies sqlite wal recovery to local handles' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x24242424;
        $salt2 = 0x35353535;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 77, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walHeader = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $appendFrame = static function (string $walBytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $walBytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };

        $baseDatabase = $makeFirstPage($pageSize, 3)
            . str_pad('old-siteurl-page', $pageSize, '.')
            . str_pad('old-home-page', $pageSize, '.');
        $pageTwoOld = str_pad('siteurl-before-commit', $pageSize, 'o');
        $pageTwoNew = str_pad('siteurl-after-commit', $pageSize, 'n');
        $pageThree = str_pad('home-after-commit', $pageSize, 'h');
        $pageFourTail = str_pad('uncommitted-transient-tail', $pageSize, 't');
        $walBytes = $appendFrame($walHeader, $checksumSeed, 2, 0, $pageTwoOld);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 0, $pageTwoNew);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 3, 4, $pageThree);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 4, 0, $pageFourTail);
        $wal = SQLiteWal::parse($walBytes, null, true);
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';

        $plan = SQLiteWalRecoveryPlan::recover($wal, $baseDatabase, $databasePath);
        $t->same('ready', $plan['status']);
        $t->same($databasePath, $plan['database_path']);
        $t->same($databasePath . '-wal', $plan['wal_path']);
        $t->same('committed_wal_frames_recovered_with_tail_preserved', $plan['reason']);
        $t->same(2048, $plan['database_bytes']);
        $t->same(strlen($walBytes), $plan['wal_bytes']);
        $t->same(3, $plan['last_commit_frame']);
        $t->same(1, $plan['committed_transaction_count']);
        $t->same(2, $plan['applied_page_count']);
        $t->same(1, $plan['uncommitted_frame_count']);
        $t->same(['sqlite-wal-recovery', 'sqlite-wal-frame-commit-scan', 'vfs-file-write-coordination'], $plan['dependencies']);
        $t->same(6, count($plan['operations']));
        $t->same('write', $plan['operations'][0]['op']);
        $t->same($databasePath, $plan['operations'][0]['path']);
        $t->same(0, $plan['operations'][0]['offset']);
        $t->same(2048, $plan['operations'][0]['bytes']);
        $t->same('recover_committed_wal_frames_to_database', $plan['operations'][0]['reason']);
        $t->same('truncate', $plan['operations'][1]['op']);
        $t->same('trim_database_to_last_wal_commit_size', $plan['operations'][1]['reason']);
        $t->same('sync', $plan['operations'][2]['op']);
        $t->same(true, $plan['operations'][2]['durable']);
        $t->same('write', $plan['operations'][3]['op']);
        $t->same($databasePath . '-wal', $plan['operations'][3]['path']);
        $t->same('preserve_wal_with_uncommitted_tail', $plan['operations'][3]['reason']);
        $t->same('sync', $plan['operations'][4]['op']);
        $t->same('sync_directory', $plan['operations'][5]['op']);
        $t->same('/srv/www/wp-content/database', $plan['operations'][5]['path']);
        $t->same(4, count($plan['frames']));
        $t->same('superseded_by_later_committed_frame', $plan['frames'][0]['reason']);
        $t->same('skip', $plan['frames'][0]['recovery_action']);
        $t->same('checkpointed_to_database', $plan['frames'][1]['reason']);
        $t->same('restore_database_page', $plan['frames'][1]['recovery_action']);
        $t->same(512, $plan['frames'][1]['database_offset']);
        $t->same('checkpointed_to_database', $plan['frames'][2]['reason']);
        $t->same(1024, $plan['frames'][2]['database_offset']);
        $t->same('after_last_commit', $plan['frames'][3]['reason']);
        $t->same('skip', $plan['frames'][3]['recovery_action']);

        $payloads = SQLiteWalRecoveryPlan::payloads($wal, $baseDatabase, $databasePath);
        $t->same([$databasePath, $databasePath . '-wal'], array_keys($payloads));
        $t->same($pageTwoNew, substr($payloads[$databasePath], $pageSize, $pageSize));
        $t->same($pageThree, substr($payloads[$databasePath], $pageSize * 2, $pageSize));
        $t->same(str_repeat("\0", 32), substr($payloads[$databasePath], $pageSize * 3, 32));
        $t->same($walBytes, $payloads[$databasePath . '-wal']);

        $root = sys_get_temp_dir() . '/port-libsqlite-wal-recovery-' . bin2hex(random_bytes(4));
        $writer = new SQLiteVfsFileWriter($root);
        $applied = $writer->applyWalRecovery($wal, $baseDatabase, $databasePath);
        $localDatabasePath = $root . '/srv/www/wp-content/database/.ht.sqlite';
        $localWalPath = $localDatabasePath . '-wal';
        $t->same('applied', $applied['status']);
        $t->same(6, $applied['applied']);
        $t->same(2048 + strlen($walBytes), $applied['bytes_written']);
        $t->same(2048, $applied['bytes_truncated']);
        $t->same(2, $applied['durable_syncs']);
        $t->same(1, $applied['directory_syncs']);
        $t->same(['sqlite-wal-recovery', 'sqlite-wal-frame-commit-scan', 'vfs-file-write-coordination', 'vfs-file-handle-write-application'], $applied['dependencies']);
        $t->same('committed_wal_frames_recovered_with_tail_preserved', $applied['recovery']['reason']);
        $t->same($pageTwoNew, substr(file_get_contents($localDatabasePath), $pageSize, $pageSize));
        $t->same($pageThree, substr(file_get_contents($localDatabasePath), $pageSize * 2, $pageSize));
        $t->same(2048, filesize($localDatabasePath));
        $t->same($walBytes, file_get_contents($localWalPath));
        $t->same(strlen($walBytes), filesize($localWalPath));
        $t->same($localDatabasePath, $applied['operations'][0]['local_path']);
        $t->same($localWalPath, $applied['operations'][3]['local_path']);

        $committedSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $committedBytes = $appendFrame($walHeader, $committedSeed, 2, 0, $pageTwoOld);
        $committedBytes = $appendFrame($committedBytes, $committedSeed, 2, 3, $pageTwoNew);
        $committedWal = SQLiteWal::parse($committedBytes, null, true);
        $committedPlan = SQLiteWalRecoveryPlan::recover($committedWal, $baseDatabase, $databasePath, directorySync: false);
        $t->same('committed_wal_frames_recovered', $committedPlan['reason']);
        $t->same(0, $committedPlan['uncommitted_frame_count']);
        $t->same(1, $committedPlan['committed_transaction_count']);
        $t->same(1, $committedPlan['applied_page_count']);
        $t->same(5, count($committedPlan['operations']));
        $t->same('preserve_wal_after_recovery', $committedPlan['operations'][3]['reason']);

        $emptyWal = SQLiteWal::parse($walHeader);
        $emptyPlan = SQLiteWalRecoveryPlan::recover($emptyWal, $baseDatabase, $databasePath);
        $t->same('skipped', $emptyPlan['status']);
        $t->same('wal_has_no_frames', $emptyPlan['reason']);
        $t->same(0, $emptyPlan['applied_page_count']);
        $t->same([], $emptyPlan['operations']);
        $emptyApplied = $writer->applyWalRecovery($emptyWal, $baseDatabase, $databasePath);
        $t->same('skipped', $emptyApplied['status']);
        $t->same(0, $emptyApplied['applied']);
        $t->same('wal_has_no_frames', $emptyApplied['recovery']['reason']);

        $tailOnlySeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $tailOnlyBytes = $appendFrame($walHeader, $tailOnlySeed, 2, 0, $pageTwoOld);
        $tailOnlyWal = SQLiteWal::parse($tailOnlyBytes, null, true);
        $tailOnlyPlan = SQLiteWalRecoveryPlan::recover($tailOnlyWal, $baseDatabase, $databasePath);
        $t->same('skipped', $tailOnlyPlan['status']);
        $t->same('wal_has_no_committed_transaction', $tailOnlyPlan['reason']);
        $t->same(1, $tailOnlyPlan['uncommitted_frame_count']);
        $t->same('after_last_commit', $tailOnlyPlan['frames'][0]['reason']);

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWalRecoveryPlan::recover($wal, $baseDatabase, ''));
        $t->throws(LogicException::class, static fn () => SQLiteWalRecoveryPlan::recover($wal, $baseDatabase, $databasePath, true));
        $t->throws(LogicException::class, static fn () => SQLiteWalRecoveryPlan::recover($wal, $baseDatabase, $databasePath, false, true));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWalRecoveryPlan::recover($wal, substr($baseDatabase, 1), $databasePath));
        $t->throws(LogicException::class, static fn () => (new SQLiteVfsFileWriter($root, true))->applyWalRecovery($wal, $baseDatabase, $databasePath));
    },
    'applies sqlite vfs hot rollback journal recovery to local handles' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $sectorSize = 512;
        $nonce = 0x21222324;
        $pageOneClean = $makeFirstPage($pageSize, 2);
        $pageTwoClean = str_repeat('C', $pageSize);
        $pageThreeIgnored = str_repeat('I', $pageSize);
        $dirtyDatabase = $makeFirstPage($pageSize, 3)
            . str_repeat('D', $pageSize)
            . str_repeat('X', $pageSize);
        $header = SQLiteRollbackJournalHeader::MAGIC . pack('N*', 3, $nonce, 2, $sectorSize, $pageSize);
        $journalBytes = str_pad($header, $sectorSize, "\0")
            . pack('N', 1) . $pageOneClean . pack('N', SQLiteRollbackJournal::pageChecksum($pageOneClean, $nonce))
            . pack('N', 2) . $pageTwoClean . pack('N', SQLiteRollbackJournal::pageChecksum($pageTwoClean, $nonce))
            . pack('N', 3) . $pageThreeIgnored . pack('N', SQLiteRollbackJournal::pageChecksum($pageThreeIgnored, $nonce));

        $journal = SQLiteRollbackJournal::parse($journalBytes, true);
        $root = sys_get_temp_dir() . '/port-libsqlite-vfs-rollback-' . bin2hex(random_bytes(4));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';
        $localDatabasePath = $root . '/srv/www/wp-content/database/.ht.sqlite';
        $localJournalPath = $localDatabasePath . '-journal';
        if (!mkdir(dirname($localDatabasePath), 0777, true) && !is_dir(dirname($localDatabasePath))) {
            throw new RuntimeException('Unable to create rollback test directory');
        }
        file_put_contents($localDatabasePath, $dirtyDatabase);
        file_put_contents($localJournalPath, $journalBytes);

        $writer = new SQLiteVfsFileWriter($root);
        $applied = $writer->applyHotRollbackJournal($journal, $dirtyDatabase, $journalBytes, $databasePath);

        $t->same('applied', $applied['status']);
        $t->same($root, $applied['root']);
        $t->same(5, $applied['applied']);
        $t->same(1024, $applied['bytes_written']);
        $t->same(1024, $applied['bytes_truncated']);
        $t->same(1, $applied['files_deleted']);
        $t->same(1, $applied['durable_syncs']);
        $t->same(1, $applied['directory_syncs']);
        $t->same(['sqlite-rollback-journal-recovery', 'hot-journal-delete', 'vfs-file-write-coordination', 'vfs-file-handle-write-application'], $applied['dependencies']);
        $t->same(true, $applied['recovery']['recovered']);
        $t->same('hot_journal_recovered', $applied['recovery']['reason']);
        $t->same('delete_journal_after_recovery', $applied['recovery']['journal_action']);
        $t->same(1024, $applied['recovery']['final_database_bytes']);
        $t->same('hot_journal_recovery_required', $applied['recovery']['hot_journal']['reason']);
        $t->same(2, $applied['recovery']['recovery_plan']['initial_database_page_count']);
        $t->same(1024, $applied['recovery']['recovery_plan']['final_database_bytes']);
        $t->same([1, 2, 3], array_column($applied['recovery']['recovery_plan']['pages'], 'page_number'));
        $t->same([true, true, false], array_column($applied['recovery']['recovery_plan']['pages'], 'applied'));
        $t->same(['restored_from_journal', 'restored_from_journal', 'beyond_initial_database_size'], array_column($applied['recovery']['recovery_plan']['pages'], 'reason'));

        $t->same('write', $applied['operations'][0]['op']);
        $t->same($databasePath, $applied['operations'][0]['path']);
        $t->same($localDatabasePath, $applied['operations'][0]['local_path']);
        $t->same(1024, $applied['operations'][0]['bytes']);
        $t->same(false, $applied['operations'][0]['durable']);
        $t->same('restore_database_pages_from_hot_journal', $applied['operations'][0]['reason']);
        $t->same('truncate', $applied['operations'][1]['op']);
        $t->same($databasePath, $applied['operations'][1]['path']);
        $t->same(1024, $applied['operations'][1]['bytes']);
        $t->same('truncate_database_to_pretransaction_size', $applied['operations'][1]['reason']);
        $t->same('sync', $applied['operations'][2]['op']);
        $t->same(true, $applied['operations'][2]['durable']);
        $t->same('sync_rollback_recovered_database', $applied['operations'][2]['reason']);
        $t->same('delete', $applied['operations'][3]['op']);
        $t->same($databasePath . '-journal', $applied['operations'][3]['path']);
        $t->same($localJournalPath, $applied['operations'][3]['local_path']);
        $t->same('delete_hot_rollback_journal', $applied['operations'][3]['reason']);
        $t->same('sync_directory', $applied['operations'][4]['op']);
        $t->same(dirname($localDatabasePath), $applied['operations'][4]['local_path']);
        $t->same('persist_rollback_journal_deletion', $applied['operations'][4]['reason']);
        $t->same(1024, filesize($localDatabasePath));
        $t->same(false, is_file($localJournalPath));
        $t->same($pageOneClean, substr((string) file_get_contents($localDatabasePath), 0, $pageSize));
        $t->same($pageTwoClean, substr((string) file_get_contents($localDatabasePath), $pageSize, $pageSize));
        $t->same(false, str_contains((string) file_get_contents($localDatabasePath), 'X'));
        $t->same(false, str_contains((string) file_get_contents($localDatabasePath), 'I'));

        file_put_contents($localJournalPath, $journalBytes);
        $locked = $writer->applyHotRollbackJournal($journal, $dirtyDatabase, $journalBytes, $databasePath, true);
        $t->same('skipped', $locked['status']);
        $t->same(0, $locked['applied']);
        $t->same(0, $locked['bytes_written']);
        $t->same(0, $locked['files_deleted']);
        $t->same(false, $locked['recovery']['recovered']);
        $t->same('database_has_reserved_lock', $locked['recovery']['reason']);
        $t->same(true, is_file($localJournalPath));

        $superJournalBlocked = $writer->applyHotRollbackJournal($journal, $dirtyDatabase, $journalBytes, $databasePath, false, true, false);
        $t->same('skipped', $superJournalBlocked['status']);
        $t->same('missing_super_journal', $superJournalBlocked['recovery']['reason']);
        $t->same(true, $superJournalBlocked['recovery']['hot_journal']['requires_super_journal']);
        $t->same(false, $superJournalBlocked['recovery']['hot_journal']['super_journal_exists']);

        $manualDelete = $writer->applyOperations([
            ['op' => 'delete', 'path' => '/tmp/already-missing-journal', 'reason' => 'idempotent_delete'],
        ]);
        $t->same('applied', $manualDelete['status']);
        $t->same(1, $manualDelete['applied']);
        $t->same(1, $manualDelete['files_deleted']);
        $t->same('delete', $manualDelete['operations'][0]['op']);
        $t->same('idempotent_delete', $manualDelete['operations'][0]['reason']);

        $readOnly = new SQLiteVfsFileWriter($root, true);
        $immutable = new SQLiteVfsFileWriter($root, false, true);
        $t->throws(LogicException::class, static fn () => $readOnly->applyHotRollbackJournal($journal, $dirtyDatabase, $journalBytes, $databasePath));
        $t->throws(LogicException::class, static fn () => $immutable->applyHotRollbackJournal($journal, $dirtyDatabase, $journalBytes, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyHotRollbackJournal($journal, substr($dirtyDatabase, 1), $journalBytes, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applyHotRollbackJournal($journal, $dirtyDatabase, $journalBytes, ''));
    },
    'plans sqlite pager rollback journal open and no-write closure' => static function (TestRunner $t): void {
        $pageSize = 512;
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';

        $delete = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, $pageSize, 'delete');
        $t->same('planned', $delete['status']);
        $t->same($databasePath, $delete['database_path']);
        $t->same($databasePath . '-journal', $delete['journal_path']);
        $t->same($pageSize, $delete['page_size']);
        $t->same('delete', $delete['journal_mode']);
        $t->same(null, $delete['reason']);
        $t->same('planned', $delete['open']['status']);
        $t->same('planned', $delete['close']['status']);
        $t->same(['write', 'delete', 'sync_directory'], array_column($delete['operations'], 'op'));
        $t->same(['open_zeroed_rollback_journal_header', 'delete_unused_rollback_journal_on_transaction_close', 'persist_rollback_journal_open_close_sidecar'], array_column($delete['operations'], 'reason'));
        $t->same([$databasePath . '-journal#zero-header'], array_keys($delete['payloads']));
        $t->same(28, strlen($delete['payloads'][$databasePath . '-journal#zero-header']));
        $t->same(str_repeat("\0", 28), $delete['payloads'][$databasePath . '-journal#zero-header']);
        $t->same(['sqlite-pager-rollback-journal-open', 'vfs-file-handle-write-application', 'sqlite-pager-rollback-journal-close', 'sqlite-pager-transaction-journal-open-closure'], $delete['dependencies']);

        $truncate = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, $pageSize, 'truncate');
        $t->same('truncate', $truncate['journal_mode']);
        $t->same(['write', 'truncate', 'sync_directory'], array_column($truncate['operations'], 'op'));
        $t->same(0, $truncate['operations'][1]['bytes']);
        $t->same('truncate_unused_rollback_journal_on_transaction_close', $truncate['operations'][1]['reason']);

        $persist = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, $pageSize, 'persist');
        $t->same('persist', $persist['journal_mode']);
        $t->same(['write', 'write', 'sync_directory'], array_column($persist['operations'], 'op'));
        $t->same([$databasePath . '-journal#zero-header', $databasePath . '-journal#persist-zero-header'], array_keys($persist['payloads']));
        $t->same(28, $persist['operations'][1]['bytes']);
        $t->same('preserve_unused_journal_with_zeroed_header', $persist['operations'][1]['reason']);

        $readOnly = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, $pageSize, 'delete', readOnly: true);
        $t->same('blocked', $readOnly['status']);
        $t->same('read_only_database_handle', $readOnly['reason']);
        $t->same([], $readOnly['operations']);

        $immutable = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, $pageSize, 'delete', immutable: true);
        $t->same('blocked', $immutable['status']);
        $t->same('immutable_database_handle', $immutable['reason']);

        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages('', $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, 500));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, $pageSize, 'wal'));
    },
    'blocks sqlite pager journal open on hot rollback journals before write transactions' => static function (TestRunner $t): void {
        $pageSize = 512;
        $sectorSize = 512;
        $nonce = 0x01020304;
        $page = str_pad('clean app_settings page before failed transaction', $pageSize, "\0");
        $journalBytes = str_pad(SQLiteRollbackJournalHeader::MAGIC . pack('N*', 1, $nonce, 1, $sectorSize, $pageSize), $sectorSize, "\0")
            . pack('N', 1) . $page . pack('N', SQLiteRollbackJournal::pageChecksum($page, $nonce));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';

        $blocked = SQLitePagerJournalOpenPlan::open($databasePath, $pageSize, 'delete', $journalBytes);
        $t->same('recovery-required', $blocked['status']);
        $t->same('hot_rollback_journal_must_be_recovered_before_write_transaction', $blocked['reason']);
        $t->same([], $blocked['operations']);
        $t->same([], $blocked['payloads']);
        $t->same(true, $blocked['hot_journal']['hot']);
        $t->same('hot_journal_recovery_required', $blocked['hot_journal']['reason']);
        $t->same(strlen($journalBytes), $blocked['hot_journal']['journal_bytes']);
        $t->same(1, $blocked['hot_journal']['page_count']);
        $t->same(1, $blocked['hot_journal']['initial_database_page_count']);
        $t->same(['sqlite-pager-rollback-journal-open', 'hot-journal-before-write-transaction'], $blocked['dependencies']);

        $reservedLock = SQLitePagerJournalOpenPlan::open($databasePath, $pageSize, 'delete', $journalBytes, databaseReservedLock: true);
        $t->same('planned', $reservedLock['status']);
        $t->same(false, $reservedLock['hot_journal']['hot']);
        $t->same('database_has_reserved_lock', $reservedLock['hot_journal']['reason']);
        $t->same(['write'], array_column($reservedLock['operations'], 'op'));

        $invalidHeader = SQLitePagerJournalOpenPlan::open($databasePath, $pageSize, 'delete', str_repeat('x', 520));
        $t->same('planned', $invalidHeader['status']);
        $t->same(false, $invalidHeader['hot_journal']['hot']);
        $t->same('invalid_journal_header', $invalidHeader['hot_journal']['reason']);
    },
    'applies sqlite pager journal open and closure operations to local vfs handles' => static function (TestRunner $t): void {
        $root = sys_get_temp_dir() . '/port-libsqlite-pager-journal-open-' . bin2hex(random_bytes(4));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';
        $localDatabaseDirectory = $root . dirname($databasePath);
        if (!is_dir($localDatabaseDirectory) && !mkdir($localDatabaseDirectory, 0777, true) && !is_dir($localDatabaseDirectory)) {
            throw new RuntimeException('Unable to create pager journal test directory');
        }

        $writer = new SQLiteVfsFileWriter($root);
        $delete = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, 512, 'delete');
        $deleteApplied = $writer->applyOperations($delete['operations'], $delete['payloads'], $delete['dependencies']);
        $t->same('applied', $deleteApplied['status']);
        $t->same(3, $deleteApplied['applied']);
        $t->same(28, $deleteApplied['bytes_written']);
        $t->same(1, $deleteApplied['files_deleted']);
        $t->same(1, $deleteApplied['directory_syncs']);
        $t->same(false, is_file($root . $databasePath . '-journal'));
        $t->same(['write', 'delete', 'sync_directory'], array_column($deleteApplied['operations'], 'op'));

        $truncate = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, 512, 'truncate');
        $truncateApplied = $writer->applyOperations($truncate['operations'], $truncate['payloads'], $truncate['dependencies']);
        $t->same(3, $truncateApplied['applied']);
        $t->same(28, $truncateApplied['bytes_written']);
        $t->same(0, filesize($root . $databasePath . '-journal'));
        $t->same(0, $truncateApplied['bytes_truncated']);

        $persist = SQLitePagerJournalOpenPlan::openAndCloseWithoutDirtyPages($databasePath, 512, 'persist');
        $persistApplied = $writer->applyOperations($persist['operations'], $persist['payloads'], $persist['dependencies']);
        $t->same(3, $persistApplied['applied']);
        $t->same(56, $persistApplied['bytes_written']);
        $t->same(28, filesize($root . $databasePath . '-journal'));
        $t->same(str_repeat("\0", 28), file_get_contents($root . $databasePath . '-journal'));
        $t->same(['sqlite-pager-rollback-journal-open', 'vfs-file-handle-write-application', 'sqlite-pager-rollback-journal-close', 'sqlite-pager-transaction-journal-open-closure'], $persistApplied['dependencies']);

        $readOnlyWriter = new SQLiteVfsFileWriter($root, readOnly: true);
        $t->throws(LogicException::class, static fn () => $readOnlyWriter->applyOperations($persist['operations'], $persist['payloads'], $persist['dependencies']));
    },
    'resolves sqlite wal reader page images through the last committed frame' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x33333333;
        $salt2 = 0x44444444;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 4, $salt1, $salt2, 0, 0);
        $basePageOne = $makeFirstPage($pageSize, 3);
        $basePageTwo = str_repeat('B', $pageSize);
        $basePageThree = str_repeat('C', $pageSize);
        $walPageTwoCommitted = str_repeat('W', $pageSize);
        $walPageThreeCommitted = str_repeat('Z', $pageSize);
        $walPageTwoTail = str_repeat('T', $pageSize);
        $walBytes = $walHeader
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . str_repeat('A', $pageSize)
            . pack('N*', 2, 3, $salt1, $salt2, 0, 0) . $walPageTwoCommitted
            . pack('N*', 3, 3, $salt1, $salt2, 0, 0) . $walPageThreeCommitted
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $walPageTwoTail;

        $wal = SQLiteWal::parse($walBytes);
        $baseDatabase = $basePageOne . $basePageTwo . $basePageThree;

        $pageOne = $wal->readerPageImage($baseDatabase, 1);
        $pageTwo = $wal->readerPageImage($baseDatabase, 2);
        $pageThree = $wal->readerPageImage($baseDatabase, 3);

        $t->same('database', $pageOne['source']);
        $t->same(null, $pageOne['frame_index']);
        $t->same($basePageOne, $pageOne['image']);
        $t->same('wal', $pageTwo['source']);
        $t->same(2, $pageTwo['frame_index']);
        $t->same($walPageTwoCommitted, $pageTwo['image']);
        $t->same(4, $pageTwo['snapshot_end_frame']);
        $t->same(3, $pageTwo['snapshot_commit_frame']);
        $t->same(3, $pageTwo['database_page_count']);
        $t->same('wal', $pageThree['source']);
        $t->same(3, $pageThree['frame_index']);
        $t->same($walPageThreeCommitted, $pageThree['image']);
        $t->same(false, str_contains($pageTwo['image'], 'T'));
        $t->same([
            [
                'page_number' => 1,
                'source' => 'database',
                'frame_index' => null,
                'database_offset' => 0,
                'snapshot_end_frame' => 4,
                'snapshot_commit_frame' => 3,
                'database_page_count' => 3,
            ],
            [
                'page_number' => 2,
                'source' => 'wal',
                'frame_index' => 2,
                'database_offset' => 512,
                'snapshot_end_frame' => 4,
                'snapshot_commit_frame' => 3,
                'database_page_count' => 3,
            ],
            [
                'page_number' => 3,
                'source' => 'wal',
                'frame_index' => 3,
                'database_offset' => 1024,
                'snapshot_end_frame' => 4,
                'snapshot_commit_frame' => 3,
                'database_page_count' => 3,
            ],
        ], $wal->readerPageMap($baseDatabase));
        $t->throws(OutOfBoundsException::class, static fn () => $wal->readerPageImage($baseDatabase, 4));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->readerPageImage($baseDatabase, 0));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->readerPageMap(substr($baseDatabase, 1)));
    },
    'resolves sqlite wal reader snapshots at bounded end frames' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x12121212;
        $salt2 = 0x34343434;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 6, $salt1, $salt2, 0, 0);
        $basePageOne = $makeFirstPage($pageSize, 2);
        $basePageTwo = str_repeat('B', $pageSize);
        $basePageThree = str_repeat('C', $pageSize);
        $firstCommitPageTwo = str_repeat('F', $pageSize);
        $secondCommitPageTwo = str_repeat('S', $pageSize);
        $secondCommitPageThree = str_repeat('3', $pageSize);
        $uncommittedPageTwo = str_repeat('U', $pageSize);
        $walBytes = $walHeader
            . pack('N*', 2, 2, $salt1, $salt2, 0, 0) . $firstCommitPageTwo
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . str_repeat('P', $pageSize)
            . pack('N*', 3, 0, $salt1, $salt2, 0, 0) . $secondCommitPageThree
            . pack('N*', 2, 3, $salt1, $salt2, 0, 0) . $secondCommitPageTwo
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $uncommittedPageTwo;

        $wal = SQLiteWal::parse($walBytes);
        $baseDatabase = $basePageOne . $basePageTwo . $basePageThree;

        $beforeCommit = $wal->readerSnapshot($baseDatabase, 0);
        $t->same(0, $beforeCommit['end_frame']);
        $t->same(null, $beforeCommit['commit_frame']);
        $t->same(3, $beforeCommit['database_page_count']);
        $beforeCommitPageTwo = $wal->readerSnapshotPageImage($baseDatabase, 2, 0);
        $t->same('database', $beforeCommitPageTwo['source']);
        $t->same(null, $beforeCommitPageTwo['frame_index']);
        $t->same($basePageTwo, $beforeCommitPageTwo['image']);
        $t->same(0, $beforeCommitPageTwo['snapshot_end_frame']);
        $t->same(null, $beforeCommitPageTwo['snapshot_commit_frame']);
        $t->same(3, $beforeCommitPageTwo['database_page_count']);

        $firstSnapshot = $wal->readerSnapshot($baseDatabase, 1);
        $t->same(1, $firstSnapshot['end_frame']);
        $t->same(1, $firstSnapshot['commit_frame']->index);
        $t->same(2, $firstSnapshot['database_page_count']);
        $firstPageTwo = $wal->readerSnapshotPageImage($baseDatabase, 2, 1);
        $t->same('wal', $firstPageTwo['source']);
        $t->same(1, $firstPageTwo['frame_index']);
        $t->same($firstCommitPageTwo, $firstPageTwo['image']);
        $t->same(1, $firstPageTwo['snapshot_end_frame']);
        $t->same(1, $firstPageTwo['snapshot_commit_frame']);
        $t->same(2, $firstPageTwo['database_page_count']);
        $t->throws(OutOfBoundsException::class, static fn () => $wal->readerSnapshotPageImage($baseDatabase, 3, 1));

        $midTransactionPageTwo = $wal->readerSnapshotPageImage($baseDatabase, 2, 3);
        $t->same('wal', $midTransactionPageTwo['source']);
        $t->same(1, $midTransactionPageTwo['frame_index']);
        $t->same($firstCommitPageTwo, $midTransactionPageTwo['image']);
        $t->same(3, $midTransactionPageTwo['snapshot_end_frame']);
        $t->same(1, $midTransactionPageTwo['snapshot_commit_frame']);
        $t->same(false, str_contains($midTransactionPageTwo['image'], 'P'));
        $t->throws(OutOfBoundsException::class, static fn () => $wal->readerSnapshotPageImage($baseDatabase, 3, 3));

        $secondSnapshot = $wal->readerSnapshot($baseDatabase, 4);
        $t->same(4, $secondSnapshot['end_frame']);
        $t->same(4, $secondSnapshot['commit_frame']->index);
        $t->same(3, $secondSnapshot['database_page_count']);
        $secondPageTwo = $wal->readerSnapshotPageImage($baseDatabase, 2, 4);
        $secondPageThree = $wal->readerSnapshotPageImage($baseDatabase, 3, 4);
        $t->same(4, $secondPageTwo['frame_index']);
        $t->same($secondCommitPageTwo, $secondPageTwo['image']);
        $t->same(3, $secondPageThree['frame_index']);
        $t->same($secondCommitPageThree, $secondPageThree['image']);
        $t->same(false, str_contains($secondPageTwo['image'], 'U'));
        $t->same([
            [
                'page_number' => 1,
                'source' => 'database',
                'frame_index' => null,
                'database_offset' => 0,
                'snapshot_end_frame' => 4,
                'snapshot_commit_frame' => 4,
                'database_page_count' => 3,
            ],
            [
                'page_number' => 2,
                'source' => 'wal',
                'frame_index' => 4,
                'database_offset' => 512,
                'snapshot_end_frame' => 4,
                'snapshot_commit_frame' => 4,
                'database_page_count' => 3,
            ],
            [
                'page_number' => 3,
                'source' => 'wal',
                'frame_index' => 3,
                'database_offset' => 1024,
                'snapshot_end_frame' => 4,
                'snapshot_commit_frame' => 4,
                'database_page_count' => 3,
            ],
        ], $wal->readerSnapshotPageMap($baseDatabase, 4));

        $latestPageTwo = $wal->readerSnapshotPageImage($baseDatabase, 2);
        $t->same(4, $latestPageTwo['frame_index']);
        $t->same(5, $latestPageTwo['snapshot_end_frame']);
        $t->same(4, $latestPageTwo['snapshot_commit_frame']);
        $t->throws(InvalidArgumentException::class, static fn () => $wal->readerSnapshot($baseDatabase, -1));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->readerSnapshot($baseDatabase, 6));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->readerSnapshot(substr($baseDatabase, 1), 4));
        $t->throws(InvalidArgumentException::class, static fn () => $wal->readerSnapshotPageMap(substr($baseDatabase, 1), 4));
    },
    'opens sqlite databases with sidecar wal page overlays' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x26262626;
        $salt2 = 0x47474747;
        $basePageOne = $makeFirstPage($pageSize, 2);
        $basePageTwo = str_pad('base-siteurl=https://example.test/base', $pageSize, '.');
        $baseDatabase = $basePageOne . $basePageTwo;
        $walPageTwoFirst = str_pad('wal-siteurl=https://example.test/first', $pageSize, '1');
        $walPageThree = str_pad('wal-option=blog_public:1', $pageSize, '3');
        $walPageTwoSecond = str_pad('wal-siteurl=https://example.test/second', $pageSize, '2');
        $walTail = str_pad('uncommitted-draft=https://example.test/draft', $pageSize, 'u');
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 17, $salt1, $salt2, 0, 0);
        $walBytes = $walHeader
            . pack('N*', 2, 2, $salt1, $salt2, 0, 0) . $walPageTwoFirst
            . pack('N*', 3, 0, $salt1, $salt2, 0, 0) . $walPageThree
            . pack('N*', 2, 3, $salt1, $salt2, 0, 0) . $walPageTwoSecond
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . $walTail;

        $view = SQLiteWalOpenView::fromBytes($baseDatabase, $walBytes);
        $t->same(SQLiteWalOpenView::class, get_class($view));
        $t->same(512, $view->pageSize());
        $t->same(true, $view->hasWal());
        $t->same(2, $view->baseDatabasePageCount());
        $t->same(4, $view->wal->frameCount());
        $t->same(1, $view->wal->uncommittedFrameCount());

        $latestSnapshot = $view->snapshot();
        $t->same(4, $latestSnapshot['end_frame']);
        $t->same(3, $latestSnapshot['commit_frame']->index);
        $t->same(3, $latestSnapshot['database_page_count']);

        $pageOne = $view->pageImage(1);
        $pageTwo = $view->pageImage(2);
        $pageThree = $view->pageImage(3);
        $t->same('database', $pageOne['source']);
        $t->same(null, $pageOne['frame_index']);
        $t->same($basePageOne, $pageOne['image']);
        $t->same('wal', $pageTwo['source']);
        $t->same(3, $pageTwo['frame_index']);
        $t->same($walPageTwoSecond, $pageTwo['image']);
        $t->same(4, $pageTwo['snapshot_end_frame']);
        $t->same(3, $pageTwo['snapshot_commit_frame']);
        $t->same('wal', $pageThree['source']);
        $t->same(2, $pageThree['frame_index']);
        $t->same($walPageThree, $pageThree['image']);
        $t->same(false, str_contains($pageTwo['image'], 'draft'));

        $firstSnapshotPageTwo = $view->pageImage(2, 1);
        $t->same(1, $firstSnapshotPageTwo['frame_index']);
        $t->same($walPageTwoFirst, $firstSnapshotPageTwo['image']);
        $t->same(1, $firstSnapshotPageTwo['snapshot_end_frame']);
        $t->same(1, $firstSnapshotPageTwo['snapshot_commit_frame']);
        $t->throws(OutOfBoundsException::class, static fn () => $view->pageImage(3, 1));

        $effectiveDatabase = $view->databaseImage();
        $t->same(3 * $pageSize, strlen($effectiveDatabase));
        $t->same($basePageOne, substr($effectiveDatabase, 0, $pageSize));
        $t->same($walPageTwoSecond, substr($effectiveDatabase, $pageSize, $pageSize));
        $t->same($walPageThree, substr($effectiveDatabase, $pageSize * 2, $pageSize));
        $t->same(false, str_contains($effectiveDatabase, 'uncommitted-draft'));

        $map = $view->pageMap();
        $t->same(3, count($map));
        $t->same(['database', 'wal', 'wal'], array_column($map, 'source'));
        $t->same([null, 3, 2], array_column($map, 'frame_index'));
        $t->same([0, 512, 1024], array_column($map, 'database_offset'));

        $checkpoint = $view->checkpointResult('passive');
        $t->same('uncommitted_frames_after_last_commit', $checkpoint['reason']);
        $t->same('preserve_wal', $checkpoint['wal_action']);
        $t->same(2, $checkpoint['checkpointed_frame_count']);
        $t->same(1, $checkpoint['uncommitted_frame_count']);
        $t->same($effectiveDatabase, $checkpoint['database_bytes']);

        $summary = $view->toArray();
        $t->same(true, $summary['has_wal']);
        $t->same(4, $summary['snapshot_end_frame']);
        $t->same(3, $summary['snapshot_commit_frame']);
        $t->same(3, $summary['snapshot_database_page_count']);
        $t->same(4, $summary['wal_frame_count']);
        $t->same(1, $summary['wal_uncommitted_frame_count']);
        $t->same($map, $summary['page_map']);

        $databaseOnly = SQLiteWalOpenView::fromBytes($baseDatabase);
        $t->same(false, $databaseOnly->hasWal());
        $t->same(2, $databaseOnly->snapshot()['database_page_count']);
        $t->same($basePageTwo, $databaseOnly->pageImage(2)['image']);
        $t->same($baseDatabase, $databaseOnly->databaseImage());
        $t->same('wal_file_missing', $databaseOnly->checkpointResult('truncate')['reason']);
        $t->same('no_wal_file', $databaseOnly->checkpointResult('truncate')['wal_action']);
        $t->throws(InvalidArgumentException::class, static fn () => $databaseOnly->snapshot(1));
        $t->throws(InvalidArgumentException::class, static fn () => $databaseOnly->checkpointResult('invalid'));
        $t->throws(InvalidArgumentException::class, static fn () => $databaseOnly->checkpointResult('passive', -1));

        $tmpBase = tempnam(sys_get_temp_dir(), 'libsqlite-wal-open-');
        if ($tmpBase === false) {
            throw new RuntimeException('Unable to create temporary database path');
        }
        $databasePath = $tmpBase . '.sqlite';
        @unlink($tmpBase);
        $walPath = $databasePath . '-wal';
        file_put_contents($databasePath, $baseDatabase);
        file_put_contents($walPath, $walBytes);
        try {
            $fileView = SQLiteWalOpenView::fromFiles($databasePath);
            $t->same(true, $fileView->hasWal());
            $t->same($walPageTwoSecond, $fileView->pageImage(2)['image']);
            $t->same(3 * $pageSize, strlen($fileView->databaseImage()));
            unlink($walPath);
            $fileViewWithoutWal = SQLiteWalOpenView::fromFiles($databasePath);
            $t->same(false, $fileViewWithoutWal->hasWal());
            $t->same($baseDatabase, $fileViewWithoutWal->databaseImage());
        } finally {
            @unlink($databasePath);
            @unlink($walPath);
        }

        $badWal = substr_replace($walBytes, pack('N', 0x99999999), 32 + 8, 4);
        $mismatchedPageSizeWal = substr_replace($walBytes, pack('N', 1024), 8, 4);
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWalOpenView::fromBytes($baseDatabase, $badWal));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWalOpenView::fromBytes($baseDatabase, $mismatchedPageSizeWal));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWalOpenView::fromBytes(substr($baseDatabase, 1), $walBytes));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWalOpenView::fromFiles('/path/that/does/not/exist.sqlite'));
    },
    'plans sqlite wal-index read marks for pinned reader checkpoints' => static function (TestRunner $t): void {
        $pageSize = 512;
        $salt1 = 0x56565656;
        $salt2 = 0x78787878;
        $walHeader = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 14, $salt1, $salt2, 0, 0);
        $wal = SQLiteWal::parse(
            $walHeader
            . pack('N*', 2, 2, $salt1, $salt2, 0, 0) . str_repeat('A', $pageSize)
            . pack('N*', 3, 0, $salt1, $salt2, 0, 0) . str_repeat('B', $pageSize)
            . pack('N*', 4, 4, $salt1, $salt2, 0, 0) . str_repeat('C', $pageSize)
            . pack('N*', 2, 4, $salt1, $salt2, 0, 0) . str_repeat('D', $pageSize)
            . pack('N*', 2, 0, $salt1, $salt2, 0, 0) . str_repeat('E', $pageSize)
        );

        $plan = $wal->readMarkPlan([0, 2, 4, null, 9]);
        $t->same(5, $plan['mx_frame']);
        $t->same(4, $plan['last_commit_frame']);
        $t->same(2, $plan['checkpoint_pinned_frame']);
        $t->same(false, $plan['checkpoint_can_finish']);
        $t->same(true, $plan['reset_blocked']);
        $t->same([0, 1, 3, 4], $plan['reusable_slots']);
        $t->same(0, $plan['recommended_reader_slot']);
        $t->same(4, $plan['recommended_reader_frame']);
        $t->same(5, count($plan['read_marks']));

        $t->same(0, $plan['read_marks'][0]['slot']);
        $t->same(0, $plan['read_marks'][0]['frame']);
        $t->same(true, $plan['read_marks'][0]['active']);
        $t->same(true, $plan['read_marks'][0]['valid']);
        $t->same(true, $plan['read_marks'][0]['stale']);
        $t->same(false, $plan['read_marks'][0]['pins_checkpoint']);
        $t->same('database_only_reader_before_wal_commit', $plan['read_marks'][0]['reason']);

        $t->same(1, $plan['read_marks'][1]['slot']);
        $t->same(2, $plan['read_marks'][1]['frame']);
        $t->same(true, $plan['read_marks'][1]['active']);
        $t->same(true, $plan['read_marks'][1]['valid']);
        $t->same(true, $plan['read_marks'][1]['stale']);
        $t->same(true, $plan['read_marks'][1]['pins_checkpoint']);
        $t->same('reader_pins_older_snapshot', $plan['read_marks'][1]['reason']);

        $t->same(2, $plan['read_marks'][2]['slot']);
        $t->same(4, $plan['read_marks'][2]['frame']);
        $t->same(true, $plan['read_marks'][2]['active']);
        $t->same(true, $plan['read_marks'][2]['valid']);
        $t->same(false, $plan['read_marks'][2]['stale']);
        $t->same(false, $plan['read_marks'][2]['pins_checkpoint']);
        $t->same('pins_latest_commit', $plan['read_marks'][2]['reason']);

        $t->same(3, $plan['read_marks'][3]['slot']);
        $t->same(null, $plan['read_marks'][3]['frame']);
        $t->same(false, $plan['read_marks'][3]['active']);
        $t->same(true, $plan['read_marks'][3]['valid']);
        $t->same(false, $plan['read_marks'][3]['stale']);
        $t->same(false, $plan['read_marks'][3]['pins_checkpoint']);
        $t->same('unused_slot', $plan['read_marks'][3]['reason']);

