    'loads sqlite shm wal-index headers and checkpoint read marks' => static function (TestRunner $t): void {
        $pageSize = 512;
        $encodedPageSize = (1 << 24) | (1 << 16) | $pageSize;
        $header = pack(
            'V*',
            3007000,
            2,
            17,
            $encodedPageSize,
            6,
            4,
            0x11111111,
            0x22222222,
            0x33333333,
            0x44444444,
            0x55555555,
            0x66666666
        );
        $checkpoint = pack('V*', 2, 0, 3, 6, 0xffffffff, 9)
            . "\x00\x01\x01\x00\x01\x00\x00\x00"
            . pack('V*', 5, 0);
        $shmBytes = $header . $header . $checkpoint . str_repeat("\0", 256);

        $index = SQLiteShmIndex::parse($shmBytes);
        $t->same('little-endian', $index->byteOrder);
        $t->same(true, $index->headersMatch);
        $t->same(3007000, $index->header['version']);
        $t->same(17, $index->header['change_counter']);
        $t->same($pageSize, $index->header['page_size']);
        $t->same(true, $index->header['initialized']);
        $t->same(true, $index->header['big_endian_checksums']);
        $t->same(6, $index->header['mx_frame']);
        $t->same(4, $index->header['database_page_count']);
        $t->same(2, $index->header['backfill_hint']);
        $t->same([0x11111111, 0x22222222], $index->header['frame_checksum']);
        $t->same([0x33333333, 0x44444444], $index->header['salt']);
        $t->same([0x55555555, 0x66666666], $index->header['checksum']);
        $t->same(2, $index->backfilledFrameCount);
        $t->same(5, $index->backfillAttemptedFrameCount);

        $plan = $index->checkpointPlan();
        $t->same('ready', $plan['status']);
        $t->same(false, $plan['checkpoint_can_finish']);
        $t->same(true, $plan['reset_blocked']);
        $t->same(true, $plan['headers_match']);
        $t->same(6, $plan['mx_frame']);
        $t->same(2, $plan['backfilled_frame_count']);
        $t->same(5, $plan['backfill_attempted_frame_count']);
        $t->same(3, $plan['checkpoint_pinned_frame']);
        $t->same([0, 3, 4], $plan['reusable_slots']);
        $t->same(['sqlite-shm-index', 'wal-index-read-marks', 'wal-index-read-locks', 'checkpoint-backfill-state'], $plan['dependencies']);
        $t->same([false, true, true, false, true], $plan['read_locks']);
        $t->same(5, count($plan['read_marks']));

        $t->same(0, $plan['read_marks'][0]['slot']);
        $t->same(0, $plan['read_marks'][0]['frame']);
        $t->same(true, $plan['read_marks'][0]['active']);
        $t->same(true, $plan['read_marks'][0]['valid']);
        $t->same(true, $plan['read_marks'][0]['stale']);
        $t->same(false, $plan['read_marks'][0]['pins_checkpoint']);
        $t->same('database_only_reader', $plan['read_marks'][0]['reason']);

        $t->same(1, $plan['read_marks'][1]['slot']);
        $t->same(3, $plan['read_marks'][1]['frame']);
        $t->same(true, $plan['read_marks'][1]['active']);
        $t->same(true, $plan['read_marks'][1]['valid']);
        $t->same(true, $plan['read_marks'][1]['stale']);
        $t->same(true, $plan['read_marks'][1]['pins_checkpoint']);
        $t->same('reader_pins_checkpoint_backfill', $plan['read_marks'][1]['reason']);

        $t->same(2, $plan['read_marks'][2]['slot']);
        $t->same(6, $plan['read_marks'][2]['frame']);
        $t->same(false, $plan['read_marks'][2]['stale']);
        $t->same(false, $plan['read_marks'][2]['pins_checkpoint']);
        $t->same('pins_latest_commit', $plan['read_marks'][2]['reason']);

        $t->same(3, $plan['read_marks'][3]['slot']);
        $t->same(null, $plan['read_marks'][3]['frame']);
        $t->same(false, $plan['read_marks'][3]['active']);
        $t->same(true, $plan['read_marks'][3]['valid']);
        $t->same('unused_slot', $plan['read_marks'][3]['reason']);

        $t->same(4, $plan['read_marks'][4]['slot']);
        $t->same(9, $plan['read_marks'][4]['frame']);
        $t->same(true, $plan['read_marks'][4]['active']);
        $t->same(false, $plan['read_marks'][4]['valid']);
        $t->same('beyond_wal_mx_frame', $plan['read_marks'][4]['reason']);

        $array = $index->toArray();
        $t->same('little-endian', $array['byte_order']);
        $t->same(2, $array['backfilled_frame_count']);
        $t->same(5, $array['backfill_attempted_frame_count']);
        $t->same(3, $array['checkpoint_plan']['checkpoint_pinned_frame']);

        $staleCopy = SQLiteShmIndex::parse($header . substr_replace($header, pack('V', 18), 8, 4) . $checkpoint);
        $t->same(false, $staleCopy->headersMatch);
        $t->same('stale-header-copy', $staleCopy->checkpointPlan()['status']);

        $bigHeader = pack('N*', 3007000, 0, 7, $pageSize, 2, 2, 1, 2, 3, 4, 5, 6);
        $bigCheckpoint = pack('N*', 0, 0, 2, 0xffffffff, 0xffffffff, 0xffffffff)
            . str_repeat("\0", 8)
            . pack('N*', 2, 0);
        $big = SQLiteShmIndex::parse($bigHeader . $bigHeader . $bigCheckpoint, 'big-endian');
        $t->same('big-endian', $big->byteOrder);
        $t->same(2, $big->header['mx_frame']);
        $t->same(true, $big->checkpointPlan()['checkpoint_can_finish']);

        $path = tempnam(sys_get_temp_dir(), 'sqlite-shm-index-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary SHM fixture');
        }
        try {
            file_put_contents($path, $shmBytes);
            $fromFile = SQLiteShmIndex::fromFile($path);
            $t->same(6, $fromFile->header['mx_frame']);
        } finally {
            @unlink($path);
        }

        $badShort = substr($shmBytes, 0, 120);
        $badPageSize = substr_replace($shmBytes, pack('V', (1 << 24) | 500), 12, 4);
        $badBackfillHint = substr_replace($shmBytes, pack('V', 7), 4, 4);
        $badBackfillCounter = substr_replace($shmBytes, pack('V', 7), 96, 4);
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteShmIndex::parse($badShort));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteShmIndex::parse($badPageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteShmIndex::parse($badBackfillHint));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteShmIndex::parse($badBackfillCounter));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteShmIndex::parse($shmBytes, 'middle-endian'));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteShmIndex::fromFile('/path/that/does/not/exist.sqlite-shm'));
    },
    'validates sqlite wal header and frame checksums when requested' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x01020304;
        $salt2 = 0x05060708;
        $headerPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 9, $salt1, $salt2);
        $headerChecksum = SQLiteWal::checksumPair($headerPrefix, false);
        $walBytes = $headerPrefix . pack('N*', $headerChecksum[0], $headerChecksum[1]);
        $checksumSeed = $headerChecksum;

        $appendFrame = static function (string $walBytes, array &$checksumSeed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $checksumSeed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $checksumSeed[0], $checksumSeed[1]);

            return $walBytes . $framePrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]) . $pageImage;
        };

        $pageOne = $makeFirstPage($pageSize, 2);
        $pageTwo = str_repeat('C', $pageSize);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 1, 0, $pageOne);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 2, $pageTwo);

        $wal = SQLiteWal::parse($walBytes, null, true);

        $t->same(true, $wal->checksumsValidated);
        $t->same(true, $wal->toArray()['checksums_validated']);
        $t->same($headerChecksum[0], $wal->header->checksum1);
        $t->same($headerChecksum[1], $wal->header->checksum2);
        $t->same($checksumSeed[0], $wal->frames[1]->checksum1);
        $t->same($checksumSeed[1], $wal->frames[1]->checksum2);
        $t->same([1, 2], array_keys($wal->pageImagesThroughLastCommit()));
        $t->same($pageTwo, $wal->pageImagesThroughLastCommit()[2]);

        $badHeaderChecksum = substr_replace($walBytes, pack('N', $headerChecksum[0] ^ 1), 24, 4);
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWal::parse($badHeaderChecksum, null, true));

        $badFrameChecksum = substr_replace($walBytes, pack('N', $checksumSeed[0] ^ 1), 32 + 24 + $pageSize + 16, 4);
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWal::parse($badFrameChecksum, null, true));
    },
    'finds sqlite wal checksum recovery boundary before corrupt tail frames' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x11121314;
        $salt2 = 0x21222324;
        $headerPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 4, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($headerPrefix, false);
        $walBytes = $headerPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);

        $appendFrame = static function (string $walBytes, array &$checksumSeed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $checksumSeed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $checksumSeed[0], $checksumSeed[1]);

            return $walBytes . $framePrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]) . $pageImage;
        };

        $pageOneBase = $makeFirstPage($pageSize, 2);
        $pageTwoBase = str_pad('app_settings base page', $pageSize, '.');
        $pageOneWal = $makeFirstPage($pageSize, 3);
        $pageTwoWal = str_pad('app_settings committed setting', $pageSize, '.');
        $pageThreeWal = str_pad('app_settings committed metadata', $pageSize, '.');
        $pageTwoCorrupt = str_pad('app_settings corrupt tail setting', $pageSize, '.');
        $databaseBytes = $pageOneBase . $pageTwoBase;

        $walBytes = $appendFrame($walBytes, $checksumSeed, 1, 0, $pageOneWal);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 0, $pageTwoWal);
        $validPrefixBytes = $appendFrame($walBytes, $checksumSeed, 3, 3, $pageThreeWal);
        $corruptWalBytes = $appendFrame($validPrefixBytes, $checksumSeed, 2, 3, $pageTwoCorrupt);
        $corruptWalBytes = substr_replace($corruptWalBytes, 'X', 32 + ((24 + $pageSize) * 3) + 24 + 12, 1);

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWal::parse($corruptWalBytes, null, true));

        $boundary = SQLiteWal::checksumRecoveryBoundary($corruptWalBytes, $databaseBytes);
        $wal = $boundary['wal'];
        $checkpointBytes = $boundary['checkpoint_database_bytes'];

        $t->same('recovered_prefix', $boundary['status']);
        $t->same('frame_checksum_mismatch', $boundary['reason']);
        $t->same(3, $boundary['valid_frame_count']);
        $t->same(4, $boundary['total_frame_slots']);
        $t->same(4, $boundary['first_invalid_frame']);
        $t->same(strlen($validPrefixBytes), $boundary['recovery_end_offset']);
        $t->same($validPrefixBytes, $boundary['valid_wal_bytes']);
        $t->same(true, $boundary['can_checkpoint']);
        $t->same(3, $boundary['last_commit_frame']);
        $t->same(3, $boundary['last_commit_page_count']);
        $t->same(0, $boundary['uncommitted_frame_count']);
        $t->same(3, $boundary['checkpoint_database_page_count']);
        $t->same(['sqlite-wal-checksum-recovery-boundary'], $boundary['dependencies']);
        $t->same(true, $wal instanceof SQLiteWal);
        $t->same(true, $wal->checksumsValidated);
        $t->same(3, $wal->frameCount());
        $t->same(3, $wal->lastCommitFrame()?->index);
        $t->same([1, 2, 3], array_keys($wal->pageImagesThroughLastCommit()));
        $t->same(false, str_contains($boundary['valid_wal_bytes'], 'corrupt tail'));
        $t->same(strlen($validPrefixBytes) + 24 + $pageSize, strlen($corruptWalBytes));
        $t->same(true, is_string($checkpointBytes));
        $t->same(true, str_contains((string) $checkpointBytes, 'app_settings committed setting'));
        $t->same(true, str_contains((string) $checkpointBytes, 'app_settings committed metadata'));
        $t->same(false, str_contains((string) $checkpointBytes, 'app_settings corrupt tail setting'));
        $t->same(true, str_contains($wal->readerSnapshotPageImage($databaseBytes, 2)['image'], 'app_settings committed setting'));
        $t->same(false, str_contains($wal->readerSnapshotPageImage($databaseBytes, 2)['image'], 'corrupt tail'));
    },
    'bounds sqlite wal recovery at header salt and truncated frame corruption' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x31323334;
        $salt2 = 0x41424344;
        $headerPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 6, $salt1, $salt2);
        $headerChecksum = SQLiteWal::checksumPair($headerPrefix, false);
        $header = $headerPrefix . pack('N*', $headerChecksum[0], $headerChecksum[1]);
        $checksumSeed = $headerChecksum;

        $appendFrame = static function (string $walBytes, array &$checksumSeed, int $pageNumber, int $commit, string $pageImage, ?int $frameSalt1 = null) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $frameSalt1 ?? $salt1, $salt2);
            $checksumSeed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $checksumSeed[0], $checksumSeed[1]);

            return $walBytes . $framePrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]) . $pageImage;
        };

        $databaseBytes = $makeFirstPage($pageSize, 1);
        $pageOne = $makeFirstPage($pageSize, 1);
        $pageTwo = str_pad('app_settings tail page', $pageSize, '.');

        $oneFrameWal = $appendFrame($header, $checksumSeed, 1, 1, $pageOne);
        $saltSeed = $checksumSeed;
        $saltCorruptWal = $appendFrame($oneFrameWal, $saltSeed, 2, 2, $pageTwo, $salt1 ^ 1);
        $saltBoundary = SQLiteWal::checksumRecoveryBoundary($saltCorruptWal, $databaseBytes);

        $t->same('recovered_prefix', $saltBoundary['status']);
        $t->same('frame_salt_mismatch', $saltBoundary['reason']);
        $t->same(1, $saltBoundary['valid_frame_count']);
        $t->same(2, $saltBoundary['total_frame_slots']);
        $t->same(2, $saltBoundary['first_invalid_frame']);
        $t->same(strlen($oneFrameWal), $saltBoundary['recovery_end_offset']);
        $t->same($oneFrameWal, $saltBoundary['valid_wal_bytes']);
        $t->same(1, $saltBoundary['last_commit_frame']);
        $t->same(1, $saltBoundary['last_commit_page_count']);
        $t->same(0, $saltBoundary['uncommitted_frame_count']);
        $t->same(1, $saltBoundary['checkpoint_database_page_count']);
        $t->same(true, str_contains((string) $saltBoundary['checkpoint_database_bytes'], 'SQLite format 3'));
        $t->same(false, str_contains($saltBoundary['valid_wal_bytes'], 'app_settings tail page'));

        $truncatedWal = $oneFrameWal . substr(pack('N*', 2, 2, $salt1, $salt2, 0, 0) . $pageTwo, 0, 100);
        $truncatedBoundary = SQLiteWal::checksumRecoveryBoundary($truncatedWal, $databaseBytes);

        $t->same('recovered_prefix', $truncatedBoundary['status']);
        $t->same('truncated_frame_tail', $truncatedBoundary['reason']);
        $t->same(1, $truncatedBoundary['valid_frame_count']);
        $t->same(2, $truncatedBoundary['total_frame_slots']);
        $t->same(2, $truncatedBoundary['first_invalid_frame']);
        $t->same(strlen($oneFrameWal), $truncatedBoundary['recovery_end_offset']);
        $t->same($oneFrameWal, $truncatedBoundary['valid_wal_bytes']);
        $t->same(1, $truncatedBoundary['wal']->frameCount());
        $t->same(1, $truncatedBoundary['last_commit_frame']);
        $t->same(true, $truncatedBoundary['can_checkpoint']);

        $badHeader = substr_replace($oneFrameWal, pack('N', $headerChecksum[0] ^ 7), 24, 4);
        $headerBoundary = SQLiteWal::checksumRecoveryBoundary($badHeader, $databaseBytes);

        $t->same('corrupt', $headerBoundary['status']);
        $t->same('header_checksum_mismatch', $headerBoundary['reason']);
        $t->same(0, $headerBoundary['valid_frame_count']);
        $t->same(0, $headerBoundary['total_frame_slots']);
        $t->same(0, $headerBoundary['first_invalid_frame']);
        $t->same(32, $headerBoundary['recovery_end_offset']);
        $t->same(substr($badHeader, 0, 32), $headerBoundary['valid_wal_bytes']);
        $t->same(0, $headerBoundary['wal']->frameCount());
        $t->same(null, $headerBoundary['last_commit_frame']);
        $t->same(false, $headerBoundary['can_checkpoint']);
        $t->same(null, $headerBoundary['checkpoint_database_bytes']);
    },
    'plans current-source wal reader pins across restart and truncate generations next119' => static function (TestRunner $t) use ($makeFirstPage): void {
        $pageSize = 512;
        $salt1 = 0x11911911;
        $salt2 = 0x11911922;
        $prefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 119, $salt1, $salt2);
        $seed = SQLiteWal::checksumPair($prefix, false);
        $walBytes = $prefix . pack('N*', $seed[0], $seed[1]);
        $append = static function (int $pageNumber, int $commit, string $image) use (&$walBytes, &$seed, $salt1, $salt2): void {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $image, false, $seed[0], $seed[1]);
            $walBytes .= $framePrefix . pack('N*', $seed[0], $seed[1]) . $image;
        };

        $baseDatabase = $makeFirstPage($pageSize, 5)
            . str_pad('wp119 active_plugins base', $pageSize, "\0")
            . str_pad('wp119 load_policy index base', $pageSize, "\0")
            . str_pad('wp119 cron base', $pageSize, "\0")
            . str_pad('wp119 transient base', $pageSize, "\0");
        $pageTwoPinned = str_pad('wp119 active_plugins reader-pinned frame', $pageSize, "\0");
        $pageThreePinnedCommit = str_pad('wp119 load_policy reader-pinned commit', $pageSize, "\0");
        $pageTwoLatest = str_pad('wp119 active_plugins latest checkpointed frame', $pageSize, "\0");
        $pageFourLatest = str_pad('wp119 cron latest checkpointed frame', $pageSize, "\0");
        $append(2, 0, $pageTwoPinned);
        $append(3, 5, $pageThreePinnedCommit);
        $append(2, 0, $pageTwoLatest);
        $append(4, 5, $pageFourLatest);

        $wal = SQLiteWal::parse($walBytes, null, true);
        $plan = $wal->restartTruncateReaderPinCurrentSourceNext($walBytes, $baseDatabase, [2, 3, 4, 5], [0, 2, 4, null]);

        $t->same('reader-pin-restart-truncate-current-source-next119', $plan['status']);
        $t->same('current-source', $plan['source_status']);
        $t->same(2, $plan['current_reader_end_frame']);
        $t->same(2, $plan['checkpoint_pinned_frame']);
        $t->same(true, $plan['pinned_restart_preserves_wal']);
        $t->same(true, $plan['pinned_truncate_preserves_wal']);
        $t->same(true, $plan['released_restart_uses_new_header']);
        $t->same(true, $plan['released_truncate_removes_wal']);
        $t->same(true, $plan['restart_truncate_database_match']);
        $t->same(false, $plan['current_restart_images_match']);
        $t->same(false, $plan['current_truncate_images_match']);
        $t->same(true, $plan['restart_truncate_images_match']);
        $t->same(['wal', 'wal', 'database', 'database'], $plan['current_sources']);
        $t->same(['wal', 'wal', 'wal', 'database'], $plan['pinned_next_sources']);
        $t->same(['database', 'database', 'database', 'database'], $plan['restart_next_sources']);
        $t->same(['database', 'database', 'database', 'database'], $plan['truncate_next_sources']);
        $t->same([1, 2, null, null], $plan['current_frame_indexes']);
        $t->same([3, 2, 4, null], $plan['pinned_next_frame_indexes']);
        $t->same([null, null, null, null], $plan['restart_next_frame_indexes']);
        $t->same([null, null, null, null], $plan['truncate_next_frame_indexes']);
        $t->same('reader_blocks_checkpoint_completion', $plan['pinned_restart']['reason']);
        $t->same('reader_blocks_checkpoint_completion', $plan['pinned_truncate']['reason']);
        $t->same('preserve_wal', $plan['pinned_restart']['wal_action']);
        $t->same('preserve_wal', $plan['pinned_truncate']['wal_action']);
        $t->same(strlen($walBytes), $plan['pinned_restart']['wal_bytes_length']);
        $t->same(strlen($walBytes), $plan['pinned_truncate']['wal_bytes_length']);
        $t->same('restart_checkpoint_can_reset_wal', $plan['released_restart']['reason']);
        $t->same('truncate_checkpoint_can_reset_and_truncate_wal', $plan['released_truncate']['reason']);
        $t->same('restart_wal', $plan['released_restart']['wal_action']);
