    'classifies sqlite rollback hot journal recovery candidates' => static function (TestRunner $t): void {
        $pageSize = 512;
        $sectorSize = 512;
        $nonce = 0x41424344;
        $page = str_repeat('H', $pageSize);
        $header = SQLiteRollbackJournalHeader::MAGIC . pack('N*', 1, $nonce, 2, $sectorSize, $pageSize);
        $journalBytes = str_pad($header, $sectorSize, "\0")
            . pack('N', 2) . $page . pack('N', SQLiteRollbackJournal::pageChecksum($page, $nonce));

        $hot = SQLiteRollbackJournal::hotJournalCandidate($journalBytes);
        $t->same(true, $hot['hot']);
        $t->same('hot_journal_recovery_required', $hot['reason']);
        $t->same(true, $hot['header_valid']);
        $t->same(1, $hot['page_count']);
        $t->same(2, $hot['initial_database_page_count']);
        $t->same(false, $hot['requires_super_journal']);
        $t->same(false, $hot['database_reserved_lock']);

        $locked = SQLiteRollbackJournal::hotJournalCandidate($journalBytes, databaseReservedLock: true);
        $t->same(false, $locked['hot']);
        $t->same('database_has_reserved_lock', $locked['reason']);
        $t->same(false, $locked['header_valid']);

        $short = SQLiteRollbackJournal::hotJournalCandidate(str_repeat("\0", 512));
        $t->same(false, $short['hot']);
        $t->same('journal_too_small', $short['reason']);

        $badHeader = SQLiteRollbackJournal::hotJournalCandidate(str_repeat('x', 520));
        $t->same(false, $badHeader['hot']);
        $t->same('invalid_journal_header', $badHeader['reason']);

        $unknownCountHeader = SQLiteRollbackJournalHeader::MAGIC . pack('N*', SQLiteRollbackJournalHeader::UNKNOWN_PAGE_COUNT, $nonce, 2, $sectorSize, $pageSize);
        $unknownCountBytes = str_pad($unknownCountHeader, $sectorSize, "\0")
            . pack('N', 2) . $page . pack('N', SQLiteRollbackJournal::pageChecksum($page, $nonce));
        $unknownCount = SQLiteRollbackJournal::hotJournalCandidate($unknownCountBytes);
        $t->same(true, $unknownCount['hot']);
        $t->same(SQLiteRollbackJournalHeader::UNKNOWN_PAGE_COUNT, $unknownCount['page_count']);
        $t->same(false, $unknownCount['requires_super_journal']);

        $unknownSuperJournal = SQLiteRollbackJournal::hotJournalCandidate($unknownCountBytes, requiresSuperJournal: true);
        $t->same(false, $unknownSuperJournal['hot']);
        $t->same('super_journal_status_unknown', $unknownSuperJournal['reason']);
        $t->same(true, $unknownSuperJournal['requires_super_journal']);
        $t->same(null, $unknownSuperJournal['super_journal_exists']);

        $missingSuperJournal = SQLiteRollbackJournal::hotJournalCandidate($unknownCountBytes, requiresSuperJournal: true, superJournalExists: false);
        $t->same(false, $missingSuperJournal['hot']);
        $t->same('missing_super_journal', $missingSuperJournal['reason']);
        $t->same(false, $missingSuperJournal['super_journal_exists']);

        $presentSuperJournal = SQLiteRollbackJournal::hotJournalCandidate($unknownCountBytes, requiresSuperJournal: true, superJournalExists: true);
        $t->same(true, $presentSuperJournal['hot']);
        $t->same('hot_journal_recovery_required', $presentSuperJournal['reason']);
        $t->same(true, $presentSuperJournal['super_journal_exists']);
    },
    'tracks sqlite savepoint rollback and release page diagnostics' => static function (TestRunner $t): void {
        $stack = new SQLiteSavepointStack();

        $stack->beginTransaction('outer');
        $stack->recordPageWrite(2);
        $stack->savepoint('plugin-import');
        $stack->recordPageWrite(5);
        $stack->recordPageWrite(7);
        $stack->savepoint('option-row');
        $stack->recordPageWrite(8);

        $t->same(true, $stack->transactionActive());
        $t->same(3, $stack->depth());
        $t->same(['outer', 'plugin-import', 'option-row'], $stack->names());
        $t->same([2, 5, 7, 8], $stack->pendingPageNumbers());
        $t->same([5, 7, 8], $stack->rollbackToPageNumbers('plugin-import'));
        $t->same([8], $stack->rollbackToPageNumbers('option-row'));
        $t->same([2, 5, 7, 8], $stack->rollbackToPageNumbers('outer'));
        $t->same([
            'savepoint' => 'plugin-import',
            'found_index' => 1,
            'retained_depth' => 2,
            'discarded_frame_names' => ['option-row'],
            'rollback_page_numbers' => [5, 7, 8],
            'target_frame_cleared' => true,
            'transaction_active_after' => true,
        ], $stack->rollbackToPlan('plugin-import'));

        $stack->rollbackTo('plugin-import');
        $t->same(2, $stack->depth());
        $t->same(['outer', 'plugin-import'], $stack->names());
        $t->same([], $stack->rollbackToPageNumbers('plugin-import'));
        $t->same([
            [
                'name' => 'outer',
                'transaction' => true,
                'page_numbers' => [2],
            ],
            [
                'name' => 'plugin-import',
                'transaction' => false,
                'page_numbers' => [],
            ],
        ], $stack->toArray());

        $stack->recordPageWrite(6);
        $t->same([
            'savepoint' => 'plugin-import',
            'found_index' => 1,
            'released_frame_names' => ['plugin-import'],
            'merged_page_numbers' => [6],
            'target_is_transaction' => false,
            'result_depth' => 1,
            'transaction_active_after' => true,
        ], $stack->releasePlan('plugin-import'));
        $t->same([
            'savepoint' => 'plugin-import',
            'found_index' => 1,
            'released_frame_names' => ['plugin-import'],
            'merged_page_numbers' => [6],
            'target_is_transaction' => false,
            'result_depth' => 1,
            'transaction_active_after' => true,
        ], $stack->releaseWithPlan('plugin-import'));
        $t->same(1, $stack->depth());
        $t->same([2, 6], $stack->pendingPageNumbers());
        $t->same([
            [
                'name' => 'outer',
                'transaction' => true,
                'page_numbers' => [2, 6],
            ],
        ], $stack->toArray());

        $t->same([
            'savepoint' => 'outer',
            'found_index' => 0,
            'released_frame_names' => ['outer'],
            'merged_page_numbers' => [2, 6],
            'target_is_transaction' => true,
            'result_depth' => 0,
            'transaction_active_after' => false,
        ], $stack->releasePlan('outer'));
        $t->same([
            'savepoint' => 'outer',
            'found_index' => 0,
            'released_frame_names' => ['outer'],
            'merged_page_numbers' => [2, 6],
            'target_is_transaction' => true,
            'result_depth' => 0,
            'transaction_active_after' => false,
        ], $stack->releaseWithPlan('outer'));
        $t->same(false, $stack->transactionActive());
        $t->same([], $stack->pendingPageNumbers());

        $stack->savepoint('implicit');
        $stack->recordPageWrite(3);
        $t->same([
            [
                'name' => 'implicit',
                'transaction' => true,
                'page_numbers' => [3],
            ],
        ], $stack->toArray());
        $stack->commit();
        $t->same(false, $stack->transactionActive());

        $t->throws(InvalidArgumentException::class, static fn () => $stack->savepoint(''));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->recordPageWrite(0));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackTo('missing'));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackToPageNumbers('missing'));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackToPlan('missing'));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackToWithPlan('missing'));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->releasePlan('missing'));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->releaseWithPlan('missing'));
        $t->throws(LogicException::class, static fn () => $stack->commitPlan());
        $t->throws(LogicException::class, static fn () => $stack->commitWithPlan());
        $t->throws(LogicException::class, static fn () => $stack->commit());
    },
    'plans sqlite savepoint rollback apply and commit transitions' => static function (TestRunner $t): void {
        $stack = new SQLiteSavepointStack();
