        $t->same([], $implicit->pendingWalFrameIndexes());
        $implicit->recordWalFrameWrite(1, 10);
        $t->same([1], $implicit->pendingWalFrameIndexes());
        $t->same([
            'rolled_back_frame_names' => ['transaction'],
