        ];
        $dirtyDatabase = str_pad('dirty-wp-options-root', $pageSize, "\0")
            . str_pad('dirty-option-name-index', $pageSize, "\0")
            . str_pad('dirty-plugin-settings', $pageSize, "\0")
            . str_pad('dirty-single-option-row', $pageSize, "\0")
            . str_pad('dirty-load_policy-index-row', $pageSize, "\0");

        $stack = new SQLiteSavepointStack();
        $stack->beginTransaction('wp-import');
        $stack->recordPageImageWrite(1, $clean[1]);
        $stack->recordPageImageWrite(2, $clean[2]);
        $stack->savepoint('plugin-settings');
        $stack->recordPageImageWrite(2, str_pad('index-before-plugin-settings', $pageSize, "\0"));
        $stack->recordPageImageWrite(3, $clean[3]);
        $stack->savepoint('single-option-row');
        $stack->recordPageImageWrite(3, str_pad('settings-before-single-row', $pageSize, "\0"));
        $stack->recordPageImageWrite(4, $clean[4]);
        $stack->recordPageWrite(6);

        $t->same([
            1 => ['image' => $clean[1], 'frame' => 'wp-import'],
            2 => ['image' => $clean[2], 'frame' => 'wp-import'],
            3 => ['image' => $clean[3], 'frame' => 'plugin-settings'],
            4 => ['image' => $clean[4], 'frame' => 'single-option-row'],
        ], $stack->rollbackPageImages());
        $t->same([
            'page_size' => $pageSize,
            'restored_page_numbers' => [1, 2, 3, 4],
            'restore_pages' => [
                ['page_number' => 1, 'database_offset' => 0, 'bytes' => 512, 'source_frame' => 'wp-import'],
                ['page_number' => 2, 'database_offset' => 512, 'bytes' => 512, 'source_frame' => 'wp-import'],
                ['page_number' => 3, 'database_offset' => 1024, 'bytes' => 512, 'source_frame' => 'plugin-settings'],
                ['page_number' => 4, 'database_offset' => 1536, 'bytes' => 512, 'source_frame' => 'single-option-row'],
            ],
            'missing_page_numbers' => [6],
            'released_savepoint_count' => 2,
            'transaction_active_after' => false,
        ], $stack->rollbackImagePlan($pageSize));

        $rolledBack = $stack->rollbackDatabaseImage($dirtyDatabase, $pageSize);
        $t->same($clean[1], substr($rolledBack, 0, $pageSize));
        $t->same($clean[2], substr($rolledBack, $pageSize, $pageSize));
        $t->same($clean[3], substr($rolledBack, $pageSize * 2, $pageSize));
        $t->same($clean[4], substr($rolledBack, $pageSize * 3, $pageSize));
        $t->same(str_pad('dirty-load_policy-index-row', $pageSize, "\0"), substr($rolledBack, $pageSize * 4, $pageSize));
        $t->same(strlen($dirtyDatabase), strlen($rolledBack));
        $t->same(true, $stack->transactionActive());

        $stack->rollbackToWithPlan('plugin-settings');
        $stack->recordPageImageWrite(3, $clean[3]);
        $stack->savepoint('second-option-row');
        $stack->recordPageImageWrite(5, $clean[5]);
        $t->same([
            1 => ['image' => $clean[1], 'frame' => 'wp-import'],
            2 => ['image' => $clean[2], 'frame' => 'wp-import'],
            3 => ['image' => $clean[3], 'frame' => 'plugin-settings'],
            5 => ['image' => $clean[5], 'frame' => 'second-option-row'],
        ], $stack->rollbackPageImages());
        $secondRollback = $stack->rollbackDatabaseImage($dirtyDatabase, $pageSize);
        $t->same($clean[1], substr($secondRollback, 0, $pageSize));
        $t->same($clean[2], substr($secondRollback, $pageSize, $pageSize));
        $t->same($clean[3], substr($secondRollback, $pageSize * 2, $pageSize));
        $t->same(str_pad('dirty-single-option-row', $pageSize, "\0"), substr($secondRollback, $pageSize * 3, $pageSize));
        $t->same($clean[5], substr($secondRollback, $pageSize * 4, $pageSize));

        $releasePlan = $stack->releaseWithPlan('plugin-settings');
        $t->same(['plugin-settings', 'second-option-row'], $releasePlan['released_frame_names']);
        $t->same([
            1 => ['image' => $clean[1], 'frame' => 'wp-import'],
            2 => ['image' => $clean[2], 'frame' => 'wp-import'],
            3 => ['image' => $clean[3], 'frame' => 'wp-import'],
            5 => ['image' => $clean[5], 'frame' => 'wp-import'],
        ], $stack->rollbackPageImages());
        $t->same(1, $stack->depth());
        $t->same(0, $stack->rollbackImagePlan($pageSize)['released_savepoint_count']);

        $beyondEnd = new SQLiteSavepointStack();
        $beyondEnd->beginTransaction('wp-import');
        $beyondEnd->recordPageImageWrite(7, str_pad('future-page-before-import', $pageSize, "\0"));
        $t->same($dirtyDatabase, $beyondEnd->rollbackDatabaseImage($dirtyDatabase, $pageSize));
        $t->same([7], $beyondEnd->rollbackImagePlan($pageSize)['restored_page_numbers']);

        $badSize = new SQLiteSavepointStack();
        $badSize->beginTransaction('wp-import');
        $badSize->recordPageImageWrite(1, 'short-image');
        $t->throws(InvalidArgumentException::class, static fn () => $badSize->rollbackImagePlan($pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => $badSize->rollbackDatabaseImage($dirtyDatabase, $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackImagePlan(0));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackDatabaseImage($dirtyDatabase, 0));
        $t->throws(InvalidArgumentException::class, static fn () => $stack->rollbackDatabaseImage(substr($dirtyDatabase, 1), $pageSize));

        $inactive = new SQLiteSavepointStack();
        $t->throws(LogicException::class, static fn () => $inactive->rollbackPageImages());
        $t->throws(LogicException::class, static fn () => $inactive->rollbackImagePlan($pageSize));
        $t->throws(LogicException::class, static fn () => $inactive->rollbackDatabaseImage($dirtyDatabase, $pageSize));
    },
    'rejects malformed sqlite rollback journals' => static function (TestRunner $t): void {
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournalHeader::parse(str_repeat("\0", 27)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournalHeader::parse(str_repeat("\0", 28)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournalHeader::parse(SQLiteRollbackJournalHeader::MAGIC . pack('N*', 0, 1, 1, 500, 512)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournalHeader::parse(SQLiteRollbackJournalHeader::MAGIC . pack('N*', 0, 1, 1, 512, 500)));

        $header = SQLiteRollbackJournalHeader::MAGIC . pack('N*', 1, 0x01020304, 1, 512, 512);
        $journalBytes = str_pad($header, 512, "\0") . pack('N', 1) . str_repeat('P', 512) . pack('N', SQLiteRollbackJournal::pageChecksum(str_repeat('P', 512), 0x01020304));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournal::parse(str_pad($header, 512, "\0") . str_repeat("\0", 12)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournal::parse(str_pad(SQLiteRollbackJournalHeader::MAGIC . pack('N*', 2, 0x01020304, 1, 512, 512), 512, "\0") . pack('N', 1) . str_repeat('P', 512) . pack('N', 0)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournal::parse(substr_replace($journalBytes, pack('N', 0), 512, 4)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournal::parse(substr_replace($journalBytes, pack('N', 0), 512 + 4 + 512, 4), true));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteRollbackJournal::parse($journalBytes, true)->rollbackDatabaseImage(str_repeat('D', 511)));
    },
    'dispatches core sqlite null numeric type and literal scalar functions' => static function (TestRunner $t): void {
        $t->same(7, SQLiteCoreScalarFunction::sqlFunctionArguments('ABS', [-7]));
        $t->same(12.5, SQLiteCoreScalarFunction::sqlFunctionArguments('abs', [' -12.5ms']));
        $t->same(0, SQLiteCoreScalarFunction::sqlFunctionArguments('abs', ['not numeric']));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('abs', [null]));

        $t->same(3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('round', [2.5]));
        $t->same(-3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('round', [-2.5]));
        $t->same(3.14, SQLiteCoreScalarFunction::sqlFunctionArguments('round', [3.14159, 2]));
        $t->same(3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('round', [3.14159, -2]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('round', [3.14159, null]));
        $t->same(-1, SQLiteCoreScalarFunction::sqlFunctionArguments('sign', [-2.5]));
        $t->same(0, SQLiteCoreScalarFunction::sqlFunctionArguments('sign', [' 0 ']));
        $t->same(1, SQLiteCoreScalarFunction::sqlFunctionArguments('sign', ['2.5e1']));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('sign', [' -3x']));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('sign', [new SQLiteBlobValue('12')]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('sign', [null]));
        $t->same(3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('ceil', [2.25]));
        $t->same(3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('ceiling', ['2.25']));
        $t->same(-3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('floor', [-2.25]));
        $t->same(-2.0, SQLiteCoreScalarFunction::sqlFunctionArguments('trunc', [-2.75]));
        $t->same(4.0, SQLiteCoreScalarFunction::sqlFunctionArguments('sqrt', [16]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('sqrt', [-1]));
        $t->same(8.0, SQLiteCoreScalarFunction::sqlFunctionArguments('pow', [2, 3]));
        $t->same(9.0, SQLiteCoreScalarFunction::sqlFunctionArguments('power', ['3', '2']));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('pow', [-2, 0.5]));
        $t->same(1.5, SQLiteCoreScalarFunction::sqlFunctionArguments('mod', [7.5, 2]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('mod', [7.5, 0]));
        $t->same(2.0, SQLiteCoreScalarFunction::sqlFunctionArguments('log10', [100]));
        $t->same(2.0, SQLiteCoreScalarFunction::sqlFunctionArguments('log', [100]));
        $t->same(3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('log', [2, 8]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('log', [1, 8]));
        $t->same(3.0, SQLiteCoreScalarFunction::sqlFunctionArguments('log2', [8]));
        $t->same(1.0, SQLiteCoreScalarFunction::sqlFunctionArguments('ln', [M_E]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('ln', [0]));
        $t->same(1.0, SQLiteCoreScalarFunction::sqlFunctionArguments('sin', [M_PI / 2]));
        $t->same(1.0, SQLiteCoreScalarFunction::sqlFunctionArguments('cos', [0]));
        $t->same(0.0, SQLiteCoreScalarFunction::sqlFunctionArguments('tan', [0]));
        $t->same(0.0, SQLiteCoreScalarFunction::sqlFunctionArguments('atan2', [0, 1]));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('acos', [2]));
        $t->same(M_PI, SQLiteCoreScalarFunction::sqlFunctionArguments('pi', []));
        $t->same(null, SQLiteCoreScalarFunction::sqlFunctionArguments('sqrt', ['bad']));

        $t->same('null', SQLiteCoreScalarFunction::sqlFunctionArguments('typeof', [null]));
        $t->same('integer', SQLiteCoreScalarFunction::sqlFunctionArguments('typeof', [1]));
        $t->same('real', SQLiteCoreScalarFunction::sqlFunctionArguments('typeof', [1.25]));
        $t->same('text', SQLiteCoreScalarFunction::sqlFunctionArguments('typeof', ['1']));
        $t->same('blob', SQLiteCoreScalarFunction::sqlFunctionArguments('typeof', [new SQLiteBlobValue("\x00A")]));

        $t->same('NULL', SQLiteCoreScalarFunction::sqlFunctionArguments('quote', [null]));
        $t->same("'app_settings'' load_policy'", SQLiteCoreScalarFunction::sqlFunctionArguments('quote', ["app_settings' load_policy"]));
        $t->same("X'0041'", SQLiteCoreScalarFunction::sqlFunctionArguments('quote', [new SQLiteBlobValue("\x00A")]));
        $t->same('42', SQLiteCoreScalarFunction::sqlFunctionArguments('quote', [42]));

        $blob = new SQLiteBlobValue('fallback');
        $t->same('published', SQLiteCoreScalarFunction::sqlFunctionArguments('coalesce', [null, null, 'published']));
        $t->same($blob, SQLiteCoreScalarFunction::sqlFunctionArguments('ifnull', [null, $blob]));
