        $t->same('localhost', $localhost['authority']);
        $t->same('/tmp/wp-content/cache.db', $localhost['path']);
        $t->same('rw', $localhost['mode']);
        $t->same('unix-dotfile', $localhost['vfs']);
        $t->same(true, $localhost['nolock']);
