    'loads bounded sqlite file headers after open admission' => static function (TestRunner $t) use ($makeFirstPage): void {
        $uriForPath = static fn (string $path): string => 'file:' . str_replace('%2F', '/', rawurlencode($path));
        $writeTemp = static function (string $prefix, string $bytes): string {
            $path = tempnam(sys_get_temp_dir(), $prefix);
            if ($path === false) {
                throw new RuntimeException('Unable to create temporary SQLite header fixture');
            }
            file_put_contents($path, $bytes);

            return $path;
        };

        $validPath = $writeTemp('wp-sqlite-header-', $makeFirstPage(512, 2) . str_repeat("\0", 512));
        $valid = SQLiteFileHeaderLoader::inspect($uriForPath($validPath) . '?mode=ro&immutable=1&vfs=unix-none');
        $t->same('header-ready', $valid['status']);
        $t->same(true, $valid['can_open']);
        $t->same(true, $valid['can_read_header']);
        $t->same($validPath, $valid['path']);
        $t->same(100, $valid['bytes_read']);
        $t->same(1024, $valid['file_size']);
        $t->same(512, $valid['minimum_first_page_bytes']);
        $t->same(1024, $valid['minimum_declared_bytes']);
        $t->same(true, $valid['complete_first_page']);
        $t->same(true, $valid['complete_declared_pages']);
        $t->true($valid['header'] instanceof SQLiteHeader);
        $t->same(512, $valid['header']->pageSize);
        $t->same(2, $valid['header']->databaseSizePages);
        $t->same('ro', $valid['open']['mode']);
        $t->same(true, $valid['open']['read_only']);
        $t->same('unix-none', $valid['open']['vfs']);
        $t->same(null, $valid['reason']);
        $t->same(['file-uri-parser', 'vfs-admission', 'immutable-readonly-open', 'bounded-file-header-read', 'sqlite-header-parse', 'sqlite-file-size-check'], $valid['dependencies']);

        $plainPath = $writeTemp('wp-sqlite-plain-', $makeFirstPage(1024, 1));
        $plain = SQLiteFileHeaderLoader::inspect($plainPath);
        $t->same('header-ready', $plain['status']);
        $t->same('rwc', $plain['open']['mode']);
        $t->same(1024, $plain['header']->pageSize);
        $t->same(1024, $plain['minimum_declared_bytes']);
        $t->same(['file-uri-parser', 'bounded-file-header-read', 'sqlite-header-parse', 'sqlite-file-size-check'], $plain['dependencies']);

        $shortPath = $writeTemp('wp-sqlite-short-', substr($makeFirstPage(512, 1), 0, 80));
        $short = SQLiteFileHeaderLoader::inspect($uriForPath($shortPath) . '?mode=ro');
        $t->same('short-header', $short['status']);
        $t->same(true, $short['can_open']);
        $t->same(false, $short['can_read_header']);
        $t->same(80, $short['bytes_read']);
        $t->same(80, $short['file_size']);
        $t->same(null, $short['header']);
        $t->same('SQLite database header requires at least 100 bytes', $short['reason']);

        $invalidPath = $writeTemp('wp-sqlite-invalid-', str_repeat('x', 128));
        $invalid = SQLiteFileHeaderLoader::inspect($invalidPath);
        $t->same('invalid-header', $invalid['status']);
        $t->same(false, $invalid['can_read_header']);
        $t->same(100, $invalid['bytes_read']);
        $t->same('Missing SQLite format 3 magic header', $invalid['reason']);
        $t->same(['file-uri-parser', 'bounded-file-header-read', 'sqlite-header-parse'], $invalid['dependencies']);

        $incompletePath = $writeTemp('wp-sqlite-incomplete-', substr($makeFirstPage(512, 1), 0, 128));
        $incomplete = SQLiteFileHeaderLoader::inspect($incompletePath);
        $t->same('incomplete-first-page', $incomplete['status']);
        $t->same(false, $incomplete['can_read_header']);
        $t->same(128, $incomplete['file_size']);
        $t->same(512, $incomplete['minimum_first_page_bytes']);
        $t->same(false, $incomplete['complete_first_page']);
        $t->same(false, $incomplete['complete_declared_pages']);
        $t->same('database file is smaller than its first page', $incomplete['reason']);

        $missing = SQLiteFileHeaderLoader::inspect($uriForPath(sys_get_temp_dir() . '/wp-sqlite-missing-' . uniqid('', true) . '.db') . '?mode=ro');
        $t->same('missing', $missing['status']);
        $t->same(false, $missing['can_open']);
        $t->same(false, $missing['can_read_header']);
        $t->same(null, $missing['file_size']);
        $t->same('database file does not exist', $missing['reason']);

        $busy = SQLiteFileHeaderLoader::inspect($uriForPath($validPath) . '?mode=rw', false, SQLiteBusyHandler::withDelays(4, [2, 2]));
        $t->same('busy-timeout', $busy['status']);
        $t->same(false, $busy['can_open']);
        $t->same(false, $busy['can_read_header']);
        $t->same(0, $busy['bytes_read']);
        $t->same(1024, $busy['file_size']);
        $t->same(4, $busy['open']['busy']['total_sleep_ms']);
        $t->same(['file-uri-parser', 'busy-handler', 'bounded-file-header-read'], $busy['dependencies']);

        $memory = SQLiteFileHeaderLoader::inspect('file::memory:?mode=memory&cache=private');
        $t->same('memory-open', $memory['status']);
        $t->same(true, $memory['can_open']);
        $t->same(false, $memory['can_read_header']);
        $t->same(':memory:', $memory['path']);
        $t->same(null, $memory['file_size']);
        $t->same('in-memory databases do not have a file header', $memory['reason']);

        foreach ([$validPath, $plainPath, $shortPath, $invalidPath, $incompletePath] as $path) {
            @unlink($path);
        }
    },
    'loads sqlite pages through a bounded page cache after open admission' => static function (TestRunner $t) use ($makeFirstPage): void {
        $uriForPath = static fn (string $path): string => 'file:' . str_replace('%2F', '/', rawurlencode($path));
        $writeTemp = static function (string $prefix, string $bytes): string {
            $path = tempnam(sys_get_temp_dir(), $prefix);
            if ($path === false) {
                throw new RuntimeException('Unable to create temporary SQLite page-cache fixture');
            }
            file_put_contents($path, $bytes);

            return $path;
        };

        $pageOne = $makeFirstPage(512, 3);
        $pageTwo = str_repeat('W', 512);
        $pageThree = str_repeat('P', 512);
        $validPath = $writeTemp('wp-sqlite-page-cache-', $pageOne . $pageTwo . $pageThree);

        $cache = SQLitePageCache::open($uriForPath($validPath) . '?mode=ro&immutable=1&vfs=unix-none');
        $summary = $cache->summary();
        $t->same('ready', $summary['status']);
        $t->same($validPath, $summary['path']);
        $t->same(512, $summary['page_size']);
        $t->same(1536, $summary['file_size']);
        $t->same(3, $summary['available_pages']);
        $t->same(3, $summary['declared_pages']);
        $t->same(true, $summary['complete_declared_pages']);
        $t->same(true, $summary['read_only']);
        $t->same('unix-none', $summary['vfs']);
        $t->same(['file-uri-parser', 'vfs-admission', 'immutable-readonly-open', 'bounded-file-header-read', 'sqlite-header-parse', 'sqlite-file-size-check', 'bounded-page-cache', 'page-size-aligned-read'], $summary['dependencies']);
        $t->same($validPath, $cache->path);
        $t->same(512, $cache->header->pageSize);
        $t->same(1536, $cache->fileSize);
        $t->same(3, $cache->availablePages);
        $t->same(3, $cache->declaredPages);
        $t->same(true, $cache->readOnly);
        $t->same('unix-none', $cache->vfs);
        $t->same(false, $cache->hasCachedPage(2));
        $t->same(0, $cache->cachedPageCount());
        $t->same($pageTwo, $cache->page(2));
        $t->same(true, $cache->hasCachedPage(2));
        $t->same(1, $cache->cachedPageCount());
        $t->same($pageTwo, $cache->page(2));
        $t->same(1, $cache->cachedPageCount());
        $selected = $cache->pages([1, 3]);
        $t->same([1, 3], array_keys($selected));
        $t->same($pageOne, $selected[1]);
        $t->same($pageThree, $selected[3]);
        $t->same(3, $cache->cachedPageCount());
        $t->same('ro', $cache->open['mode']);
        $t->same(true, $cache->open['immutable']);

        $oversizedPath = $writeTemp('wp-sqlite-page-cache-extra-', $makeFirstPage(512, 2) . str_repeat('A', 512) . str_repeat('B', 512));
        $oversized = SQLitePageCache::open($oversizedPath);
        $t->same(3, $oversized->availablePages);
        $t->same(2, $oversized->declaredPages);
        $t->same('ready', $oversized->summary()['status']);
        $t->same(str_repeat('A', 512), $oversized->page(2));
        $t->throws(OutOfBoundsException::class, static fn () => $oversized->page(3));

        $incompletePath = $writeTemp('wp-sqlite-page-cache-incomplete-', $makeFirstPage(512, 3) . str_repeat('I', 512));
        $incomplete = SQLitePageCache::open($incompletePath);
        $incompleteSummary = $incomplete->summary();
        $t->same('incomplete-declared-pages', $incompleteSummary['status']);
        $t->same(2, $incompleteSummary['available_pages']);
        $t->same(3, $incompleteSummary['declared_pages']);
        $t->same(false, $incompleteSummary['complete_declared_pages']);
        $t->same(str_repeat('I', 512), $incomplete->page(2));
        $t->throws(OutOfBoundsException::class, static fn () => $incomplete->page(3));

        $shortPath = $writeTemp('wp-sqlite-page-cache-short-', substr($makeFirstPage(512, 1), 0, 128));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePageCache::open($shortPath));
        $invalidPath = $writeTemp('wp-sqlite-page-cache-invalid-', str_repeat('x', 128));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePageCache::open($invalidPath));
        $t->throws(InvalidArgumentException::class, static fn () => $cache->page(0));
        $t->throws(OutOfBoundsException::class, static fn () => $cache->page(4));
        $t->throws(InvalidArgumentException::class, static fn () => $cache->pages(['2']));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePageCache::open($uriForPath($validPath) . '?mode=rw', false, SQLiteBusyHandler::timeout(0)));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePageCache::open('file::memory:?mode=memory'));

        foreach ([$validPath, $oversizedPath, $incompletePath, $shortPath, $invalidPath] as $path) {
            @unlink($path);
        }
    },
    'coordinates sqlite file locks for open admission without a vfs dependency' => static function (TestRunner $t): void {
        $coordinator = new SQLiteLockCoordinator([
            'reader-a' => 'shared',
            'writer-a' => 'reserved',
        ]);

        $t->same([
            ['connection' => 'reader-a', 'level' => 'shared'],
            ['connection' => 'writer-a', 'level' => 'reserved'],
        ], $coordinator->holders());

        $reader = $coordinator->plan('reader-b', 'shared');
        $t->same('ready', $reader['status']);
        $t->same(true, $reader['can_acquire']);
        $t->same('reader-b', $reader['connection']);
        $t->same('shared', $reader['requested']);
        $t->same('none', $reader['current']);
        $t->same([], $reader['blocking']);
        $t->same(['sqlite-lock-coordinator'], $reader['dependencies']);
        $t->same(null, $reader['reason']);
        $t->same(null, $reader['busy']);

        $reserved = $coordinator->plan('writer-b', 'reserved', SQLiteBusyHandler::withDelays(6, [2, 2, 2]));
        $t->same('busy-timeout', $reserved['status']);
        $t->same(false, $reserved['can_acquire']);
        $t->same('writer-b', $reserved['connection']);
        $t->same('reserved', $reserved['requested']);
        $t->same('writer is blocked by an existing writer lock', $reserved['reason']);
        $t->same([['connection' => 'writer-a', 'level' => 'reserved', 'reason' => 'writer lock already held']], $reserved['blocking']);
        $t->same(['sqlite-lock-coordinator', 'busy-handler'], $reserved['dependencies']);
        $t->same(6, $reserved['busy']['total_sleep_ms']);
        $t->same(3, $reserved['busy']['retry_count']);

        $exclusive = $coordinator->plan('writer-a', 'exclusive', SQLiteBusyHandler::withDelays(4, [1, 3]));
        $t->same('busy-timeout', $exclusive['status']);
        $t->same(false, $exclusive['can_acquire']);
        $t->same('reserved', $exclusive['current']);
        $t->same('exclusive writer is blocked until readers and writers drain', $exclusive['reason']);
        $t->same([['connection' => 'reader-a', 'level' => 'shared', 'reason' => 'shared reader must drain before exclusive lock']], $exclusive['blocking']);
        $t->same(4, $exclusive['busy']['total_sleep_ms']);

        $coordinator->set('writer-a', 'pending');
        $blockedReader = $coordinator->plan('reader-b', 'shared', SQLiteBusyHandler::timeout(0));
        $t->same('busy-cancelled', $blockedReader['status']);
        $t->same(false, $blockedReader['can_acquire']);
        $t->same('new reader is blocked by pending or exclusive writer lock', $blockedReader['reason']);
        $t->same([['connection' => 'writer-a', 'level' => 'pending', 'reason' => 'pending lock blocks new shared readers']], $blockedReader['blocking']);
        $t->same(0, $blockedReader['busy']['total_sleep_ms']);

        $coordinator->release('reader-a');
        $exclusiveReady = $coordinator->plan('writer-a', 'exclusive');
        $t->same('ready', $exclusiveReady['status']);
        $t->same(true, $exclusiveReady['can_acquire']);
        $t->same('pending', $exclusiveReady['current']);
        $t->same([], $exclusiveReady['blocking']);

        $openRead = $coordinator->openPlan('file:/srv/wp/site.db?mode=ro&immutable=1&vfs=unix-none', 'reader-b', true, false);
        $t->same('busy-cancelled', $openRead['status']);
        $t->same(false, $openRead['can_open']);
        $t->same(true, $openRead['read_only']);
        $t->same('shared', $openRead['lock']['requested']);
        $t->same(['file-uri-parser', 'vfs-admission', 'immutable-readonly-open', 'sqlite-lock-coordinator', 'busy-handler'], $openRead['dependencies']);

        $coordinator->set('writer-a', 'none');
        $writeOpen = $coordinator->openPlan('file:/srv/wp/site.db?mode=rw&cache=shared', 'writer-b', true, false, true);
        $t->same('ready', $writeOpen['status']);
        $t->same(true, $writeOpen['can_open']);
        $t->same(false, $writeOpen['read_only']);
        $t->same('reserved', $writeOpen['lock']['requested']);
        $t->same('shared', $writeOpen['open']['cache']);
        $t->same(['file-uri-parser', 'shared-cache-coordination', 'sqlite-lock-coordinator'], $writeOpen['dependencies']);

        $missing = $coordinator->openPlan('file:/srv/wp/missing.db?mode=ro', 'reader-c', false, false);
        $t->same('missing', $missing['status']);
        $t->same(false, $missing['can_open']);
        $t->same('open admission failed', $missing['lock']['reason']);
        $t->same('database file does not exist', $missing['reason']);

        $coordinator->set('reader-z', 'shared');
        $coordinator->release('reader-z');
        $t->same([], $coordinator->holders());

        $t->throws(InvalidArgumentException::class, static fn () => new SQLiteLockCoordinator([' ' => 'shared']));
        $t->throws(InvalidArgumentException::class, static fn () => $coordinator->plan('reader', 'hot'));
        $t->throws(InvalidArgumentException::class, static fn () => $coordinator->set('reader', ''));
