        $t->same(['full'], $applied['operations'][0]['flag_names']);
        $t->same(false, $applied['operations'][0]['data_only']);
        $t->same(false, $applied['operations'][0]['directory']);
        $t->same(true, $applied['operations'][0]['durable']);
