    'recovers sqlite statement journals gated by attached master journals current next' => static function (TestRunner $t): void {
        $root = sys_get_temp_dir() . '/port-libsqlite-master-stmt-recovery-' . bin2hex(random_bytes(4));
        $mainPath = '/srv/www/wp-content/database/.ht.sqlite';
        $metaPath = '/srv/www/wp-content/database/site-meta.sqlite';
        $orphanPath = '/srv/www/wp-content/database/orphan.sqlite';
        $masterPath = '/srv/www/wp-content/database/.ht.sqlite-mj80';
        $pageSize = 512;
        $page = static fn (string $label): string => str_pad($label, $pageSize, "\0");

        $mainCurrent = $page('main schema current after failed statement')
            . $page('app_settings dirty plugin row')
            . $page('app_settings dirty load_policy index');
        $metaCurrent = $page('sitemeta schema current after failed statement')
            . $page('app_tenant_settings dirty plugin row');
        $orphanCurrent = $page('orphan schema current after failed statement')
            . $page('orphan dirty row');

        $mainBeforeOptions = $page('app_settings before failed statement');
        $mainBeforeIndex = $page('app_settings index before failed statement');
        $metaBefore = $page('app_tenant_settings before failed statement');
        $orphanBefore = $page('orphan before failed statement');
        $masterBytes = $mainPath . "-journal\n" . $metaPath . "-journal\n";
        $databases = [
            [
                'database_path' => $mainPath,
                'database_bytes' => $mainCurrent,
                'statement_journal_path' => $mainPath . '-stmt-journal',
                'statement_pages' => [3 => $mainBeforeIndex, 2 => $mainBeforeOptions],
                'outer_journal_bytes' => 'main outer transaction rollback journal remains live',
            ],
            [
                'database_path' => $metaPath,
                'database_bytes' => $metaCurrent,
                'statement_pages' => [2 => $metaBefore],
                'outer_journal_bytes' => 'sitemeta outer transaction rollback journal remains live',
            ],
            [
                'database_path' => $orphanPath,
                'database_bytes' => $orphanCurrent,
                'statement_pages' => [2 => $orphanBefore],
                'outer_journal_bytes' => 'orphan outer journal missing from master',
            ],
        ];

        $plan = SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, $databases, $pageSize);
        $t->same('master_journal_statement_recovered_current_next', $plan['status']);
        $t->same('master_journal_members_gate_statement_journal_recovery', $plan['reason']);
        $t->same($masterPath, $plan['master_journal_path']);
        $t->same(true, $plan['master_journal_exists']);
        $t->same([$mainPath . '-journal', $metaPath . '-journal'], $plan['master_journal_members']);
        $t->same(3, $plan['database_count']);
        $t->same(2, $plan['recovered_database_count']);
        $t->same(1, $plan['skipped_database_count']);
        $t->same('app_settings dirty plugin row', $plan['current_page_prefixes'][$mainPath][2]);
        $t->same('app_settings before failed statement', $plan['next_page_prefixes'][$mainPath][2]);
        $t->same('app_settings dirty load_policy index', $plan['current_page_prefixes'][$mainPath][3]);
        $t->same('app_settings index before failed statement', $plan['next_page_prefixes'][$mainPath][3]);
        $t->same('app_tenant_settings dirty plugin row', $plan['current_page_prefixes'][$metaPath][2]);
        $t->same('app_tenant_settings before failed statement', $plan['next_page_prefixes'][$metaPath][2]);
        $t->same('orphan dirty row', $plan['current_page_prefixes'][$orphanPath][2]);
        $t->same('orphan dirty row', $plan['next_page_prefixes'][$orphanPath][2]);
        $t->same('delete_statement_journal_after_rollback', $plan['statement_journal_actions'][$mainPath . '-stmt-journal']);
        $t->same('delete_statement_journal_after_rollback', $plan['statement_journal_actions'][$metaPath . '-stmt-journal']);
        $t->same('preserve_statement_journal', $plan['statement_journal_actions'][$orphanPath . '-stmt-journal']);
        $t->same('preserve_outer_rollback_journal', $plan['outer_journal_actions'][$mainPath . '-journal']);
        $t->same('preserve_outer_rollback_journal', $plan['outer_journal_actions'][$metaPath . '-journal']);
        $t->same('preserve_outer_rollback_journal', $plan['outer_journal_actions'][$orphanPath . '-journal']);
        $t->same('preserve_master_journal_for_outer_transaction', $plan['master_journal_action']);
        $t->same(7, count($plan['operations']));
        $t->same(['write', 'truncate', 'delete', 'write', 'truncate', 'delete', 'sync_directory'], array_column($plan['operations'], 'op'));
        $t->same('restore_statement_journal_page_preimages', $plan['operations'][0]['reason']);
        $t->same($mainPath . '#statement-rollback', $plan['operations'][0]['payload_key']);
        $t->same($pageSize * 3, $plan['operations'][0]['bytes']);
        $t->same('trim_statement_recovered_database_image', $plan['operations'][1]['reason']);
        $t->same('delete_statement_journal_after_recovery', $plan['operations'][2]['reason']);
        $t->same($metaPath . '#statement-rollback', $plan['operations'][3]['payload_key']);
        $t->same('persist_statement_journal_recovery_sidecars', $plan['operations'][6]['reason']);
        $t->same($pageSize * 3, strlen($plan['payloads'][$mainPath . '#statement-rollback']));
        $t->same($mainBeforeOptions, substr($plan['payloads'][$mainPath . '#statement-rollback'], $pageSize, $pageSize));
        $t->same($mainBeforeIndex, substr($plan['payloads'][$mainPath . '#statement-rollback'], $pageSize * 2, $pageSize));
        $t->same($metaBefore, substr($plan['payloads'][$metaPath . '#statement-rollback'], $pageSize, $pageSize));
        $t->same(true, $plan['databases'][$mainPath]['recovered']);
        $t->same('master_journal_member_statement_rollback', $plan['databases'][$mainPath]['reason']);
        $t->same([2, 3], $plan['databases'][$mainPath]['page_numbers']);
        $t->same(false, $plan['databases'][$orphanPath]['recovered']);
        $t->same('missing_master_journal_member', $plan['databases'][$orphanPath]['reason']);
        $t->same([
            'sqlite-pager-master-journal-statement-recovery-current-next80',
            'sqlite-statement-journal-page-recovery',
            'attached-database-statement-rollback',
            'vfs-file-write-coordination',
        ], $plan['dependencies']);

        mkdir(dirname($root . $masterPath), 0777, true);
        file_put_contents($root . $masterPath, $masterBytes);
        file_put_contents($root . $mainPath . '-journal', 'main outer rollback journal');
        file_put_contents($root . $mainPath . '-stmt-journal', 'main statement journal');
        file_put_contents($root . $metaPath . '-journal', 'meta outer rollback journal');
        file_put_contents($root . $metaPath . '-stmt-journal', 'meta statement journal');
        file_put_contents($root . $orphanPath . '-journal', 'orphan outer rollback journal');
        file_put_contents($root . $orphanPath . '-stmt-journal', 'orphan statement journal');

        $applied = (new SQLiteVfsFileWriter($root))->applyMasterJournalStatementPageRecovery($masterPath, $masterBytes, $databases, $pageSize);
        $t->same('applied', $applied['status']);
        $t->same(true, $applied['atomic']);
        $t->same(7, $applied['applied']);
        $t->same(($pageSize * 3) + ($pageSize * 2), $applied['bytes_written']);
        $t->same(($pageSize * 3) + ($pageSize * 2), $applied['bytes_truncated']);
        $t->same(2, $applied['files_deleted']);
        $t->same(0, $applied['durable_syncs']);
        $t->same(1, $applied['directory_syncs']);
        $t->same(false, is_file($root . $mainPath . '-stmt-journal'));
        $t->same(false, is_file($root . $metaPath . '-stmt-journal'));
        $t->same(true, is_file($root . $mainPath . '-journal'));
        $t->same(true, is_file($root . $metaPath . '-journal'));
        $t->same(true, is_file($root . $masterPath));
        $t->same(true, is_file($root . $orphanPath . '-stmt-journal'));
        $mainBytes = file_get_contents($root . $mainPath);
        $metaBytes = file_get_contents($root . $metaPath);
        $t->same($pageSize * 3, strlen($mainBytes));
        $t->same('main schema current after failed statement', rtrim(substr($mainBytes, 0, 48), "\0"));
        $t->same($mainBeforeOptions, substr($mainBytes, $pageSize, $pageSize));
        $t->same($mainBeforeIndex, substr($mainBytes, $pageSize * 2, $pageSize));
        $t->same($pageSize * 2, strlen($metaBytes));
        $t->same('sitemeta schema current after failed statement', rtrim(substr($metaBytes, 0, 48), "\0"));
        $t->same($metaBefore, substr($metaBytes, $pageSize, $pageSize));
        $t->same(2, $applied['recovery']['recovered_database_count']);
        $t->same('preserve_master_journal_for_outer_transaction', $applied['recovery']['master_journal_action']);

        $reserved = SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [[
            'database_path' => $mainPath,
            'database_bytes' => $mainCurrent,
            'statement_pages' => [2 => $mainBeforeOptions],
            'reserved_lock' => true,
        ]], $pageSize);
        $t->same('master_journal_statement_recovery_skipped_current_next', $reserved['status']);
        $t->same(0, $reserved['recovered_database_count']);
        $t->same(1, $reserved['skipped_database_count']);
        $t->same('database_has_reserved_lock', $reserved['databases'][$mainPath]['reason']);
        $t->same('preserve_statement_journal', $reserved['statement_journal_actions'][$mainPath . '-stmt-journal']);
        $t->same([], $reserved['operations']);

        $missingMaster = (new SQLiteVfsFileWriter($root))->applyMasterJournalStatementPageRecovery($masterPath, null, [[
            'database_path' => $mainPath,
            'database_bytes' => $mainCurrent,
            'statement_pages' => [2 => $mainBeforeOptions],
        ]], $pageSize);
        $t->same('skipped', $missingMaster['status']);
        $t->same(false, $missingMaster['recovery']['master_journal_exists']);
        $t->same('missing_master_journal', $missingMaster['recovery']['databases'][$mainPath]['reason']);
        $t->same(0, $missingMaster['applied']);

        $readOnly = new SQLiteVfsFileWriter($root, true);
        $t->throws(LogicException::class, static fn () => $readOnly->applyMasterJournalStatementPageRecovery($masterPath, $masterBytes, $databases, $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext('', $masterBytes, $databases, $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, $databases, 500));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [['database_path' => '', 'database_bytes' => $mainCurrent, 'statement_pages' => [2 => $mainBeforeOptions]]], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [['database_path' => $mainPath, 'database_bytes' => substr($mainCurrent, 1), 'statement_pages' => [2 => $mainBeforeOptions]]], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [['database_path' => $mainPath, 'database_bytes' => $mainCurrent, 'statement_pages' => []]], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [['database_path' => $mainPath, 'database_bytes' => $mainCurrent, 'statement_pages' => [0 => $mainBeforeOptions]]], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [['database_path' => $mainPath, 'database_bytes' => $mainCurrent, 'statement_pages' => [2 => substr($mainBeforeOptions, 1)]]], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => SQLitePagerStatementRecoveryPlan::masterJournalStatementRecoveryCurrentNext($masterPath, $masterBytes, [$databases[0], $databases[0]], $pageSize));
        $t->throws(InvalidArgumentException::class, static fn () => (new SQLiteVfsFileWriter($root))->applyMasterJournalStatementPageRecovery('../escape-mj', $masterBytes, $databases, $pageSize));
    },
    'applies sqlite vfs savepoint rollback images and wal truncation to local handles' => static function (TestRunner $t): void {
        $root = sys_get_temp_dir() . '/port-libsqlite-vfs-savepoint-' . bin2hex(random_bytes(4));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';
        $localDatabase = $root . '/srv/www/wp-content/database/.ht.sqlite';
        $localWal = $localDatabase . '-wal';
        $pageSize = 512;

        $pageOneClean = str_pad('clean schema before import', $pageSize, "\0");
        $pageTwoClean = str_pad('clean app_settings before import', $pageSize, "\0");
        $pageThreeBeforePlugin = str_pad('plugin settings before batch', $pageSize, "\0");
        $pageFourBeforeRow = str_pad('single option before row', $pageSize, "\0");
        $dirtyDatabase = str_pad('dirty schema after import', $pageSize, "\0")
            . str_pad('dirty app_settings after import', $pageSize, "\0")
            . str_pad('plugin settings dirty row', $pageSize, "\0")
            . str_pad('single option dirty row', $pageSize, "\0");

        $salt1 = 0x12345678;
        $salt2 = 0x87654321;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 12, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walBytes = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $appendFrame = static function (string $bytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $bytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };
        $walFrameOne = str_pad('wal schema before plugin', $pageSize, "\0");
        $walFrameTwo = str_pad('wal options before plugin', $pageSize, "\0");
        $walFrameThree = str_pad('wal plugin draft should disappear', $pageSize, "\0");
        $walFrameFour = str_pad('wal row draft should disappear', $pageSize, "\0");
        $walBytes = $appendFrame($walBytes, $checksumSeed, 1, 0, $walFrameOne);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 2, $walFrameTwo);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 3, 0, $walFrameThree);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 4, 4, $walFrameFour);
        $wal = SQLiteWal::parse($walBytes, null, true);

        $savepoints = new SQLiteSavepointStack();
        $savepoints->beginTransaction('wp-import');
        $savepoints->recordPageImageWrite(1, $pageOneClean);
        $savepoints->recordPageImageWrite(2, $pageTwoClean);
        $savepoints->recordWalFrameWrite(1, 1);
        $savepoints->recordWalFrameWrite(2, 2, true);
        $savepoints->savepoint('plugin-settings');
        $savepoints->recordPageImageWrite(3, $pageThreeBeforePlugin);
        $savepoints->recordWalFrameWrite(3, 3);
        $savepoints->savepoint('single-option-row');
        $savepoints->recordPageImageWrite(4, $pageFourBeforeRow);
        $savepoints->recordWalFrameWrite(4, 4, true);

        $writer = new SQLiteVfsFileWriter($root);
        $applied = $writer->applySavepointRollback(
            $savepoints,
            'plugin-settings',
            $dirtyDatabase,
            $pageSize,
            $databasePath,
            $wal,
            $walBytes
        );

        $t->same('applied', $applied['status']);
        $t->same($root, $applied['root']);
        $t->same('plugin-settings', $applied['savepoint']);
        $t->same(7, $applied['applied']);
        $t->same(strlen($dirtyDatabase) + 32 + (2 * (24 + $pageSize)), $applied['bytes_written']);
        $t->same(strlen($dirtyDatabase) + 32 + (2 * (24 + $pageSize)), $applied['bytes_truncated']);
        $t->same(0, $applied['files_deleted']);
        $t->same(2, $applied['durable_syncs']);
        $t->same(1, $applied['directory_syncs']);
        $t->same(true, in_array('sqlite-savepoint-page-image-rollback', $applied['dependencies'], true));
        $t->same(true, in_array('sqlite-savepoint-wal-rollback', $applied['dependencies'], true));
        $t->same(true, in_array('vfs-file-write-coordination', $applied['dependencies'], true));
        $t->same(true, in_array('vfs-file-handle-write-application', $applied['dependencies'], true));

        $t->same('plugin-settings', $applied['database_image']['savepoint']);
        $t->same([3, 4], $applied['database_image']['restored_page_numbers']);
        $t->same([1024, 1536], [
            $applied['database_image']['restore_pages'][0]['database_offset'],
            $applied['database_image']['restore_pages'][1]['database_offset'],
        ]);
        $t->same([], $applied['database_image']['missing_page_numbers']);
        $t->same(true, $applied['database_image']['transaction_active_after']);
        $t->same('plugin-settings', $applied['wal_truncation']['savepoint']);
        $t->same(2, $applied['wal_truncation']['rollback_to_frame']);
        $t->same(4, $applied['wal_truncation']['original_frame_count']);
        $t->same(2, $applied['wal_truncation']['retained_frame_count']);
        $t->same(2, $applied['wal_truncation']['discarded_frame_count']);
        $t->same(32 + (2 * (24 + $pageSize)), $applied['wal_truncation']['truncate_to_bytes']);
        $t->same(true, $applied['wal_truncation']['needs_truncate']);
        $t->same([3, 4], [
            $applied['wal_truncation']['discarded_wal_frames'][0]['page_number'],
            $applied['wal_truncation']['discarded_wal_frames'][1]['page_number'],
        ]);
        $t->same([false, true], [
            $applied['wal_truncation']['discarded_wal_frames'][0]['commit_frame'],
            $applied['wal_truncation']['discarded_wal_frames'][1]['commit_frame'],
        ]);

        $t->same('write', $applied['operations'][0]['op']);
        $t->same('restore_savepoint_database_page_images', $applied['operations'][0]['reason']);
        $t->same($databasePath, $applied['operations'][0]['path']);
        $t->same($localDatabase, $applied['operations'][0]['local_path']);
        $t->same(strlen($dirtyDatabase), $applied['operations'][0]['bytes']);
        $t->same('truncate', $applied['operations'][1]['op']);
        $t->same('sync', $applied['operations'][2]['op']);
        $t->same(true, $applied['operations'][2]['durable']);
        $t->same('write', $applied['operations'][3]['op']);
        $t->same($databasePath . '-wal', $applied['operations'][3]['path']);
        $t->same($localWal, $applied['operations'][3]['local_path']);
        $t->same(32 + (2 * (24 + $pageSize)), $applied['operations'][3]['bytes']);
        $t->same('restore_savepoint_wal_prefix', $applied['operations'][3]['reason']);
        $t->same('truncate', $applied['operations'][4]['op']);
        $t->same('truncate_savepoint_wal_frames', $applied['operations'][4]['reason']);
        $t->same('sync', $applied['operations'][5]['op']);
        $t->same('sync_savepoint_wal_rollback', $applied['operations'][5]['reason']);
        $t->same('sync_directory', $applied['operations'][6]['op']);
        $t->same('persist_savepoint_rollback_sidecars', $applied['operations'][6]['reason']);

        $databaseBytes = file_get_contents($localDatabase);
        $t->same(strlen($dirtyDatabase), strlen($databaseBytes));
        $t->same(str_pad('dirty schema after import', $pageSize, "\0"), substr($databaseBytes, 0, $pageSize));
        $t->same(str_pad('dirty app_settings after import', $pageSize, "\0"), substr($databaseBytes, $pageSize, $pageSize));
        $t->same($pageThreeBeforePlugin, substr($databaseBytes, $pageSize * 2, $pageSize));
        $t->same($pageFourBeforeRow, substr($databaseBytes, $pageSize * 3, $pageSize));
        $t->same(false, str_contains($databaseBytes, 'plugin settings dirty row'));
        $t->same(false, str_contains($databaseBytes, 'single option dirty row'));

        $truncatedWalBytes = file_get_contents($localWal);
        $truncatedWal = SQLiteWal::parse($truncatedWalBytes, null, true);
        $t->same(32 + (2 * (24 + $pageSize)), strlen($truncatedWalBytes));
        $t->same(2, $truncatedWal->frameCount());
        $t->same($walFrameOne, $truncatedWal->frames[0]->pageImage);
        $t->same($walFrameTwo, $truncatedWal->frames[1]->pageImage);
        $t->same(false, str_contains($truncatedWalBytes, 'wal plugin draft should disappear'));
        $t->same(false, str_contains($truncatedWalBytes, 'wal row draft should disappear'));

        $imageOnlyRoot = sys_get_temp_dir() . '/port-libsqlite-vfs-savepoint-image-' . bin2hex(random_bytes(4));
        $imageOnly = (new SQLiteVfsFileWriter($imageOnlyRoot))->applySavepointRollback($savepoints, 'single-option-row', $dirtyDatabase, $pageSize, $databasePath);
        $t->same('applied', $imageOnly['status']);
        $t->same(4, $imageOnly['applied']);
        $t->same(1, $imageOnly['durable_syncs']);
        $t->same(null, $imageOnly['wal_truncation']);
        $t->same(false, is_file($imageOnlyRoot . $databasePath . '-wal'));
        $t->same(str_pad('single option before row', $pageSize, "\0"), substr(file_get_contents($imageOnlyRoot . $databasePath), $pageSize * 3, $pageSize));

        $readOnly = new SQLiteVfsFileWriter($root, true);
        $t->throws(LogicException::class, static fn () => $readOnly->applySavepointRollback($savepoints, 'plugin-settings', $dirtyDatabase, $pageSize, $databasePath, $wal, $walBytes));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applySavepointRollback($savepoints, '', $dirtyDatabase, $pageSize, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applySavepointRollback($savepoints, 'plugin-settings', $dirtyDatabase, $pageSize, ''));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applySavepointRollback($savepoints, 'plugin-settings', substr($dirtyDatabase, 1), $pageSize, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applySavepointRollback($savepoints, 'plugin-settings', $dirtyDatabase, $pageSize, $databasePath, $wal));
        $t->throws(InvalidArgumentException::class, static fn () => $writer->applySavepointRollback($savepoints, 'missing', $dirtyDatabase, $pageSize, $databasePath));
    },
    'applies sqlite pager checkpoint transactions atomically through vfs handles' => static function (TestRunner $t) use ($makeFirstPage): void {
        $root = sys_get_temp_dir() . '/port-libsqlite-pager-checkpoint-atomic-' . bin2hex(random_bytes(4));
        $databasePath = '/srv/www/wp-content/database/.ht.sqlite';
        $localDatabase = $root . $databasePath;
        $localWal = $localDatabase . '-wal';
        $pageSize = 512;

        $databaseBytes = $makeFirstPage($pageSize, 3)
            . str_pad('base app_settings table page', $pageSize, "\0")
            . str_pad('base load_policy index page', $pageSize, "\0");

        $salt1 = 0x33445566;
        $salt2 = 0x77889900;
        $walHeaderPrefix = pack('N*', SQLiteWalHeader::MAGIC_BIG_ENDIAN, 3007000, $pageSize, 0, $salt1, $salt2);
        $checksumSeed = SQLiteWal::checksumPair($walHeaderPrefix, false);
        $walBytes = $walHeaderPrefix . pack('N*', $checksumSeed[0], $checksumSeed[1]);
        $appendFrame = static function (string $bytes, array &$seed, int $pageNumber, int $commit, string $pageImage) use ($salt1, $salt2): string {
            $framePrefix = pack('N*', $pageNumber, $commit, $salt1, $salt2);
            $seed = SQLiteWal::checksumPair(substr($framePrefix, 0, 8) . $pageImage, false, $seed[0], $seed[1]);

            return $bytes . $framePrefix . pack('N*', $seed[0], $seed[1]) . $pageImage;
        };
        $walPageTwo = str_pad('checkpointed siteurl option page', $pageSize, "\0");
        $walPageThree = str_pad('checkpointed load_policy index page', $pageSize, "\0");
        $walBytes = $appendFrame($walBytes, $checksumSeed, 2, 0, $walPageTwo);
        $walBytes = $appendFrame($walBytes, $checksumSeed, 3, 3, $walPageThree);
        $wal = SQLiteWal::parse($walBytes, null, true);

        $locks = new SQLiteLockCoordinator();
        $applied = (new SQLiteVfsFileWriter($root))->applyPagerCheckpointTransaction(
            $locks,
            'wp-import-checkpoint',
            $wal,
            $databaseBytes,
            $databasePath,
            'truncate'
        );

        $t->same('applied', $applied['status']);
        $t->same($root, $applied['root']);
        $t->same(true, $applied['atomic']);
        $t->same(true, $applied['locks_released']);
        $t->same([], $locks->holders());
        $t->same(4, $applied['applied']);
        $t->same(strlen($databaseBytes), $applied['bytes_written']);
        $t->same(0, $applied['bytes_truncated']);
        $t->same(0, $applied['files_deleted']);
        $t->same(1, $applied['durable_syncs']);
        $t->same(1, $applied['directory_syncs']);
        $t->same(true, in_array('sqlite-pager-checkpoint-transaction', $applied['dependencies'], true));
        $t->same(true, in_array('sqlite-pager-atomic-checkpoint-apply', $applied['dependencies'], true));
        $t->same(true, in_array('vfs-atomic-rollback-on-write-failure', $applied['dependencies'], true));
        $t->same(true, in_array('vfs-file-handle-write-application', $applied['dependencies'], true));
        $t->same('ready', $applied['transaction']['status']);
        $t->same(true, $applied['transaction']['can_checkpoint']);
        $t->same('truncate', $applied['transaction']['mode']);
        $t->same($databasePath, $applied['transaction']['database_path']);
        $t->same(['shared', 'reserved', 'pending', 'exclusive'], array_column($applied['transaction']['lock_sequence'], 'requested'));
        $t->same(['ready', 'ready', 'ready', 'ready'], array_column($applied['transaction']['lock_sequence'], 'status'));
        $t->same('truncate_wal', $applied['transaction']['write_plan']['wal_action']);
        $t->same(strlen($databaseBytes), $applied['transaction']['write_plan']['database_bytes']);
        $t->same(0, $applied['transaction']['write_plan']['wal_bytes']);
        $t->same('checkpoint_database_pages', $applied['transaction']['write_plan']['operations'][0]['reason']);
        $t->same('sync_checkpointed_database', $applied['transaction']['write_plan']['operations'][1]['reason']);
        $t->same('truncate_reset_wal', $applied['transaction']['write_plan']['operations'][2]['reason']);
        $t->same('persist_database_and_wal_directory_entries', $applied['transaction']['write_plan']['operations'][3]['reason']);
        $t->same('write', $applied['operations'][0]['op']);
        $t->same($databasePath, $applied['operations'][0]['path']);
        $t->same($localDatabase, $applied['operations'][0]['local_path']);
        $t->same(strlen($databaseBytes), $applied['operations'][0]['bytes']);
        $t->same('sync', $applied['operations'][1]['op']);
        $t->same(true, $applied['operations'][1]['durable']);
        $t->same('truncate', $applied['operations'][2]['op']);
        $t->same($databasePath . '-wal', $applied['operations'][2]['path']);
        $t->same($localWal, $applied['operations'][2]['local_path']);
        $t->same(0, $applied['operations'][2]['bytes']);
        $t->same('sync_directory', $applied['operations'][3]['op']);
        $t->same(dirname($databasePath), $applied['operations'][3]['path']);

        $checkpointedDatabase = file_get_contents($localDatabase);
        $t->same(strlen($databaseBytes), strlen($checkpointedDatabase));
        $t->same($walPageTwo, substr($checkpointedDatabase, $pageSize, $pageSize));
        $t->same($walPageThree, substr($checkpointedDatabase, $pageSize * 2, $pageSize));
        $t->same('', file_get_contents($localWal));
        $t->same(false, str_contains($checkpointedDatabase, 'base app_settings table page'));
        $t->same(false, str_contains($checkpointedDatabase, 'base load_policy index page'));

        $blockedLocks = new SQLiteLockCoordinator(['theme-preview-reader' => 'shared']);
        $blocked = (new SQLiteVfsFileWriter($root))->applyPagerCheckpointTransaction(
            $blockedLocks,
            'wp-import-checkpoint',
            $wal,
            $databaseBytes,
            $databasePath,
            'restart',
            null,
            SQLiteBusyHandler::timeout(10, 5)
        );
        $t->same('busy-timeout', $blocked['status']);
        $t->same(0, $blocked['applied']);
        $t->same(false, $blocked['locks_released']);
        $t->same(true, $blocked['atomic']);
        $t->same(false, $blocked['transaction']['can_checkpoint']);
        $t->same('exclusive writer is blocked until readers and writers drain', $blocked['transaction']['reason']);
        $t->same('theme-preview-reader', $blocked['transaction']['lock_sequence'][3]['blocking'][0]['connection']);
        $t->same('shared reader must drain before exclusive lock', $blocked['transaction']['lock_sequence'][3]['blocking'][0]['reason']);
        $t->same([['connection' => 'theme-preview-reader', 'level' => 'shared']], $blockedLocks->holders());

        $failureRoot = sys_get_temp_dir() . '/port-libsqlite-pager-checkpoint-atomic-fail-' . bin2hex(random_bytes(4));
        $failureDatabase = $failureRoot . $databasePath;
        $failureWal = $failureDatabase . '-wal';
        if (!is_dir(dirname($failureDatabase)) && !mkdir(dirname($failureDatabase), 0777, true) && !is_dir(dirname($failureDatabase))) {
            throw new RuntimeException('failed to create test directory');
        }
        $originalDatabase = str_pad('original db image before failed checkpoint', strlen($databaseBytes), "\0");
        file_put_contents($failureDatabase, $originalDatabase);
        mkdir($failureWal, 0777, true);
        $failureLocks = new SQLiteLockCoordinator();
        $failingWriter = new SQLiteVfsFileWriter($failureRoot);

        $t->throws(RuntimeException::class, static fn () => $failingWriter->applyPagerCheckpointTransaction(
            $failureLocks,
            'wp-import-checkpoint',
            $wal,
            $databaseBytes,
            $databasePath,
            'restart'
        ));
        $t->same($originalDatabase, file_get_contents($failureDatabase));
        $t->same(true, is_dir($failureWal));
        $t->same([], $failureLocks->holders());

        $t->throws(LogicException::class, static fn () => (new SQLiteVfsFileWriter($root, true))->applyPagerCheckpointTransaction($locks, 'wp-import-checkpoint', $wal, $databaseBytes, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => (new SQLiteVfsFileWriter($root))->applyPagerCheckpointTransaction($locks, '', $wal, $databaseBytes, $databasePath));
        $t->throws(InvalidArgumentException::class, static fn () => (new SQLiteVfsFileWriter($root))->applyPagerCheckpointTransaction($locks, 'wp-import-checkpoint', $wal, $databaseBytes, ''));
        $t->throws(InvalidArgumentException::class, static fn () => (new SQLiteVfsFileWriter($root))->applyPagerCheckpointTransaction($locks, 'wp-import-checkpoint', $wal, $databaseBytes, $databasePath, 'bad'));
    },
    'dispatches sqlite numeric aggregate semantics' => static function (TestRunner $t): void {
        $values = [10, null, '20bytes', ' 3.5ms', 'not numeric', true, new SQLiteBlobValue('7z')];

        $t->same(7, SQLiteNumericAggregate::countAll($values));
        $t->same(6, SQLiteNumericAggregate::countValue($values));
        $t->same(4, SQLiteNumericAggregate::countDistinct([null, '10', '10', 10, true, 1, new SQLiteBlobValue('10')]));
        $t->same(41.5, SQLiteNumericAggregate::sum($values));
        $t->same(41.5, SQLiteNumericAggregate::total($values));
        $t->same(41.5 / 6, SQLiteNumericAggregate::avg($values));
        $t->same(31.5, SQLiteNumericAggregate::sumDistinct([null, 10, 10, '10', 1, true, ' 3.5ms', new SQLiteBlobValue('7z')]));
        $t->same(31.5, SQLiteNumericAggregate::totalDistinct([null, 10, 10, '10', 1, true, ' 3.5ms', new SQLiteBlobValue('7z')]));
        $t->same(31.5 / 5, SQLiteNumericAggregate::avgDistinct([null, 10, 10, '10', 1, true, ' 3.5ms', new SQLiteBlobValue('7z')]));
        $t->same(null, SQLiteNumericAggregate::sumDistinct([null, null]));
        $t->same(0.0, SQLiteNumericAggregate::totalDistinct([null, null]));
        $t->same(null, SQLiteNumericAggregate::avgDistinct([null, null]));
        $t->same(0, SQLiteNumericAggregate::sumDistinct(['not numeric', 'not numeric']));
        $t->same(null, SQLiteNumericAggregate::sum([null, null]));
        $t->same(0.0, SQLiteNumericAggregate::total([null, null]));
        $t->same(null, SQLiteNumericAggregate::avg([null, null]));
        $t->same(0, SQLiteNumericAggregate::sum(['not numeric']));

        $t->same(2, SQLiteNumericAggregate::min([null, 'alpha', 2, 'beta']));
        $maxBlob = SQLiteNumericAggregate::max([2, 'z', new SQLiteBlobValue('a'), new SQLiteBlobValue('b')]);
        $t->true($maxBlob instanceof SQLiteBlobValue);
        $t->same('b', $maxBlob->bytes);
        $t->same(30, SQLiteNumericAggregate::sumFilter([[10, 1], [20, '2'], [30, 0], [40, null], [50, 'true']]));
        $t->same([10.0, 30.0, 50.0, 70.0], SQLiteNumericAggregate::totalWindow([10, 20, 30, 40], 1, 0));

        $state = new SQLiteNumericAggregateState();
        foreach ([[10, 1], [null, 1], ['20ms', 0], ['5.5', 1], ['nope', 1]] as [$value, $filter]) {
            $state->step($value);
            $state->stepDistinct($value);
            $state->stepFilter($value, $filter);
            $state->stepWindow($value);
        }
        $t->same(5, $state->countAll());
        $t->same(4, $state->countValue());
        $t->same(4, $state->countDistinct());
        $t->same(35.5, $state->sum());
        $t->same(35.5, $state->total());
        $t->same(35.5 / 4, $state->avg());
        $t->same(35.5, $state->sumDistinct());
        $t->same(35.5, $state->totalDistinct());
        $t->same(35.5 / 4, $state->avgDistinct());
        $t->same(10, $state->min());
        $t->same('nope', $state->max());
        $t->same(15.5, $state->sumFiltered());
        $t->same([10.0, 10.0, 20.0, 25.5, 5.5], $state->totalWindowed(1, 0));
        $t->same([
            'rows' => 5,
            'distinctRows' => 5,
            'filteredRows' => 5,
            'windowRows' => 5,
        ], $state->summary());

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteNumericAggregate::sum([['not' => 'scalar']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteNumericAggregate::sumDistinct([['not' => 'scalar']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteNumericAggregate::min([['not' => 'scalar']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteNumericAggregate::totalWindow([1], -1));
    },
    'dispatches sqlite builtin window ranking and value functions' => static function (TestRunner $t): void {
        $orderKeys = [10, 10, 20, 30, 30, 30, 40];

        $t->same([1, 2, 3, 4, 5, 6, 7], SQLiteWindowFunction::rowNumber($orderKeys));
        $t->same([1, 1, 3, 4, 4, 4, 7], SQLiteWindowFunction::rank($orderKeys));
        $t->same([1, 1, 2, 3, 3, 3, 4], SQLiteWindowFunction::denseRank($orderKeys));
        $t->same([0.0, 0.0, 2 / 6, 3 / 6, 3 / 6, 3 / 6, 1.0], SQLiteWindowFunction::percentRank($orderKeys));
        $t->same([2 / 7, 2 / 7, 3 / 7, 6 / 7, 6 / 7, 6 / 7, 1.0], SQLiteWindowFunction::cumeDist($orderKeys));
        $t->same([1, 1, 1, 2, 2, 3, 3], SQLiteWindowFunction::ntile($orderKeys, 3));
        $t->same([1, 2, 3], SQLiteWindowFunction::ntile(['a', 'b', 'c'], 10));
        $t->same([], SQLiteWindowFunction::rowNumber([]));
        $t->same([], SQLiteWindowFunction::ntile([], 3));
        $t->same([0.0], SQLiteWindowFunction::percentRank(['only']));

        $values = ['siteurl', 'home', 'blogname', '_transient_feed'];
        $t->same(['missing', 'siteurl', 'home', 'blogname'], SQLiteWindowFunction::lag($values, 1, 'missing'));
        $t->same(['missing', 'missing', 'siteurl', 'home'], SQLiteWindowFunction::lag($values, 2, 'missing'));
        $t->same(['home', 'blogname', '_transient_feed', 'missing'], SQLiteWindowFunction::lead($values, 1, 'missing'));
        $t->same(['siteurl', 'siteurl', 'siteurl', 'siteurl'], SQLiteWindowFunction::firstValue($values));
        $t->same(['_transient_feed', '_transient_feed', '_transient_feed', '_transient_feed'], SQLiteWindowFunction::lastValue($values));
        $t->same(['blogname', 'blogname', 'blogname', 'blogname'], SQLiteWindowFunction::nthValue($values, 3));
        $t->same([null, null, null, null], SQLiteWindowFunction::nthValue($values, 9));

        $mixedKeys = [null, null, 1, true, '1', new SQLiteBlobValue('1'), new SQLiteBlobValue('1')];
        $t->same([1, 1, 3, 3, 5, 6, 6], SQLiteWindowFunction::rank($mixedKeys));
        $t->same([1, 1, 2, 2, 3, 4, 4], SQLiteWindowFunction::denseRank($mixedKeys));
        $t->same([2 / 7, 2 / 7, 4 / 7, 4 / 7, 5 / 7, 1.0, 1.0], SQLiteWindowFunction::cumeDist($mixedKeys));

        $summary = SQLiteWindowFunction::rankingSummary($orderKeys, 4);
        $t->same([1, 1, 3, 4, 4, 4, 7], $summary['rank']);
        $t->same([1, 1, 2, 2, 3, 3, 4], $summary['ntile']);

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWindowFunction::ntile([1], 0));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWindowFunction::lag([1], 0));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWindowFunction::lead([1], 0));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWindowFunction::nthValue([1], 0));
        $t->same([1, 1, 3], SQLiteWindowFunction::rank([[1, 'a'], [1, 'a'], [1, 'b']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteWindowFunction::rank([[new stdClass()], [1]]));
    },
    'summarizes grouped aggregate result rows with having and order by semantics' => static function (TestRunner $t): void {
        $rows = [
            ['load_policy' => 'yes', 'name' => 'siteurl', 'bytes' => 20],
            ['load_policy' => 'yes', 'name' => 'home', 'bytes' => 20],
            ['load_policy' => 'yes', 'name' => 'blogname', 'bytes' => 9],
            ['load_policy' => 'no', 'name' => '_transient_feed', 'bytes' => 12],
            ['load_policy' => 'no', 'name' => 'empty_cache_key', 'bytes' => 0],
            ['load_policy' => 'no', 'name' => 'legacy_null', 'bytes' => null],
            ['load_policy' => null, 'name' => 'orphaned', 'bytes' => 3],
            ['load_policy' => null, 'name' => 'orphaned-again', 'bytes' => 7],
        ];

        $summary = SQLiteGroupedAggregate::summarize($rows, 'load_policy', 'bytes');
        $orderedByGroup = SQLiteGroupedAggregate::orderBy($summary, 'group');

        $t->same(null, $orderedByGroup[0]['group']);
        $t->same(2, $orderedByGroup[0]['countAll']);
        $t->same(2, $orderedByGroup[0]['countValue']);
        $t->same(10, $orderedByGroup[0]['sum']);
        $t->same(5.0, $orderedByGroup[0]['avg']);
        $t->same('3|7', $orderedByGroup[0]['groupConcat']);

        $t->same('no', $orderedByGroup[1]['group']);
        $t->same(3, $orderedByGroup[1]['countAll']);
        $t->same(2, $orderedByGroup[1]['countValue']);
        $t->same(2, $orderedByGroup[1]['countDistinct']);
        $t->same(12, $orderedByGroup[1]['sum']);
        $t->same(12.0, $orderedByGroup[1]['total']);
        $t->same(6.0, $orderedByGroup[1]['avg']);
        $t->same(0, $orderedByGroup[1]['min']);
        $t->same(12, $orderedByGroup[1]['max']);
        $t->same('12|0', $orderedByGroup[1]['groupConcat']);

        $t->same('yes', $orderedByGroup[2]['group']);
        $t->same(3, $orderedByGroup[2]['countAll']);
        $t->same(49, $orderedByGroup[2]['sum']);
        $t->same(2, $orderedByGroup[2]['countDistinct']);

        $havingCount = SQLiteGroupedAggregate::havingCountAtLeast($summary, 3);
        $t->same(['yes', 'no'], array_column($havingCount, 'group'));

        $havingSum = SQLiteGroupedAggregate::havingSumGreaterThan($summary, 12);
        $t->same(['yes'], array_column($havingSum, 'group'));

        $orderedBySum = SQLiteGroupedAggregate::orderBy($summary, 'sum', 'DESC');
        $t->same(['yes', 'no', null], array_column($orderedBySum, 'group'));
        $t->same([49, 12, 10], array_column($orderedBySum, 'sum'));

        $blobSummary = SQLiteGroupedAggregate::summarize([
            ['bucket' => new SQLiteBlobValue('a'), 'value' => 1],
            ['bucket' => new SQLiteBlobValue('a'), 'value' => 2],
            ['bucket' => new SQLiteBlobValue('b'), 'value' => 4],
        ], 'bucket', 'value');
        $t->same(2, $blobSummary[0]['countAll']);
        $t->same(3, $blobSummary[0]['sum']);
        $t->same(4, $blobSummary[1]['sum']);

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteGroupedAggregate::summarize([['load_policy' => 'yes']], 'load_policy', 'bytes'));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteGroupedAggregate::summarize([['load_policy' => [] , 'bytes' => 1]], 'load_policy', 'bytes'));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteGroupedAggregate::orderBy($summary, 'missing'));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteGroupedAggregate::orderBy($summary, 'sum', 'SIDEWAYS'));
    },
    'applies sqlite select distinct order by limit and offset result semantics' => static function (TestRunner $t): void {
        $rows = [
            ['load_policy' => 'yes', 'key_name' => 'siteurl', 'bytes' => 20, 'payload' => new SQLiteBlobValue('b')],
            ['load_policy' => 'yes', 'key_name' => 'home', 'bytes' => 20, 'payload' => new SQLiteBlobValue('a')],
            ['load_policy' => 'yes', 'key_name' => 'home', 'bytes' => 20, 'payload' => new SQLiteBlobValue('a')],
            ['load_policy' => 'no', 'key_name' => '_transient_feed', 'bytes' => 12, 'payload' => null],
            ['load_policy' => 'no', 'key_name' => 'empty_cache_key', 'bytes' => 0, 'payload' => false],
            ['load_policy' => null, 'key_name' => 'orphaned', 'bytes' => null, 'payload' => true],
            ['load_policy' => null, 'key_name' => 'orphaned', 'bytes' => null, 'payload' => true],
        ];

        $distinct = SQLiteSelectResult::distinct($rows, ['load_policy', 'key_name', 'bytes', 'payload']);
        $t->same(5, count($distinct));
        $t->same(['siteurl', 'home', '_transient_feed', 'empty_cache_key', 'orphaned'], array_column($distinct, 'key_name'));

        $ordered = SQLiteSelectResult::orderBy($distinct, [
            ['column' => 'load_policy'],
            ['column' => 'bytes', 'direction' => 'DESC'],
            ['column' => 'key_name'],
        ]);
        $t->same(['orphaned', '_transient_feed', 'empty_cache_key', 'home', 'siteurl'], array_column($ordered, 'key_name'));
        $t->same([null, 'no', 'no', 'yes', 'yes'], array_column($ordered, 'load_policy'));
        $t->same([null, 12, 0, 20, 20], array_column($ordered, 'bytes'));

        $descending = SQLiteSelectResult::orderBy($distinct, [
            ['column' => 'bytes', 'direction' => 'DESC'],
            ['column' => 'key_name', 'direction' => 'ASC'],
        ]);
        $t->same(['home', 'siteurl', '_transient_feed', 'empty_cache_key', 'orphaned'], array_column($descending, 'key_name'));

        $blobOrder = SQLiteSelectResult::orderBy($distinct, [['column' => 'payload']]);
        $payloads = array_map(
            static fn (mixed $value): mixed => $value instanceof SQLiteBlobValue ? $value->bytes : $value,
            array_column($blobOrder, 'payload')
        );
        $t->same([null, false, true, 'a', 'b'], $payloads);

        $paged = SQLiteSelectResult::limitOffset($ordered, 2, 1);
        $t->same(['_transient_feed', 'empty_cache_key'], array_column($paged, 'key_name'));
        $t->same(['home', 'siteurl'], array_column(SQLiteSelectResult::limitOffset($ordered, -1, 3), 'key_name'));
        $t->same([], SQLiteSelectResult::limitOffset($ordered, 2, 20));

        $executed = SQLiteSelectResult::execute($rows, ['load_policy', 'key_name'], [
            ['column' => 'load_policy', 'direction' => 'DESC'],
            ['column' => 'key_name'],
        ], 3, 1);
        $t->same(['siteurl', '_transient_feed', 'empty_cache_key'], array_column($executed, 'key_name'));
        $t->same(['yes', 'no', 'no'], array_column($executed, 'load_policy'));

        $stableRows = [
            ['name' => 'first', 'rank' => 1],
            ['name' => 'second', 'rank' => 1],
            ['name' => 'third', 'rank' => 1],
        ];
        $t->same(['first', 'second', 'third'], array_column(SQLiteSelectResult::orderBy($stableRows, [['column' => 'rank']]), 'name'));

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::distinct($rows, []));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::distinct([['load_policy' => []]], ['load_policy']));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::distinct([['load_policy' => 'yes']], ['missing']));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::orderBy($rows, [['column' => 'missing']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::orderBy($rows, [['column' => 'bytes', 'direction' => 'SIDEWAYS']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::orderBy([['bytes' => []]], [['column' => 'bytes']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::limitOffset($rows, 1, -1));
    },
    'filters sqlite select rows with exists and in subquery semantics' => static function (TestRunner $t): void {
        $options = [
            ['setting_id' => 1, 'key_name' => 'siteurl', 'load_policy' => 'yes', 'payload' => new SQLiteBlobValue('same')],
            ['setting_id' => 2, 'key_name' => 'home', 'load_policy' => 'yes', 'payload' => new SQLiteBlobValue('same')],
            ['setting_id' => 3, 'key_name' => 'blogname', 'load_policy' => 'yes', 'payload' => new SQLiteBlobValue('blog')],
            ['setting_id' => 4, 'key_name' => '_transient_feed', 'load_policy' => 'no', 'payload' => null],
            ['setting_id' => 5, 'key_name' => 'orphaned', 'load_policy' => null, 'payload' => true],
        ];
        $metadata = [
            ['setting_id' => 1, 'meta_key' => 'network'],
            ['setting_id' => 1, 'meta_key' => 'public'],
            ['setting_id' => 3, 'meta_key' => 'public'],
            ['setting_id' => null, 'meta_key' => 'ignored-null'],
            ['setting_id' => 8, 'meta_key' => 'unused'],
        ];

        $public = SQLiteSelectResult::whereExists(
            $options,
            static fn (array $row): array => array_values(array_filter(
                $metadata,
                static fn (array $meta): bool => $meta['setting_id'] === $row['setting_id'] && $meta['meta_key'] === 'public'
            ))
        );
        $t->same(['siteurl', 'blogname'], array_column($public, 'key_name'));

        $withoutMetadata = SQLiteSelectResult::whereExists(
            $options,
            static fn (array $row): array => array_values(array_filter(
                $metadata,
                static fn (array $meta): bool => $meta['setting_id'] === $row['setting_id']
            )),
            true
        );
        $t->same(['home', '_transient_feed', 'orphaned'], array_column($withoutMetadata, 'key_name'));

        $networkOrPublicIds = SQLiteSelectResult::whereIn($options, 'setting_id', array_column($metadata, 'setting_id'));
        $t->same(['siteurl', 'blogname'], array_column($networkOrPublicIds, 'key_name'));
        $t->same([1, 3], array_column($networkOrPublicIds, 'setting_id'));

        $allowedNames = SQLiteSelectResult::whereIn($options, 'key_name', ['home', '_transient_feed', 'missing']);
        $t->same(['home', '_transient_feed'], array_column($allowedNames, 'key_name'));

        $binaryPayloads = SQLiteSelectResult::whereIn($options, 'payload', [new SQLiteBlobValue('same')]);
        $t->same(['siteurl', 'home'], array_column($binaryPayloads, 'key_name'));

        $notSelectedWithoutNull = SQLiteSelectResult::whereIn($options, 'key_name', ['siteurl', 'blogname'], true);
        $t->same(['home', '_transient_feed', 'orphaned'], array_column($notSelectedWithoutNull, 'key_name'));

        $notSelectedWithNull = SQLiteSelectResult::whereIn($options, 'key_name', ['siteurl', null], true);
        $t->same([], $notSelectedWithNull);

        $notSelectedNullableLhs = SQLiteSelectResult::whereIn($options, 'load_policy', ['yes'], true);
        $t->same(['_transient_feed'], array_column($notSelectedNullableLhs, 'key_name'));

        $emptyIn = SQLiteSelectResult::whereIn($options, 'key_name', []);
        $t->same([], $emptyIn);

        $emptyNotIn = SQLiteSelectResult::whereIn($options, 'key_name', [], true);
        $t->same(['siteurl', 'home', 'blogname', '_transient_feed', 'orphaned'], array_column($emptyNotIn, 'key_name'));

        $emptyExists = SQLiteSelectResult::whereExists($options, static fn (array $row): array => []);
        $t->same([], $emptyExists);

        $constantExists = SQLiteSelectResult::whereExists($options, static fn (array $row): array => [['ignored' => null]]);
        $t->same(['siteurl', 'home', 'blogname', '_transient_feed', 'orphaned'], array_column($constantExists, 'key_name'));

        $executed = SQLiteSelectResult::execute(
            SQLiteSelectResult::whereIn($public, 'key_name', ['siteurl', 'blogname']),
            null,
            [['column' => 'key_name', 'direction' => 'DESC']],
            1
        );
        $t->same(['siteurl'], array_column($executed, 'key_name'));

        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::whereIn($options, '', ['siteurl']));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::whereIn([['key_name' => 'siteurl']], 'missing', ['siteurl']));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::whereIn($options, 'key_name', [['bad']]));
        $t->throws(InvalidArgumentException::class, static fn () => SQLiteSelectResult::whereIn([['key_name' => []]], 'key_name', ['siteurl']));
    },
    'executes bounded sqlite select sql text with correlated subqueries' => static function (TestRunner $t): void {
        $options = [
            ['setting_id' => 1, 'key_name' => 'siteurl', 'load_policy' => 'yes', 'bytes' => 24],
            ['setting_id' => 2, 'key_name' => 'home', 'load_policy' => 'yes', 'bytes' => 24],
            ['setting_id' => 3, 'key_name' => 'blogname', 'load_policy' => 'yes', 'bytes' => 9],
            ['setting_id' => 4, 'key_name' => '_transient_feed', 'load_policy' => 'no', 'bytes' => 12],
            ['setting_id' => 5, 'key_name' => '_site_transient_update_plugins', 'load_policy' => 'no', 'bytes' => 110],
            ['setting_id' => 6, 'key_name' => 'orphaned', 'load_policy' => null, 'bytes' => 3],
        ];
        $metadata = [
            ['meta_setting_id' => 1, 'meta_key' => 'public', 'meta_value' => '1'],
            ['meta_setting_id' => 1, 'meta_key' => 'network', 'meta_value' => '1'],
            ['meta_setting_id' => 3, 'meta_key' => 'public', 'meta_value' => '1'],
            ['meta_setting_id' => 4, 'meta_key' => 'expired', 'meta_value' => '1'],
            ['meta_setting_id' => 5, 'meta_key' => 'plugin', 'meta_value' => 'cache'],
            ['meta_setting_id' => null, 'meta_key' => 'ignored-null', 'meta_value' => 'x'],
        ];

        $publicRows = SQLiteSelectSql::execute(
            "SELECT setting_id, key_name FROM app_settings WHERE EXISTS (SELECT meta_key FROM option_meta WHERE meta_setting_id = setting_id AND meta_key = 'public') ORDER BY setting_id",
            ['app_settings' => $options, 'option_meta' => $metadata],
        );
        $t->same(2, count($publicRows));
        $t->same([1, 3], array_column($publicRows, 'setting_id'));
        $t->same(['siteurl', 'blogname'], array_column($publicRows, 'key_name'));
        $t->same(['setting_id', 'key_name'], array_keys($publicRows[0]));
        $t->same(1, $publicRows[0]['setting_id']);
        $t->same('siteurl', $publicRows[0]['key_name']);
        $t->same(3, $publicRows[1]['setting_id']);
        $t->same('blogname', $publicRows[1]['key_name']);

        $withoutMetadataRows = SQLiteSelectSql::execute(
            "SELECT setting_id, key_name FROM app_settings WHERE NOT EXISTS (SELECT meta_key FROM option_meta WHERE meta_setting_id = setting_id) ORDER BY setting_id",
            ['app_settings' => $options, 'option_meta' => $metadata],
        );
        $t->same(2, count($withoutMetadataRows));
        $t->same(['home', 'orphaned'], array_column($withoutMetadataRows, 'key_name'));
        $t->same([2, 6], array_column($withoutMetadataRows, 'setting_id'));
        $t->same(['setting_id', 'key_name'], array_keys($withoutMetadataRows[0]));
        $t->same('home', $withoutMetadataRows[0]['key_name']);
        $t->same('orphaned', $withoutMetadataRows[1]['key_name']);

        $inRows = SQLiteSelectSql::execute(
            "SELECT key_name, bytes FROM app_settings WHERE setting_id IN (SELECT meta_setting_id FROM option_meta WHERE meta_key IN ('public', 'plugin')) ORDER BY bytes DESC, key_name",
            ['app_settings' => $options, 'option_meta' => $metadata],
        );
        $t->same(3, count($inRows));
