    'executes bounded sqlite update from current conflict sql text' => static function (TestRunner $t): void {
        $options = [
            ['setting_id' => 1, 'key_name' => 'siteurl', 'key_value' => 'https://example.test', 'load_policy' => 'yes', 'bytes' => 24],
