            ['setting_id' => 3, 'key_name' => 'blogname', 'key_value' => 'Example Site', 'load_policy' => 'yes', 'bytes' => 9],
            ['setting_id' => 4, 'key_name' => '_transient_feed', 'key_value' => 'cached', 'load_policy' => 'no', 'bytes' => 12],
