        ];
        $staging = [
            ['setting_id' => 2, 'new_name' => 'home_preview', 'new_value' => 'draft-home', 'seq' => 1],
            ['setting_id' => 2, 'new_name' => 'home_current', 'new_value' => 'current-home', 'seq' => 2],
