        $t->same(['home_current', 'legacy_name'], array_column($plan['updates'], 'key_name'));
        $t->same(['current-home', 'current-blog'], array_column($plan['updates'], 'key_value'));
        $t->same([12, 12], array_column($plan['updates'], 'bytes'));
