        $t->same(['name', 'bytes'], array_keys($chainRows[0]));
        $t->same('home', $chainRows[0]['name']);
        $t->same(24, $chainRows[0]['bytes']);
        $t->same('blogname', $chainRows[2]['name']);

        $withRows = SQLiteSelectSql::execute(
